  @override
  String get adderallMilestone3Description =>
      'Les symptômes de sevrage atteignent leur intensité maximale. Vous pouvez ressentir une forte fatigue, de l\'irritabilité et des difficultés de concentration. C\'est la partie la plus difficile, mais la situation s\'améliore ensuite. Envisagez de vous tourner vers votre réseau de soutien.';

  @override
  String get adderallMilestone7Title =>
      'Une semaine : amélioration des symptômes physiques';

  @override
  String get adderallMilestone7Description =>
      'Les pires symptômes physiques du sevrage commencent à s\'estomper. Le sommeil commence à se normaliser et l\'énergie revient progressivement. Votre corps s\'adapte à fonctionner sans stimulants.';

  @override
  String get adderallMilestone14Title =>
