  @override
  String get adderallMilestone30Description =>
      'Votre cerveau récupère activement. La production naturelle de dopamine s\'améliore, et vous pouvez remarquer une meilleure concentration et davantage de motivation sans médicament. La qualité du sommeil et l\'appétit reviennent à des schémas normaux.';

  @override
