  @override
  String get benzoMilestone14Title => 'Pic du sevrage aigu';

  @override
  String get benzoMilestone14Description =>
      'Les symptômes de sevrage aigu atteignent généralement leur maximum au cours des deux premières semaines. Vous pouvez ressentir de l\'anxiété, des troubles du sommeil et un inconfort physique. Bien que difficiles, ces symptômes indiquent que votre cerveau commence à récupérer et à se rééquilibrer.';

  @override
  String get benzoMilestone60Title =>
      'Amélioration de l\'architecture du sommeil';

  @override
  String get benzoMilestone60Description =>
      'Les études montrent qu\'après 2 mois, vos rythmes naturels de sommeil commencent à se rétablir. Le sommeil lent augmente et sa qualité s\'améliore par rapport à la période de prise de benzodiazépines, même si l\'efficacité globale du sommeil peut encore être en récupération.';

  @override
  String get benzoMilestone90Title => 'Stabilisation de la santé physique';

  @override
  String get benzoMilestone90Description =>
      'Vers 3 mois, de nombreux symptômes physiques du sevrage se sont nettement améliorés. Votre corps continue de s\'adapter à fonctionner sans médicament. L\'anxiété et l\'humeur peuvent encore fluctuer, mais le fonctionnement général s\'améliore.';

  @override
  String get benzoMilestone180Title =>
