  @override
  String get benzoMilestone180Description =>
      'À six mois, la mémoire et l\'attention montrent une amélioration mesurable. Les recherches observent une récupération de nombreuses capacités cognitives, avec des progrès qui se poursuivent au-delà de six mois.';

  @override
  String get benzoMilestone365Title => 'Un an de guérison';

  @override
  String get benzoMilestone365Description =>
      'Après un an, des améliorations importantes du bien-être mental et physique deviennent évidentes. Beaucoup rapportent moins d\'anxiété, un meilleur sommeil et une meilleure santé générale qu\'au cours d\'une utilisation prolongée de benzodiazépines. La récupération cérébrale se poursuit.';

  @override
  String get benzoMilestone540Title => 'La récupération cérébrale continue';

  @override
  String get benzoMilestone540Description =>
      'À 18 mois, la mémoire, l\'attention et la clarté mentale continuent de s\'améliorer. Le système GABA qui apaise le cerveau a eu bien plus d\'un an pour se stabiliser, tandis que le cerveau continue à construire des schémas plus sains.';

  @override
  String get benzoMilestone730Title => 'Deux ans : progrès majeurs';

  @override
  String get benzoMilestone730Description =>
