  @override
  String get alcoholMilestone90Description =>
      'Les trois premiers mois apportent des progrès majeurs pour la mémoire, la concentration et la prise de décision, avec une récupération qui se poursuit pendant les mois suivants.';

  @override
  String get alcoholMilestone180Title =>
      'Le volume et le fonctionnement du cerveau continuent de récupérer';

  @override
  String get alcoholMilestone180Description =>
      'Six mois de sobriété donnent au cerveau un temps prolongé pour récupérer. Le volume cérébral et les capacités de réflexion continuent de s\'améliorer.';

  @override
  String get alcoholMilestone365Title =>
      'La réduction du risque de cancer peut commencer';

  @override
  String get alcoholMilestone365Description =>
      'Une année d\'abstinence peut commencer à réduire le risque de cancer. L\'alcool augmente clairement le risque de plusieurs cancers (foie, sein, colorectal, œsophage), mais la recherche sur le délai de réduction du risque est encore en cours et varie selon le type de cancer.';

  @override
  String get smokingMilestone1Title => 'Le monoxyde de carbone est éliminé';

  @override
  String get smokingMilestone1Description =>
      'Votre sang respire à nouveau ! En 24 heures, le taux de monoxyde de carbone revient à la normale et le niveau d\'oxygène augmente. Votre cœur n\'a plus besoin de travailler davantage pour faire circuler un sang chargé de toxines.';

  @override
  String get smokingMilestone3Title => 'Le sevrage nicotinique atteint son pic';

  @override
  String get smokingMilestone3Description =>
      'Le monstre de la nicotine est au plus fort, mais vous êtes en train de gagner ! Toute la nicotine a quitté votre organisme. Les envies les plus fortes surviennent maintenant, mais elles sont aussi le passage vers la liberté.';

  @override
  String get smokingMilestone7Title =>
      'Le goût et l\'odorat s\'améliorent fortement';

  @override
  String get smokingMilestone7Description =>
      'La nourriture va redevenir une aventure ! Le tabac endommage les papilles gustatives et les récepteurs olfactifs. Après une semaine, vous redécouvrez des saveurs que vous aviez oubliées. Préparez-vous à vraiment apprécier vos repas !';

  @override
  String get smokingMilestone14Title =>
      'La circulation et la marche s\'améliorent';

  @override
  String get smokingMilestone14Description =>
      'Vos jambes vous remercient à chaque pas ! La circulation sanguine s\'améliore nettement, rendant la marche et l\'exercice sensiblement plus faciles. Ces escaliers paraissent déjà moins intimidants, non ?';

  @override
  String get smokingMilestone30Title => 'La fonction pulmonaire augmente';

  @override
  String get smokingMilestone30Description =>
      'Vos poumons font leur grand retour ! Les cils bronchiques ont repoussé et évacuent des années de goudron et de débris. La capacité pulmonaire augmente nettement et la toux du fumeur appartient au passé.';

  @override
  String get smokingMilestone90Title =>
      'Le risque d\'infarctus diminue nettement';

  @override
  String get smokingMilestone90Description =>
      'Votre cœur vous remercie ! Après trois mois sans tabac, votre risque cardiovasculaire a déjà sensiblement diminué. Votre système cardiovasculaire récupère plus vite que vous ne l\'imaginez.';

  @override
  String get smokingMilestone180Title => 'Le système immunitaire se renforce';

  @override
  String get smokingMilestone180Description =>
      'Votre système immunitaire vient de passer au niveau supérieur ! Après six mois sans tabac, vos globules blancs ont retrouvé toute leur efficacité et combattent les infections comme ils sont faits pour le faire.';

  @override
  String get smokingMilestone365Title => 'Le risque d\'AVC diminue nettement';

  @override
  String get smokingMilestone365Description =>
      'Une année entière de liberté ! Votre risque d\'AVC a fortement diminué et vos vaisseaux sanguins récupèrent remarquablement. Vous avez offert à votre cerveau une meilleure circulation et davantage de protection.';

  @override
  String get smokingMilestone1825Title => 'Le risque de cancer chute (5 ans)';

  @override
  String get smokingMilestone1825Description =>
      'Cinq ans de victoire ! Votre risque de cancers de la bouche, de la gorge, de l\'œsophage et de la vessie a diminué de moitié. Le risque de cancer du poumon a lui aussi nettement baissé. Vos cellules ont eu le temps de se réparer et de se régénérer.';

  @override
  String get vapingMilestone1Title =>
      'Les envies de nicotine atteignent leur pic';

  @override
  String get vapingMilestone1Description =>
      'Votre cerveau réclame sa nicotine, mais vous êtes déjà en train de gagner ! En 24 heures, le niveau de nicotine chute fortement. Les envies les plus intenses surviennent maintenant, mais ce sont aussi les plus importantes à dépasser.';

  @override
  String get vapingMilestone3Title => 'La respiration s\'améliore';

  @override
  String get vapingMilestone3Description =>
      'Vos poumons respirent mieux ! Les bronches commencent à se détendre et la capacité pulmonaire à s\'améliorer. Cette sensation d\'oppression liée au vapotage commence déjà à diminuer.';

  @override
  String get vapingMilestone7Title => 'Le goût et l\'odorat reviennent';

  @override
  String get vapingMilestone7Description =>
      'Les aliments vont retrouver toute leur saveur ! La nicotine atténue le goût et l\'odorat. Après une semaine, vos sens font leur grand retour.';

  @override
  String get vapingMilestone14Title => 'La circulation s\'améliore';

  @override
  String get vapingMilestone14Description =>
      'Votre sang circule bien mieux ! La nicotine contracte les vaisseaux sanguins, mais après deux semaines sans vapotage, votre circulation s\'améliore nettement. Adieu les mains et les pieds froids !';

  @override
  String get vapingMilestone30Title => 'Récupération de la fonction pulmonaire';

  @override
  String get vapingMilestone30Description =>
      'Vos poumons ont de quoi célébrer ! Les cils bronchiques, ces minuscules nettoyeurs des poumons, se sont régénérés et la fonction pulmonaire s\'est nettement améliorée. La toux du matin appartient au passé !';

  @override
  String get vapingMilestone60Title => 'Le niveau d\'anxiété se normalise';

  @override
  String get vapingMilestone60Description =>
      'Surprise : le vapotage aggravait l\'anxiété au lieu de l\'apaiser ! Après deux mois, votre niveau habituel d\'anxiété est plus bas et votre système nerveux se stabilise.';

  @override
  String get vapingMilestone90Title =>
      'La concentration et la mémoire s\'affinent';

  @override
  String get vapingMilestone90Description =>
      'Le brouillard mental s\'est dissipé ! Après trois mois sans nicotine, votre concentration, votre mémoire et votre clarté mentale se sont nettement améliorées. Comme si votre mémoire vive mentale avait été augmentée.';

  @override
  String get vapingMilestone180Title =>
      'Récupération de la santé bucco-dentaire';

  @override
  String get vapingMilestone180Description =>
      'Votre bouche vous remercie ! Après six mois sans vapotage, l\'inflammation des gencives diminue, les taches sur les dents s\'estompent et votre risque de problèmes bucco-dentaires baisse nettement.';

  @override
  String get vapingMilestone365Title => 'Réduction du risque cardiovasculaire';

  @override
  String get vapingMilestone365Description =>
      'Votre cœur est réellement plus fort ! Après une année entière, votre risque de maladie cardiaque a nettement diminué. Votre système cardiovasculaire a récupéré des agressions quotidiennes de la nicotine.';

  @override
  String get marijuanaMilestone1Title => 'Début des symptômes de sevrage';

  @override
  String get marijuanaMilestone1Description =>
      'Votre cerveau s\'adapte à la vie sans THC ! Dans les 24 à 48 heures, vous pouvez ressentir de l\'irritabilité, de l\'anxiété ou des troubles du sommeil. C\'est tout à fait normal : vos récepteurs cannabinoïdes commencent à se réinitialiser.';

  @override
  String get marijuanaMilestone3Title => 'Pic des symptômes physiques';

  @override
  String get marijuanaMilestone3Description =>
      'Vous êtes au point le plus difficile, mais la suite va s\'améliorer ! Les jours 2 à 6 correspondent généralement au pic du sevrage, avec maux de tête, sueurs et changements d\'humeur. Votre corps travaille à retrouver son équilibre.';

  @override
  String get marijuanaMilestone7Title => 'Le sommeil s\'améliore';

  @override
  String get marijuanaMilestone7Description =>
      'Les bonnes nuits reviennent ! Après une semaine sans cannabis, votre architecture naturelle du sommeil commence à se normaliser. Le sommeil paradoxal rebondit, entraînant des rêves plus vifs et un repos de meilleure qualité.';

  @override
  String get marijuanaMilestone14Title => 'Fin du sevrage aigu';

  @override
  String get marijuanaMilestone14Description =>
      'La tempête est passée ! La plupart des symptômes physiques diminuent nettement après deux semaines. Votre humeur se stabilise et le quotidien devient beaucoup plus facile. Le plus dur est derrière vous.';

  @override
  String get marijuanaMilestone30Title => 'La mémoire s\'améliore';

  @override
  String get marijuanaMilestone30Description =>
      'Le brouillard mental se dissipe ! Les recherches montrent que l\'apprentissage verbal et la mémoire commencent à s\'améliorer nettement après l\'arrêt du cannabis. L\'hippocampe, essentiel à la formation des souvenirs, fonctionne mieux.';

  @override
  String get marijuanaMilestone60Title => 'La concentration s\'affine';

  @override
  String get marijuanaMilestone60Description =>
      'Mode concentration activé ! Après deux mois sans cannabis, votre capacité à vous concentrer et à maintenir votre attention s\'améliore sensiblement. Les tâches professionnelles et les études deviennent plus faciles à gérer.';

  @override
  String get marijuanaMilestone90Title => 'Le retour d\'une humeur stable';

  @override
  String get marijuanaMilestone90Description =>
      'Trois mois sans cannabis apportent une humeur plus stable, moins d\'anxiété et un meilleur contrôle du stress. Votre état émotionnel s\'installe dans un nouvel équilibre plus sain.';

  @override
  String get marijuanaMilestone180Title =>
      'La planification et la prise de décision récupèrent';

  @override
  String get marijuanaMilestone180Description =>
      'Votre directeur mental reprend les commandes ! Six mois sans cannabis apportent de grands progrès en matière de planification, de prise de décision et de résolution de problèmes.';

  @override
  String get marijuanaMilestone365Title =>
      'Restauration de la structure cérébrale';

  @override
  String get marijuanaMilestone365Description =>
      'Une année sans cannabis donne aux régions cérébrales liées à la mémoire beaucoup de temps pour récupérer. Les progrès d\'apprentissage et de mémoire font désormais partie de votre nouvelle normalité.';

  @override
  String get opioidMilestone1Title => 'Début du sevrage aigu';

  @override
  String get opioidMilestone1Description =>
      'La partie la plus difficile commence maintenant, mais vous n\'êtes pas seul. Les symptômes aigus culminent pendant les 24 à 72 premières heures. Votre corps commence son processus de guérison. Un accompagnement médical professionnel est essentiel pendant cette phase.';

  @override
  String get opioidMilestone7Title =>
      'Les symptômes physiques culminent puis diminuent';

  @override
  String get opioidMilestone7Description =>
      'Vous avez traversé la tempête ! Les pires symptômes physiques culminent généralement entre les jours 3 et 5 et commencent à diminuer vers le jour 7. Votre corps travaille à rétablir son équilibre naturel.';

  @override
  String get opioidMilestone14Title => 'Le sommeil commence à s\'améliorer';

  @override
  String get opioidMilestone14Description =>
      'Les bonnes nuits reviennent ! Après deux semaines, votre architecture naturelle du sommeil commence à se restaurer. Les opioïdes perturbent le sommeil paradoxal, mais votre cerveau réapprend à rêver naturellement.';

  @override
  String get opioidMilestone30Title =>
      'La pensée et la mémoire commencent à récupérer';

  @override
  String get opioidMilestone30Description =>
      'Le brouillard mental se lève ! Après un mois d\'abstinence, la mémoire, la prise de décision et la clarté mentale s\'améliorent à mesure que la partie frontale du cerveau récupère des modifications liées aux opioïdes.';

  @override
  String get opioidMilestone60Title => 'La régulation émotionnelle s\'améliore';

  @override
  String get opioidMilestone60Description =>
      'Vos émotions retrouvent leur rythme naturel. Après deux mois de rétablissement, le système de récompense de votre cerveau commence à répondre de nouveau aux plaisirs du quotidien. Les montagnes russes émotionnelles se stabilisent.';

  @override
  String get opioidMilestone90Title =>
      'La fonction dopaminergique récupère nettement';

  @override
  String get opioidMilestone90Description =>
      'Le système de récompense de votre cerveau fait son grand retour ! Après trois mois, la fonction dopaminergique s\'est nettement améliorée. Les activités naturelles recommencent à procurer du plaisir : nourriture, musique, relations.';

  @override
  String get opioidMilestone180Title => 'Le système immunitaire se renforce';

  @override
  String get opioidMilestone180Description =>
      'Votre système immunitaire reprend du service ! Après six mois de rétablissement, les défenses naturelles de votre corps se sont nettement renforcées. Vous êtes mieux armé contre les infections et les maladies.';

  @override
  String get opioidMilestone365Title =>
      'La plasticité et la structure cérébrales s\'améliorent';

  @override
  String get opioidMilestone365Description =>
      'Votre cerveau s\'est activement reconstruit ! Une année entière de rétablissement apporte des améliorations importantes de la structure cérébrale et de la plasticité neuronale. Les changements liés à une consommation chronique d\'opioïdes continuent de guérir.';

  @override
  String get opioidMilestone730Title =>
      'Stabilité du rétablissement à long terme (2 ans)';

  @override
  String get opioidMilestone730Description =>
      'Deux ans de force et de résilience ! Vous avez créé de nouveaux circuits neuronaux, de nouvelles stratégies d\'adaptation et de nouvelles habitudes de vie. Les recherches montrent qu\'atteindre cette étape réduit fortement le risque de rechute. Vous êtes un combattant du rétablissement !';

  @override
  String get socialMediaMilestone1Title =>
      'Premier jour de détox numérique ! 🎯';

  @override
  String get socialMediaMilestone1Description =>
      'Vous avez officiellement commencé à recâbler votre cerveau ! Les recherches montrent que le simple fait de penser à consulter les réseaux sociaux active les mêmes circuits neuronaux que les dépendances. Mais vous brisez déjà le cycle — bravo !';

  @override
  String get socialMediaMilestone3Title => 'FOMO ? Plutôt FO-NON ! 😎';

  @override
  String get socialMediaMilestone3Description =>
      'Trois jours et les pensées anxieuses du type « qu\'est-ce que je rate ? » diminuent déjà. Vous apprenez à votre cerveau que la vraie vie est bien plus intéressante que des fils d\'actualité soigneusement mis en scène !';

  @override
  String get socialMediaMilestone7Title =>
      'Capacité d\'attention : poisson rouge → humain 🧠';

  @override
  String get socialMediaMilestone7Description =>
      'Première semaine terminée ! Votre capacité à rester concentré sans vérifier votre téléphone toutes les quelques minutes s\'améliore déjà. Les études montrent que notre cerveau recherche les décharges de dopamine des notifications — mais vous lui apprenez à trouver des récompenses ailleurs !';

  @override
  String get socialMediaMilestone14Title =>
      'Dormez comme un bébé, pas comme un zombie 😴';

  @override
  String get socialMediaMilestone14Description =>
      'Deux semaines sans faire défiler avant de dormir = un sommeil de meilleure qualité ! La lumière bleue des écrans réduit la production de mélatonine, mais vos rythmes naturels de sommeil reviennent en force.';

  @override
  String get socialMediaMilestone30Title => 'Vrais amis > faux likes 💝';

  @override
  String get socialMediaMilestone30Description =>
      'Un mois avec beaucoup moins de réseaux = une baisse importante de la solitude et de la dépression ! Les recherches montrent que limiter les réseaux sociaux améliore nettement la santé mentale. Vous êtes allé encore plus loin !';

  @override
  String get socialMediaMilestone60Title =>
      'Piège de la comparaison : ÉCHAPPÉ ! ✨';

  @override
  String get socialMediaMilestone60Description =>
      'Deux mois sans comparaison sociale constante = confiance en forte hausse ! Les recherches montrent régulièrement que l\'usage des réseaux sociaux est associé à une baisse de l\'estime de soi, notamment à cause des comparaisons ascendantes. Vous vous êtes libéré du piège de la comparaison !';

  @override
  String get socialMediaMilestone90Title =>
      'Collectionneur de loisirs : niveau expert 🎨';

  @override
  String get socialMediaMilestone90Description =>
      'Trois mois = environ 270 heures récupérées ! De quoi apprendre une compétence, lire plus de 15 livres ou approfondir un loisir. Votre cerveau renforce les habitudes répétées, alors ces routines hors ligne deviennent plus faciles et automatiques.';

  @override
  String get socialMediaMilestone180Title =>
      'Transformation du bien-être mental accomplie 🌟';

  @override
  String get socialMediaMilestone180Description =>
      'Six mois avec beaucoup moins de réseaux et vous vous épanouissez pleinement ! Les études à long terme montrent que réduire les réseaux sociaux entraîne des améliorations durables du bien-être, de l\'estime de soi et de la satisfaction de vie. Vous prouvez que la vie réelle a beaucoup à offrir !';

  @override
  String get socialMediaMilestone365Title =>
      'Maître du zen numérique débloqué 🏆';

  @override
  String get socialMediaMilestone365Description =>
      'Une année entière de vie intentionnelle ! Vous avez récupéré plus de 1 000 heures, noué des relations plus profondes et montré que les meilleurs moments ne sont pas faits pour être publiés, mais vécus. Vous êtes désormais une légende du bien-être numérique !';

  @override
  String get nicotinePouchesMilestone1Title =>
      'Le goût et l\'odorat commencent à récupérer';

  @override
  String get nicotinePouchesMilestone1Description =>
      'La nicotine émousse le goût et l\'odorat. Après seulement 24 heures sans sachets, ces sens commencent leur grand retour ! Les aliments vont retrouver toute leur saveur.';

  @override
  String get nicotinePouchesMilestone3Title =>
      'La nicotine est entièrement éliminée';

  @override
  String get nicotinePouchesMilestone3Description =>
      'Votre corps a officiellement expulsé toute la nicotine ! Même si les symptômes de sevrage peuvent culminer maintenant, souvenez-vous : votre cerveau se recâble pour la liberté. Le plus dur est presque terminé.';

  @override
  String get nicotinePouchesMilestone7Title =>
      'La santé bucco-dentaire s\'améliore';

  @override
  String get nicotinePouchesMilestone7Description =>
      'Vos gencives ont de quoi célébrer ! Les sachets de nicotine peuvent provoquer irritation et récession gingivales. Après une semaine, la circulation sanguine des gencives se normalise et la guérison commence.';

  @override
  String get nicotinePouchesMilestone14Title =>
      'Amélioration de la circulation';

  @override
  String get nicotinePouchesMilestone14Description =>
      'Vos vaisseaux sanguins respirent mieux ! La nicotine les contracte, mais après deux semaines sans nicotine, votre circulation s\'est nettement améliorée. Bonjour les mains et les pieds plus chauds !';

  @override
  String get nicotinePouchesMilestone30Title =>
      'La réponse au stress se normalise';

  @override
  String get nicotinePouchesMilestone30Description =>
      'Surprise : la nicotine augmente en réalité le stress entre les prises ! Votre cortisol et votre réponse au stress reviennent à la normale. Une vraie détente, sans le faux soulagement de la nicotine.';

  @override
  String get nicotinePouchesMilestone60Title =>
      'La qualité du sommeil s\'améliore';

  @override
  String get nicotinePouchesMilestone60Description =>
      'Les beaux rêves se font sans nicotine ! Même si elle semble relaxante, la nicotine perturbe en réalité l\'architecture du sommeil. Après deux mois, vos cycles de sommeil paradoxal sont magnifiquement restaurés.';

  @override
  String get nicotinePouchesMilestone90Title =>
      'Les récepteurs dopaminergiques récupèrent';

  @override
  String get nicotinePouchesMilestone90Description =>
      'Le système de récompense de votre cerveau est de nouveau opérationnel ! La nicotine détourne les circuits de la dopamine et rend les plaisirs ordinaires ternes. Après trois mois, les joies naturelles de la vie redeviennent vibrantes.';

  @override
  String get nicotinePouchesMilestone180Title =>
      'Le risque cardiovasculaire diminue';

  @override
  String get nicotinePouchesMilestone180Description =>
      'Votre cœur vous remercie ! Six mois sans nicotine réduisent nettement le risque de maladie cardiovasculaire. Votre tension artérielle et la variabilité de votre fréquence cardiaque se sont fortement améliorées.';

  @override
  String get nicotinePouchesMilestone365Title =>
      'Santé à long terme consolidée';

  @override
  String get nicotinePouchesMilestone365Description =>
      'Une année de liberté ! Votre risque de problèmes de santé liés à la nicotine continue de chuter. Vous avez brisé le cycle de dépendance et repris votre autonomie. C\'est réellement héroïque ! 🏆';

  @override
  String get pornographyMilestone1Title => 'Reprendre le contrôle';

  @override
  String get pornographyMilestone1Description =>
      'L\'usage problématique de pornographie se définit par une perte de contrôle et la détresse ou les difficultés qui en résultent. Un jour compte déjà : vous avez interrompu l\'ancien schéma une première fois et commencé à identifier vos déclencheurs.';

  @override
  String get pornographyMilestone3Title => 'Comprendre vos envies';

  @override
  String get pornographyMilestone3Description =>
      'Les personnes ayant un usage problématique plus sévère signalent souvent des pensées sexuelles intrusives, un désir difficile à contrôler, de l\'irritabilité, des changements d\'humeur et des troubles du sommeil. Le troisième jour est un bon moment pour identifier lesquels de ces symptômes vous concernent réellement.';

  @override
  String get pornographyMilestone7Title => 'Une semaine : premières données';

  @override
  String get pornographyMilestone7Description =>
      'Dans une étude randomisée de 7 jours d\'abstinence, les utilisateurs réguliers n\'ont montré aucun syndrome de sevrage global. Un sous-groupe exploratoire combinant usage problématique élevé et visionnage quotidien avait davantage d\'envies ; une première semaine difficile est donc possible, mais pas inévitable.';

  @override
  String get pornographyMilestone14Title => 'Cartographiez vos déclencheurs';

  @override
  String get pornographyMilestone14Description =>
      'Deux semaines vous exposent plusieurs fois aux situations qui déclenchaient auparavant l\'usage de pornographie. Les recherches associent l\'usage problématique à des facteurs comme les envies, le stress, l\'évitement, la solitude et les stratégies d\'adaptation ; connaître votre propre schéma vous donne quelque chose de concret à modifier.';

  @override
  String get pornographyMilestone30Title => 'Un mois de contrôle';

  @override
  String get pornographyMilestone30Description =>
      'Un mois constitue un test significatif du contrôle. Dans une étude portant sur 14 581 personnes, les problèmes de fonction sexuelle étaient davantage associés à l\'usage problématique qu\'à la simple fréquence de visionnage ; retrouver le contrôle est donc une cible mieux étayée par les données.';

  @override
  String get pornographyMilestone90Title => 'Le changement peut durer';

  @override
  String get pornographyMilestone90Description =>
      'Un essai randomisé de thérapie d\'acceptation et d\'engagement pour l\'usage problématique de pornographie a constaté de fortes réductions du visionnage après 12 séances, encore largement présentes au suivi à 3 mois. Un changement durable est réaliste, surtout avec des compétences structurées plutôt qu\'en comptant uniquement sur la volonté.';

  @override
  String get pornographyMilestone180Title => 'Stabilité à six mois';

  @override
  String get pornographyMilestone180Description =>
      'Une étude randomisée de thérapie cognitivo-comportementale pour les comportements sexuels incontrôlés a constaté des améliorations des symptômes, de la compulsivité sexuelle et du bien-être, restées stables aux suivis à 3 et 6 mois. Un contrôle à long terme peut être maintenu.';

  @override
  String get pornographyMilestone365Title => 'Un an : changement durable';

  @override
  String get pornographyMilestone365Description =>
      'Les données de suivi à un an d\'une étude sur un traitement fondé sur l\'acceptation montrent que les participants ne sont pas revenus aux niveaux d\'hypersexualité d\'avant traitement. Un an de changement maintenu est un signe crédible d\'une habitude durable, pas une date magique de « réinitialisation du cerveau ».';

  @override
  String get pornographyMilestone1825Title => 'Cinq ans de contrôle';

  @override
  String get pornographyMilestone1825Description =>
      'Cinq ans représentent un maintien à long terme. Le trouble du comportement sexuel compulsif est cliniquement défini par une perte persistante de contrôle accompagnée de détresse ou d\'altération du fonctionnement ; maintenir le contrôle et bien fonctionner pendant des années constitue donc un résultat significatif en soi.';

  @override
  String get customMilestone1Title =>
      'Début de la phase initiale de récupération';

  @override
  String get customMilestone1Description =>
      'Votre corps commence à guérir ! Dans les 24 heures suivant l\'arrêt, votre organisme commence à éliminer les substances et à s\'adapter à fonctionner sans elles. Les troubles du sommeil sont fréquents mais font partie du processus de récupération.';

  @override
  String get customMilestone3Title => 'Pic des symptômes de sevrage';

  @override
  String get customMilestone3Description =>
      'Vous affrontez la tempête de front ! Pour de nombreuses substances, les symptômes physiques culminent autour du troisième jour, notamment l\'anxiété, les sautes d\'humeur et l\'inconfort physique. Cela signifie que vous traversez la partie la plus difficile.';

  @override
  String get customMilestone7Title => 'Fin de la phase aiguë du sevrage';

  @override
  String get customMilestone7Description =>
      'Le pire est derrière vous ! Après une semaine, les symptômes aigus commencent à diminuer pour la plupart des substances. Votre corps s\'adapte à sa nouvelle normalité et commence à se stabiliser.';

  @override
  String get customMilestone14Title =>
      'Stabilisation du début de rétablissement';

  @override
  String get customMilestone14Description =>
      'Votre esprit s\'éclaircit ! Deux semaines d\'abstinence apportent souvent une meilleure clarté mentale et moins d\'envies, tandis que votre cerveau s\'adapte à fonctionner sans substance addictive.';

  @override
  String get customMilestone30Title => 'Étape d\'un mois';

  @override
  String get customMilestone30Description =>
      'Une grande victoire ! Trente jours d\'abstinence représentent un progrès important. Beaucoup constatent que le sommeil, l\'humeur et l\'énergie continuent de s\'améliorer pendant cette période.';

  @override
  String get customMilestone90Title => 'Étape de trois mois de rétablissement';

  @override
  String get customMilestone90Description =>
      'Votre engagement porte ses fruits ! Trois mois de rétablissement constituent une réussite importante. Les symptômes de sevrage post-aigu commencent généralement à s\'estomper et beaucoup disent se sentir de nouveau davantage eux-mêmes.';

  @override
  String get customMilestone180Title => 'Six mois de rétablissement';

  @override
  String get customMilestone180Description =>
      'Vous construisez un changement durable ! Six mois d\'abstinence apportent souvent des améliorations continues de la santé physique, de la stabilité émotionnelle et de la qualité de vie générale tandis que votre corps poursuit sa guérison.';

  @override
  String get customMilestone365Title => 'Un an de rétablissement';

  @override
  String get customMilestone365Description =>
      'Une réussite incroyable ! Une année d\'abstinence représente une étape majeure de la vie. À ce stade, beaucoup constatent des améliorations importantes de leur santé physique, de leurs relations et de leur bien-être général.';

  @override
  String get customMilestone730Title => 'Deux ans de rétablissement durable';

  @override
  String get customMilestone730Description =>
      'Vous avez construit une nouvelle vie ! Deux ans de rétablissement démontrent une résilience et un engagement remarquables. L\'abstinence à long terme apporte souvent de profonds changements positifs dans tous les domaines de la vie et réduit nettement le risque de rechute.';

  @override
  String get addictionSsri => 'ISRS';

  @override
  String get ssriPageTitle => 'Rétablissement après les ISRS';

  @override
  String get ssriHeaderStarted => 'Votre parcours de rétablissement';

  @override
  String get ssriHeaderNotStarted =>
      'Bienfaits de l\'arrêt progressif des ISRS';

  @override
  String get ssriSubtitleStarted =>
      'Suivez vos progrès et célébrez chaque étape';

  @override
  String get ssriSubtitleNotStarted =>
      'Découvrez ce qui se passe pendant l\'arrêt progressif';

  @override
  String get ssriMilestone3Title => 'Jour 3 : pic du syndrome FINISH';

  @override
  String get ssriMilestone3Description =>
      'Les symptômes de sevrage culminent souvent entre les jours 2 et 4. Les ISRS modifient le recyclage de la sérotonine ; le cerveau a donc besoin de temps pour s\'adapter après l\'arrêt. Attendez-vous à des symptômes pseudo-grippaux, des vertiges, de l\'insomnie, des nausées et des « décharges cérébrales ». La paroxétine tend à provoquer un sevrage plus marqué ; la fluoxétine reste beaucoup plus longtemps dans l\'organisme et est généralement plus facile à arrêter.';

  @override
  String get ssriMilestone7Title =>
      'Une semaine : la phase aiguë commence à diminuer';

  @override
  String get ssriMilestone7Description =>
      'Les symptômes physiques les plus intenses commencent à s\'atténuer. Votre cerveau adapte sa signalisation sérotoninergique pour fonctionner sans le médicament. Le sommeil et l\'appétit commencent à se stabiliser.';

  @override
  String get ssriMilestone14Title =>
      'Deux semaines : résolution des symptômes physiques';

  @override
  String get ssriMilestone14Description =>
      'La plupart des symptômes physiques aigus d\'arrêt ont fortement diminué ou disparu. Les décharges cérébrales, les nausées et les vertiges s\'estompent. La sensibilité émotionnelle peut rester élevée pendant que le cerveau continue de rééquilibrer ses systèmes sérotoninergiques.';

  @override
  String get ssriMilestone30Title =>
      'Un mois : stabilisation de l\'humeur et de l\'énergie';

  @override
  String get ssriMilestone30Description =>
      'Un mois marque une étape importante. La qualité du sommeil s\'améliore, l\'énergie se stabilise et beaucoup constatent que leur humeur trouve un nouvel équilibre. Le cerveau restaure activement sa régulation naturelle de la sérotonine.';

  @override
  String get ssriMilestone90Title =>
      'Trois mois : récupération des récepteurs sérotoninergiques';

  @override
  String get ssriMilestone90Description =>
      'Trois mois constituent une étape majeure. Le système sérotoninergique a eu plusieurs mois pour s\'adapter après l\'élimination du médicament. L\'humeur, l\'anxiété, la concentration et la clarté mentale sont sensiblement meilleures chez la plupart des personnes.';

  @override
  String get ssriMilestone180Title =>
      'Six mois : adaptation cérébrale à long terme';

  @override
  String get ssriMilestone180Description =>
      'Six mois permettent une adaptation neurologique importante. Les systèmes sérotoninergiques du cerveau ont retrouvé leur équilibre naturel. Beaucoup rapportent une gamme émotionnelle plus riche et, chez ceux qui en souffraient, les troubles sexuels causés par les ISRS se sont généralement résolus.';

  @override
  String get ssriMilestone365Title => 'Un an : récupération accomplie';

  @override
  String get ssriMilestone365Description =>
      'Un an représente un cycle complet de récupération. Les recherches montrent que la majorité des personnes ayant terminé une diminution progressive avec un soutien psychologique vont bien à un an, avec une qualité de vie comparable ou meilleure que celle des personnes restées sous traitement.';

  @override
  String get settingsShowSsriTracking => 'Afficher le suivi des ISRS';

  @override
  String get settingsNotifySsri => 'Notifier les progrès d\'arrêt des ISRS';

  @override
  String get addictionSnri => 'IRSN';

  @override
  String get snriPageTitle => 'Rétablissement après les IRSN';

  @override
  String get snriHeaderStarted => 'Votre parcours de rétablissement';

  @override
  String get snriHeaderNotStarted =>
      'Bienfaits de l\'arrêt progressif des IRSN';

  @override
  String get snriSubtitleStarted =>
      'Suivez vos progrès et célébrez chaque étape';

  @override
  String get snriSubtitleNotStarted =>
      'Découvrez ce qui se passe pendant l\'arrêt progressif';

  @override
  String get snriMilestone3Title => 'Jour 3 : pic du syndrome d\'arrêt intense';

  @override
  String get snriMilestone3Description =>
      'Les IRSN — en particulier la venlafaxine (Effexor) — sont associés à certains des syndromes d\'arrêt d\'antidépresseurs les plus sévères. La très courte demi-vie de la venlafaxine (5 heures) peut rendre les symptômes plus intenses qu\'avec la plupart des ISRS. Les symptômes FINISH (état pseudo-grippal, insomnie, nausées, déséquilibre, troubles sensoriels, hyperactivation) touchent simultanément les systèmes de la sérotonine et de la noradrénaline.';

  @override
  String get snriMilestone7Title =>
      'Une semaine : deux systèmes neurochimiques s\'adaptent';

  @override
  String get snriMilestone7Description =>
      'Les IRSN agissent sur la recapture de la sérotonine et de la noradrénaline. Les deux systèmes s\'adaptent en même temps. Les symptômes physiques les plus intenses commencent à diminuer, mais ce double mécanisme peut rendre l\'adaptation plus complexe qu\'avec les seuls ISRS.';

  @override
  String get snriMilestone14Title =>
      'Deux semaines : les symptômes physiques s\'estompent';

  @override
  String get snriMilestone14Description =>
      'La plupart des symptômes physiques aigus d\'arrêt ont nettement diminué. Les décharges cérébrales, les nausées et les vertiges s\'estompent. La réadaptation du système noradrénergique peut encore provoquer de l\'anxiété ou des variations de tension artérielle ; elles disparaissent généralement au cours des semaines suivantes.';

  @override
  String get snriMilestone30Title =>
      'Un mois : stabilisation du système noradrénergique';

  @override
  String get snriMilestone30Description =>
      'Un mois marque une étape importante. Les systèmes sérotoninergique et noradrénergique se rééquilibrent activement. Le sommeil et l\'énergie se stabilisent. Beaucoup remarquent une gamme émotionnelle plus large à mesure que l\'émoussement émotionnel lié au médicament s\'atténue.';

  @override
  String get snriMilestone90Title =>
      'Trois mois : rééquilibrage des deux systèmes';

  @override
  String get snriMilestone90Description =>
      'Trois mois constituent une étape majeure. Les systèmes de la sérotonine et de la noradrénaline ont eu plusieurs mois pour s\'adapter. L\'humeur, l\'anxiété, la concentration et la clarté mentale sont sensiblement meilleures après une diminution supervisée.';

  @override
  String get snriMilestone180Title => 'Six mois : récupération neurologique';

  @override
  String get snriMilestone180Description =>
      'Six mois permettent une réadaptation importante des systèmes sérotoninergique et noradrénergique. L\'axe HPA — influencé par les IRSN via la noradrénaline — se normalise. Beaucoup rapportent à ce stade une bien meilleure résilience face au stress quotidien.';

  @override
  String get snriMilestone365Title => 'Un an : récupération accomplie';

  @override
  String get snriMilestone365Description =>
      'Un an représente un cycle complet de récupération des systèmes sérotoninergique et noradrénergique. Les recherches montrent régulièrement que les personnes qui arrêtent avec succès les IRSN sous supervision médicale et avec un soutien psychologique conservent de bons résultats à un an.';

  @override
  String get settingsShowSnriTracking => 'Afficher le suivi des IRSN';

  @override
  String get settingsNotifySnri => 'Notifier les progrès d\'arrêt des IRSN';

  @override
  String get addictionTca => 'ATC';

  @override
  String get tcaPageTitle => 'Rétablissement après les ATC';

  @override
  String get tcaHeaderStarted => 'Votre parcours de rétablissement';

  @override
  String get tcaHeaderNotStarted => 'Bienfaits de l\'arrêt progressif des ATC';

  @override
  String get tcaSubtitleStarted =>
      'Suivez vos progrès et célébrez chaque étape';

  @override
  String get tcaSubtitleNotStarted =>
      'Découvrez ce qui se passe pendant l\'arrêt progressif';

  @override
  String get tcaMilestone3Title => 'Jour 3 : pic du rebond cholinergique';

  @override
  String get tcaMilestone3Description =>
      'Les ATC bloquent l\'acétylcholine. Après l\'arrêt, ce système peut brièvement devenir hyperactif. Les symptômes comprennent nausées, diarrhée, crampes abdominales, fortes sueurs, maux de tête, douleurs musculaires et insomnie. Ils culminent généralement tôt puis s\'atténuent.';

  @override
  String get tcaMilestone7Title =>
      'Une semaine : les symptômes de rebond diminuent';

  @override
  String get tcaMilestone7Description =>
      'Le rebond cholinergique culmine généralement pendant les premiers jours et commence à diminuer après une semaine. Les symptômes digestifs, les sueurs et la sensation pseudo-grippale s\'atténuent, tandis que les systèmes contrôlant le rythme cardiaque, la digestion et la transpiration reviennent vers la normale.';

  @override
  String get tcaMilestone14Title =>
      'Deux semaines : inversion des effets anticholinergiques';

  @override
  String get tcaMilestone14Description =>
      'La bouche sèche, la constipation, les difficultés à uriner et la vision trouble causées par les ATC s\'atténuent à mesure que le système cholinergique récupère. La mémoire et l\'attention semblent souvent plus claires elles aussi.';

  @override
  String get tcaMilestone30Title =>
      'Un mois : stabilisation du système nerveux autonome';

  @override
  String get tcaMilestone30Description =>
      'Après un mois, les systèmes qui contrôlent le rythme cardiaque, la tension artérielle, la digestion et la transpiration se stabilisent. Les changements du rythme cardiaque et de la tension se rapprochent de la normale, et le sommeil paradoxal revient.';

  @override
  String get tcaMilestone90Title =>
      'Trois mois : stabilisation des systèmes neurochimiques';

  @override
  String get tcaMilestone90Description =>
      'Les ATC agissent sur plusieurs systèmes neurochimiques. Trois mois leur donnent beaucoup de temps pour se stabiliser. L\'humeur, la clarté mentale et le bien-être physique sont nettement meilleurs.';

  @override
  String get tcaMilestone180Title =>
      'Six mois : récupération cardiaque et cognitive';

  @override
  String get tcaMilestone180Description =>
      'Six mois permettent une récupération importante du rythme cardiaque, de la mémoire et de la vitesse de pensée. Les modifications du rythme cardiaque et le brouillard mental causés par les ATC ont eu des mois pour se résorber.';

  @override
  String get tcaMilestone365Title => 'Un an : récupération accomplie';

  @override
  String get tcaMilestone365Description =>
      'Un an donne à chaque système affecté par les ATC une année entière pour récupérer. Les systèmes de l\'acétylcholine, de la noradrénaline, de la sérotonine et de l\'histamine se sont stabilisés, et la mémoire, la clarté mentale ainsi que le contrôle du rythme cardiaque ont largement récupéré.';

  @override
  String get settingsShowTcaTracking => 'Afficher le suivi des ATC';

  @override
  String get settingsNotifyTca => 'Notifier les progrès d\'arrêt des ATC';

  @override
  String get addictionMaoi => 'IMAO';

  @override
  String get maoiPageTitle => 'Rétablissement après les IMAO';

  @override
  String get maoiHeaderStarted => 'Votre parcours de rétablissement';

  @override
  String get maoiHeaderNotStarted =>
      'Bienfaits de l\'arrêt progressif des IMAO';

  @override
  String get maoiSubtitleStarted =>
      'Suivez vos progrès et célébrez chaque étape';

  @override
  String get maoiSubtitleNotStarted =>
      'Découvrez ce qui se passe pendant l\'arrêt progressif';

  @override
  String get maoiMilestone3Title =>
      'Jour 3 : phase de risque maximal — supervision médicale essentielle';

  @override
  String get maoiMilestone3Description =>
      'Les IMAO présentent les risques d\'arrêt les plus graves parmi les classes d\'antidépresseurs. Un arrêt brutal — surtout de la phénelzine ou de la tranylcypromine — peut provoquer une agitation sévère, de la confusion, des hallucinations, des myoclonies et une hyperthermie. Si vous présentez ces symptômes, consultez immédiatement. Les IMAO agissent en désactivant durablement les enzymes MAO ; la récupération exige que le corps synthétise de nouvelles enzymes, un processus qui prend environ 14 jours.';

  @override
  String get maoiMilestone7Title =>
      'Une semaine : synthèse des enzymes MAO en cours';

  @override
  String get maoiMilestone7Description =>
      'Les IMAO détruisent durablement les molécules d\'enzyme MAO ; la récupération nécessite d\'en synthétiser de nouvelles. Après une semaine, environ 50 % de l\'activité MAO normale peut avoir été récupérée. Les symptômes aigus sévères d\'arrêt (délirium, myoclonies, hyperthermie) sont fortement réduits. Une surveillance médicale étroite reste importante.';

  @override
  String get maoiMilestone14Title =>
      'Deux semaines : activité des enzymes MAO largement rétablie';

  @override
  String get maoiMilestone14Description =>
      'Deux semaines correspondent au délai clinique habituel de récupération des enzymes MAO après l\'arrêt. Vers le 14e jour, l\'activité des MAO-A et MAO-B est en grande partie rétablie et le métabolisme normal de la tyramine reprend. Les restrictions alimentaires nécessaires pendant le traitement par IMAO peuvent généralement être assouplies en concertation avec votre prescripteur.';

  @override
  String get maoiMilestone30Title =>
      'Un mois : rééquilibrage des systèmes neurochimiques';

  @override
  String get maoiMilestone30Description =>
      'Un mois après l\'arrêt d\'un IMAO, l\'enzyme MAO est de nouveau active et le cerveau gère naturellement la sérotonine, la noradrénaline, la dopamine et la tyramine. La période particulière d\'interactions alimentaires et médicamenteuses est terminée, même s\'il faut toujours informer les prescripteurs de votre usage antérieur d\'IMAO.';

  @override
  String get maoiMilestone90Title =>
      'Trois mois : normalisation de la chimie cérébrale';

  @override
  String get maoiMilestone90Description =>
      'Trois mois donnent aux systèmes cérébraux de l\'humeur et de l\'énergie beaucoup de temps pour se réadapter après les IMAO. L\'humeur, l\'énergie et la clarté mentale se stabilisent tandis que le cerveau gère de nouveau naturellement ces substances.';

  @override
  String get maoiMilestone180Title => 'Six mois : récupération à long terme';

  @override
  String get maoiMilestone180Description =>
      'Six mois représentent une longue période de fonctionnement naturel des monoamines. Les populations de récepteurs à la sérotonine, à la noradrénaline et à la dopamine se sont normalisées. Les voies de la phénéthylamine (PEA), elles aussi affectées par les IMAO, ont retrouvé leurs niveaux naturels — un aspect souvent négligé de la récupération qui contribue à la normalisation émotionnelle.';

  @override
  String get maoiMilestone365Title => 'Un an : récupération accomplie';

  @override
  String get maoiMilestone365Description =>
      'Une année après l\'arrêt d\'un IMAO donne au cerveau et au corps une année entière sans médicament. L\'humeur, l\'énergie, la clarté mentale et la régulation neurochimique normale ont eu beaucoup de temps pour se stabiliser et récupérer.';

