  @override
  String get adderallReferenceDay1 =>
      'Sevrage des amphétamines : ce qui se passe au début\n\nSource : MedlinePlus (U.S. National Library of Medicine)\n\nQue sont les amphétamines ?\nLes amphétamines sont des stimulants qui comprennent à la fois des substances illicites (comme le « speed ») et des médicaments sur ordonnance utilisés pour traiter le TDAH et la narcolepsie (comme l\'Adderall et le Vyvanse). Elles augmentent fortement la dopamine et la noradrénaline, ce qui peut entraîner une grande capacité de concentration, un surcroît d\'énergie et de l\'euphorie. Avec une consommation régulière importante, le cerveau s\'adapte à ces poussées répétées ; l\'arrêt peut donc temporairement faire baisser l\'humeur, l\'énergie et la motivation.\n\nSymptômes fréquents du sevrage\nMedlinePlus cite comme symptômes typiques lors de l\'arrêt des amphétamines :\n• Forte envie de la substance\n• Sautes d\'humeur allant de la dépression à l\'agitation et à l\'anxiété\n• Fatigue toute la journée\n• Difficultés de concentration\n• Hallucinations (voir ou entendre des choses qui n\'existent pas)\n• Réactions physiques comme maux de tête, douleurs, augmentation de l\'appétit et mauvais sommeil\n\nLe sevrage est-il dangereux ?\nMedlinePlus ne décrit pas le sevrage des amphétamines comme médicalement dangereux en lui-même, mais indique que des symptômes sévères peuvent nécessiter un programme résidentiel et que les problèmes d\'humeur et émotionnels liés aux amphétamines — notamment la dépression — peuvent être graves et nécessiter un soutien.\n\nObtenir de l\'aide\nMedlinePlus recommande de contacter un professionnel de santé si vous ou une personne de votre entourage êtes dépendant des amphétamines et avez besoin d\'aide pour arrêter. En cas de pensées d\'automutilation, la ressource oriente vers les services de crise appropriés.';

  @override
  String get adderallReferenceDay3 =>
      'Gestion du sevrage des amphétamines : jour 3\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), NCBI Bookshelf\n\nQue se passe-t-il au troisième jour ?\nLes recommandations de l\'OMS indiquent que les symptômes du sevrage des stimulants « commencent dans les 24 heures suivant la dernière prise et durent 3 à 5 jours ». Le troisième jour se situe pleinement dans cette phase aiguë — généralement parmi les journées les plus difficiles avant que les symptômes commencent à se calmer.\n\nLes symptômes\nPour les stimulants de type amphétamine, les recommandations citent :\n• Agitation et irritabilité\n• Dépression\n• Sommeil plus long et appétit accru\n• Douleurs musculaires\nLes personnes ayant une consommation importante peuvent également présenter des symptômes psychotiques comme la paranoïa, des pensées désorganisées ou des hallucinations.\n\nUn défi surtout psychologique\nContrairement au sevrage de l\'alcool ou des opioïdes, celui des stimulants n\'entraîne pas habituellement vomissements, tremblements ou crises convulsives. La principale difficulté est psychologique — baisse de moral, perte de plaisir et envies liées à un système dopaminergique épuisé.\n\nApproche de prise en charge\nLes recommandations de l\'OMS préconisent des soins de soutien :\n• Boire au moins 2 à 3 litres d\'eau par jour\n• Compléments multivitaminés avec vitamines du groupe B et vitamine C\n• Traitement symptomatique des douleurs et de l\'anxiété\n• En cas d\'agitation sévère, stratégies comportementales en premier, avec sédation au diazépam uniquement si nécessaire\n\nAprès la phase aiguë\nLes recommandations indiquent que la phase la plus difficile ne dure que quelques jours, suivie d\'une période de récupération plus légère pouvant durer un à deux mois.';

  @override
  String get adderallReferenceDay7 =>
      'Une semaine sans Adderall : le pire est en train de passer\n\nSource : Li & Shoptaw, « Clinical Management of Psychostimulant Withdrawal: Review of the Evidence », Addiction (2023), PubMed Central\n\nLa phase aiguë se résout\nCette revue des données décrit le sevrage des psychostimulants par phases. Pendant la phase aiguë, les symptômes « culminent après les 2 à 3 premiers jours » et « l\'inconfort majeur lié à ces symptômes disparaît généralement en 4 à 7 jours ». À la fin de la première semaine, la partie la plus dure du crash est derrière la plupart des personnes — l\'énergie et l\'appétit commencent à se stabiliser et le sommeil à se réguler.\n\nLa suite\nLa revue indique que la plupart des symptômes restants continuent de diminuer pendant les deux à trois semaines suivantes. Au septième jour, la récupération est déjà bien engagée.\n\nCe qui peut encore être présent au jour 7\nLes symptômes psychologiques durent généralement plus longtemps que le crash physique :\n• Faible motivation et perte de plaisir\n• Difficultés de concentration\n• Humeur encore inférieure à la normale\nIls reflètent un système dopaminergique en réadaptation — une partie normale et temporaire de la récupération.\n\nSignal de récupération\nAucun médicament approuvé par la FDA ne traite spécifiquement le sevrage des stimulants ; les soins de soutien, la structure, le sommeil, l\'alimentation et l\'accompagnement psychologique sont donc les piliers de cette phase.';

  @override
  String get adderallReferenceDay14 =>
      'Deux semaines sans Adderall : entrée dans la phase de récupération prolongée\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), NCBI Bookshelf\n\nAprès la phase aiguë\nL\'OMS situe le sevrage stimulant le plus intense sur environ trois à cinq jours, suivi d\'une période de récupération plus légère d\'environ un à deux mois. Après deux semaines, le crash est loin derrière vous.\n\nÀ quoi ressemble la phase de récupération prolongée\nLe sommeil excessif, l\'agitation et les douleurs musculaires se sont largement apaisés. Ce qui reste est généralement plus léger : humeur basse ou changeante, motivation réduite et envies intermittentes pendant que le système de récompense du cerveau se réadapte.\n\nSommeil et appétit\nLe sommeil prolongé et l\'appétit accru de la phase aiguë se normalisent. Lorsque le sommeil se stabilise, l\'humeur, la concentration et l\'énergie ont tendance à suivre.\n\nRisque de rechute et TDAH\nCette période présente encore un risque accru, notamment si des symptômes de TDAH réapparaissent sans traitement. Les recommandations de l\'OMS insistent sur le soutien psychologique et les compétences de prévention de la rechute ; pour les personnes qui prenaient de l\'Adderall pour un TDAH, c\'est un bon moment pour discuter avec un médecin de stratégies non stimulantes ou d\'alternatives.';

  @override
  String get adderallReferenceDay30 =>
      'Un mois sans Adderall : la plupart des symptômes sont derrière vous\n\nSource : Li & Shoptaw, « Clinical Management of Psychostimulant Withdrawal: Review of the Evidence », Addiction (2023), PubMed Central\n\nOù se situe un mois\nLa revue constate que la plupart des symptômes de sevrage s\'estompent au cours des deux à trois premières semaines. À 30 jours, l\'essentiel a diminué et l\'humeur ainsi que la motivation sont généralement bien meilleures que pendant la première semaine.\n\nLa phase de récupération tardive\nEntre un et six mois, la mémoire, la planification, la concentration et la prise de décision continuent de s\'améliorer. À un mois, le crash est terminé et ces progrès sont déjà en cours.\n\nHumeur et motivation\nLa profonde perte de plaisir du crash s\'est largement atténuée. Les activités qui semblaient sans intérêt la première semaine recommencent à procurer une récompense à mesure que la signalisation naturelle de la dopamine récupère.\n\nPour les personnes avec TDAH\nSi l\'Adderall était prescrit pour un TDAH, les symptômes sous-jacents peuvent être plus visibles maintenant. Il est important de travailler avec un professionnel de santé sur des stratégies non stimulantes ou des alternatives pendant cette phase.';

  @override
  String get adderallReferenceDay60 =>
      'Deux mois sans Adderall : la phase de récupération prolongée touche à sa fin\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), NCBI Bookshelf\n\nOù se situent deux mois\nL\'OMS décrit une période de récupération plus légère d\'environ un à deux mois après le crash initial. À 60 jours, vous êtes à l\'extrémité de cette fenêtre et les symptômes persistants sont en grande partie en train de disparaître.\n\nCe qui s\'améliore\nL\'agitation, l\'humeur dépressive et les perturbations du sommeil et de l\'appétit décrites pour le sevrage stimulant se sont, chez la plupart des personnes, nettement apaisées :\n• L\'humeur habituelle est plus stable, avec moins de fluctuations qu\'au début\n• Le sommeil et l\'appétit se sont normalisés\n• Le système de récompense répond plus facilement aux plaisirs ordinaires — nourriture, activité physique, relations\n\nSignal de récupération\nDes doses plus élevées et une consommation plus longue peuvent prolonger la récupération, tandis que l\'abstinence continue fait progresser l\'humeur, la motivation et la clarté mentale vers la normale au cours des mois suivants.\n\nSanté physique\nLes effets stimulants sur le rythme cardiaque, l\'appétit et le poids s\'atténuent lorsque le médicament disparaît du quotidien, et la contrainte cardiovasculaire liée aux stimulants diminue.';

  @override
  String get adderallReferenceDay90 =>
      'Trois mois sans Adderall : le pire est derrière vous, la guérison continue\n\nSource : Li & Shoptaw, « Clinical Management of Psychostimulant Withdrawal: Review of the Evidence », Addiction (2023), PubMed Central\n\nOù se situent 90 jours\nÀ trois mois, les symptômes précoces ont disparu depuis longtemps tandis que la mémoire, la planification, la concentration, la prise de décision et le système de récompense continuent de s\'améliorer.\n\nLa pensée et la mémoire continuent de récupérer\nLa revue constate que la mémoire, la planification, la concentration et les décisions face au risque peuvent continuer à s\'améliorer pendant des mois. À 90 jours, concentration et mémoire poursuivent leur évolution dans la bonne direction avec l\'abstinence.\n\nPourquoi cette période compte encore\nAucun médicament approuvé par la FDA ne cible spécifiquement le sevrage stimulant ; structure, thérapie, activité physique, sommeil et soutien sont donc les outils qui font avancer la récupération durant cette phase. Construire ces habitudes maintenant est ce qui porte la suite du rétablissement.\n\nVue d\'ensemble\nTrois mois constituent une vraie réussite — les périodes physiques et émotionnelles les plus difficiles sont derrière vous et, avec une abstinence continue, la trajectoire est celle d\'une amélioration régulière.';

  @override
  String get adderallReferenceDay180 =>
      'Six mois sans Adderall : bien au-delà de la partie difficile\n\nSource : « Withdrawal Syndromes », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nCe que StatPearls dit des stimulants\nCette référence clinique décrit la récupération après stimulants comme un crash suivi d\'une amélioration progressive. Les problèmes fréquents incluent dépression, sommeil excessif, augmentation de la faim, baisse de moral et ralentissement des mouvements et de la pensée. La dépression peut durer plusieurs semaines, avec une récupération plus légère qui se poursuit ensuite.\n\nOù se situent six mois\nÀ six mois, vous êtes très loin de la période aiguë comme de la phase dépressive de plusieurs semaines décrite par StatPearls. La récupération lente évoquée a eu beaucoup de temps pour progresser et, chez la plupart des personnes, l\'humeur habituelle, le sommeil, l\'appétit et la motivation sont désormais stables et fiables.\n\nSignal de récupération\nStatPearls décrit une récupération progressive au-delà des premières semaines. À six mois, le crash aigu et la phase dépressive de plusieurs semaines sont loin derrière ; stabilité de l\'humeur, du sommeil, de l\'appétit et de la motivation est devenue la tendance dominante.\n\nLien avec le TDAH\nPour les personnes qui prenaient de l\'Adderall pour un TDAH, six mois d\'abstinence sont un bon moment pour faire, avec un médecin, un bilan clair des symptômes actuels et de l\'efficacité d\'approches non stimulantes — activité physique, sommeil, organisation, thérapie ou autre traitement.';

  @override
  String get adderallReferenceDay365 =>
      'Un an sans Adderall : une récupération importante, présentée avec nuance\n\nSource : Berman et al., « Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review », Molecular Psychiatry (2008), PubMed Central\n\nÀ propos de cette revue\nCette revue examine les effets possibles d\'une exposition à forte dose ou prolongée aux amphétamines sur le cerveau et documente une récupération mesurable pendant l\'abstinence.\n\nCe qu\'elle dit de la récupération\nLa revue décrit une récupération du débit sanguin cérébral et des protéines qui recyclent la dopamine après une abstinence prolongée. Certaines régions récupèrent plus vite que d\'autres, mais la direction générale est claire : le cerveau récupère après l\'arrêt.\n\nRécupération à long terme\nLa revue documente une récupération mesurable du débit sanguin cérébral et du recyclage de la dopamine après une abstinence prolongée. À un an, ces systèmes cérébraux ont eu une année entière pour se reconstruire.\n\nCe que cela signifie à un an\nPour la plupart des personnes — en particulier celles qui prenaient l\'Adderall aux doses prescrites — une année sans traitement signifie que les systèmes de récompense, d\'attention et de motivation fonctionnent bien au quotidien. Une consommation plus importante ou plus longue peut demander davantage de temps, mais la récupération continue. Le risque de rechute est beaucoup plus faible qu\'au début du rétablissement.';

  @override
  String get alcoholReferenceDay1 =>
      'Que devient votre sommeil quand vous arrêtez l\'alcool ?\n\nSource : « Alcohol and the Sleeping Brain » (Colrain, Nicholas & Baker), Handbook of Clinical Neurology — publication évaluée par les pairs, hébergée par le NIH\n\nAlcool et architecture du sommeil\nL\'alcool est sédatif : il raccourcit le délai d\'endormissement et augmente le sommeil lent profond pendant la première moitié de la nuit. Mais cela a un coût : l\'alcool réduit le sommeil paradoxal — la phase réparatrice liée à la consolidation de la mémoire et à la régulation émotionnelle — et fragmente le sommeil pendant la seconde moitié de la nuit lorsqu\'il est métabolisé.\n\nLa première nuit sans alcool\nComme l\'alcool réduit le sommeil paradoxal et les rêves, les premières nuits sans alcool entraînent souvent un rebond de sommeil paradoxal : rêves vifs et sommeil plus léger et fragmenté pendant que les rythmes normaux reviennent. C\'est une partie normale et temporaire de la récupération.\n\nLa récupération commence\nÀ mesure que le cerveau se réadapte au cours des jours et semaines suivants, le sommeil paradoxal et la qualité globale du sommeil s\'améliorent. Les troubles du sommeil font partie des symptômes liés au sevrage qui persistent le plus, mais ils évoluent vers la normale avec une abstinence durable.\n\nRemarque sur la forte consommation\nChez les personnes qui boivent beaucoup ou quotidiennement depuis longtemps, les premières 24 heures peuvent aussi apporter des symptômes de sevrage (anxiété, sueurs, tremblements, nausées). Un sevrage sévère peut être dangereux — si vous buvez beaucoup chaque jour, parlez à un médecin avant d\'arrêter brutalement.';

  @override
  String get alcoholReferenceDay3 =>
      'La phase aiguë et le début du rétablissement\n\nSource : « Alcohol Withdrawal », StatPearls — publication évaluée par les pairs, NIH National Library of Medicine\n\nLes premières 24 à 72 heures\nStatPearls indique que les symptômes de sevrage apparaissent quelques heures après le dernier verre — tremblements, insomnie, agitation, sueurs, augmentation du rythme cardiaque et de la tension artérielle — et culminent généralement vers 72 heures. La plupart des personnes ont dépassé le pire de la phase aiguë à la fin du troisième jour. Un sevrage sévère (crises convulsives ou delirium tremens, qui selon StatPearls peut survenir jusqu\'à 3 à 5 jours après l\'arrêt ou la réduction) est une urgence médicale : les personnes ayant une consommation importante quotidiens ne doivent pas arrêter brutalement sans avis médical.\n\nLes envies viennent par vagues\nLes envies s\'intensifient souvent au cours des premiers jours, mais une envie isolée est brève — elle disparaît généralement en quelques minutes. Savoir que chaque vague retombe d\'elle-même aide à la traverser.\n\nL\'hydratation se rétablit\nL\'alcool inhibe l\'hormone antidiurétique (ADH), ce qui pousse les reins à éliminer davantage d\'eau et laisse les consommateurs réguliers chroniquement déshydratés. Quand l\'alcool s\'arrête, cet effet diurétique cesse et l\'équilibre hydrique commence à se rétablir au cours des premiers jours — souvent avec une peau plus nette et une énergie plus stable.\n\nL\'esprit et le sommeil commencent à se stabiliser\nÀ mesure que la phase aiguë passe, la chimie cérébrale perturbée par l\'alcool (GABA et glutamate) commence à se rééquilibrer. La clarté mentale s\'améliore et le sommeil — très fragmenté au début du sevrage — évolue vers une meilleure qualité au cours de la première semaine.';

  @override
  String get alcoholReferenceDay7 =>
      'Comment le système immunitaire récupère\n\nSource : « Alcohol and the Immune System » (Sarkar, Jung & Wang), Alcohol Research: Current Reviews — publication évaluée par les pairs, hébergée par le NIH\n\nComment l\'alcool affaiblit l\'immunité\nL\'alcool affaiblit le système immunitaire de plusieurs façons. Même un seul épisode de forte consommation peut réduire la capacité à combattre les infections pendant jusqu\'à 24 heures. Une consommation prolongée réduit les globules blancs, perturbe les signaux immunitaires et endommage les défenses intestinales et pulmonaires, augmentant le risque d\'infections et ralentissant la cicatrisation.\n\nSupprimer l\'agression\nBeaucoup de ces effets s\'améliorent une fois l\'alcool éliminé. Les globules blancs et la signalisation immunitaire commencent à récupérer, tandis que les défenses intestinales et respiratoires se réparent. Au cours de la première semaine, votre système immunitaire n\'est plus affaibli quotidiennement et la résistance aux infections courantes commence à s\'améliorer.\n\nUn processus progressif\nLa récupération immunitaire complète prend plus d\'une semaine et dépend de l\'intensité et de la durée de la consommation — mais la première semaine sans alcool est le moment où la reconstruction commence.';

  @override
  String get alcoholReferenceDay14 =>
      'Récupération cérébrale précoce pendant l\'abstinence\n\nSource : Bartsch AJ et al., « Manifestations of early brain recovery associated with abstinence from alcoholism », Brain (2007) — publication évaluée par les pairs\n\nMesurer la récupération\nCette étude a utilisé l\'IRM pour suivre des personnes récemment désintoxiquées d\'une dépendance à l\'alcool pendant les premières semaines d\'abstinence, en les comparant à des témoins sains. Elle a observé la reconstruction physique du cerveau après l\'arrêt.\n\nLe volume cérébral rebondit\nLa consommation chronique d\'alcool réduit le volume du cerveau — en partie par une diminution réversible de la taille des cellules, pas seulement par une perte cellulaire permanente. Avec l\'abstinence, les chercheurs ont mesuré une augmentation moyenne du volume cérébral global de près de 2 %, concentrée autour du cervelet, du mésencéphale, des ventricules et des régions frontales. Une grande partie de cette repousse survient tôt, pendant les deux premières semaines sans alcool.\n\nCervelet et attention\nLa récupération était particulièrement nette dans les régions cérébrales impliquées dans le mouvement et l\'attention. Un marqueur de santé des cellules cérébrales augmentait parallèlement à des améliorations mesurables de l\'attention : la guérison physique s\'accompagnait donc de gains réels sur le plan cognitif.\n\nUne base, pas une fin\nLes fonctions supérieures comme le raisonnement complexe récupèrent plus progressivement, mais les deux premières semaines montrent que le cerveau commence à guérir rapidement une fois l\'alcool retiré.';

  @override
  String get alcoholReferenceDay30 =>
      'La tension artérielle baisse lorsque vous réduisez l\'alcool\n\nSource : Roerecke et al., « The effect of a reduction in alcohol consumption on blood pressure: a systematic review and meta-analysis », Lancet Public Health (2017) — publication évaluée par les pairs\n\nLes données\nCette méta-analyse a regroupé 36 essais randomisés (environ 2 865 participants) étudiant l\'effet d\'une réduction de l\'alcool sur la tension artérielle. Elle a constaté un effet clairement dépendant de la dose : plus une personne réduisait sa consommation, plus sa tension diminuait.\n\nQuelle est l\'ampleur de l\'effet ?\nLes personnes consommant deux verres ou moins par jour n\'ont pas montré de changement significatif de tension en réduisant leur consommation. Au-delà de ce seuil, l\'effet augmentait avec la dose : il était le plus marqué chez les personnes buvant six verres ou plus par jour et réduisant d\'environ moitié, avec une baisse moyenne d\'environ 5,5 mmHg de la pression systolique et 4,0 mmHg de la diastolique. Une diminution de cette ampleur est cliniquement significative — comparable à certains traitements antihypertenseurs et suffisante pour réduire le risque à long terme d\'AVC et de maladie cardiaque.\n\nPourquoi un mois compte\nL\'alcool augmente la tension en activant la réponse au stress, en augmentant le cortisol et en rigidifiant les vaisseaux. Les essais de cette revue montrent que le bénéfice apparaît sur plusieurs semaines de réduction durable ; après environ un mois d\'abstinence, la tension d\'un gros consommateur a donc eu le temps de se rapprocher d\'un niveau plus sain.\n\nUn effet de seuil\nLa revue a trouvé un seuil clair : le bénéfice se concentrait chez les personnes buvant plus de deux verres par jour et augmentait avec le niveau antérieur de consommation. Si vous étiez un consommateur léger, n\'attendez pas ce bénéfice spécifique sur la tension — mais les personnes ayant une consommation importante obtiennent un bénéfice cardiovasculaire réel et mesurable en arrêtant.';

  @override
  String get alcoholReferenceDay60 =>
      'Récupération du foie après l\'arrêt de l\'alcool\n\nSource : National Institute on Alcohol Abuse and Alcoholism (NIAAA), « Alcohol\'s Effects on the Body »\n\nComment l\'alcool endommage le foie\nLe foie traite la majeure partie de l\'alcool consommé et subit l\'essentiel des dommages. Le NIAAA décrit une progression des atteintes hépatiques liées à l\'alcool : elles commencent par une stéatose (accumulation de graisse dans les cellules du foie), peuvent évoluer vers une hépatite alcoolique (inflammation), puis avec une consommation importante prolongée vers la fibrose et la cirrhose (cicatrisation).\n\nLes premiers stades sont réversibles\nLe point essentiel est que le foie possède une grande capacité de régénération et que les premières étapes de ces dommages peuvent s\'améliorer lorsque l\'alcool s\'arrête. La stéatose en particulier se résorbe souvent avec une abstinence durable. Après environ deux mois sans alcool, le foie a eu le temps d\'éliminer des dépôts graisseux, de réduire l\'inflammation et de retrouver un fonctionnement plus sain — souvent visible par une baisse des enzymes hépatiques (ALT et AST).\n\nAu-delà du foie\nLe NIAAA indique que l\'alcool sollicite aussi le cœur, le pancréas et le système immunitaire. Donner au corps une pause durable permet également à ces systèmes de récupérer — ce qui contribue à l\'énergie plus stable et à l\'amélioration générale de la santé souvent constatées à ce stade.';

  @override
  String get alcoholReferenceDay90 =>
      'Pensée et mémoire après trois mois de sobriété\n\nSource : revue systématique de la récupération neuropsychologique après abstinence d\'alcool (PubMed Central, 2024) — publication évaluée par les pairs\n\nCe que montrent les données\nCette revue a regroupé des études suivant la récupération de la pensée et de la mémoire après l\'arrêt de l\'alcool. La plupart des capacités évoluent vers la normale en environ six à douze mois, et certaines s\'améliorent plus tôt.\n\nCe qui récupère en premier\nDeux capacités ressortent comme récupérant plus vite : la vitesse de traitement de base (la revue indique une récupération typique vers un mois, même si la précision sur les tâches complexes prend plus de temps) et la mise à jour de la mémoire de travail. Vers trois mois, beaucoup commencent déjà à ressentir ces améliorations.\n\nCe qui prend davantage de temps\nL\'attention, la planification, la prise de décision, le contrôle des impulsions, la perception et la mémoire continuent de s\'améliorer tout au long de la fenêtre de récupération de six à douze mois.\n\nCe qui influence la récupération\nLa revue note que la récupération dépend de facteurs comme l\'âge, le tabagisme et les capacités antérieures — mais pas de façon constante de la quantité totale d\'alcool consommée auparavant. La trajectoire attendue reste celle de la récupération.\n\nPourquoi cela compte\nUne pensée plus claire est un élément concret du rétablissement : une meilleure attention et de meilleures décisions aident à poursuivre le traitement et à éviter la rechute.';

  @override
  String get alcoholReferenceDay180 =>
      'Récupération cérébrale après six mois de sobriété\n\nSource : revue évaluée par les pairs sur la récupération structurelle et fonctionnelle du cerveau pendant l\'abstinence de substances (PubMed Central)\n\nLa récupération continue\nLe rebond précoce du volume cérébral pendant les premières semaines n\'est qu\'un début. Cette revue montre qu\'avec une abstinence durable, le cerveau continue de récupérer sur les plans structurel et fonctionnel — la matière grise se rétablit et les voies de substance blanche endommagées, qui coordonnent la communication entre régions cérébrales, se réparent au fil des mois.\n\nL\'avant du cerveau\nLa récupération est particulièrement importante dans la partie frontale du cerveau, qui gère le jugement, la planification et le contrôle de soi. À mesure qu\'elle guérit, la prise de décision et le contrôle des impulsions se renforcent.\n\nRecâblage et fonctionnement\nEn parallèle de la réparation physique, le fonctionnement et les connexions cérébrales récupèrent. Le cerveau peut se recâbler et réapprendre, ce qui fait de l\'abstinence durable une période particulièrement favorable à la thérapie et aux nouvelles habitudes.\n\nSignal de récupération\nAprès six mois, la structure et le fonctionnement du cerveau évoluent clairement vers une normalité plus saine. Rester abstinent donne davantage de temps à cette récupération pour se consolider.';

  @override
  String get alcoholReferenceDay365 =>
      'Alcool, risque de cancer et arrêt\n\nSource : National Cancer Institute (NCI), « Alcohol and Cancer Risk »\n\nL\'alcool cause le cancer\nLe NCI indique qu\'il existe un fort consensus scientifique sur le fait que la consommation d\'alcool peut provoquer des cancers. L\'alcool est lié aux cancers de la bouche, du pharynx, du larynx, de l\'œsophage, du foie, du sein, du côlon et du rectum. Plus une personne boit — et plus longtemps — plus le risque augmente.\n\nComment l\'alcool favorise le cancer\nLes mécanismes comprennent l\'acétaldéhyde, produit toxique de dégradation de l\'alcool qui endommage l\'ADN ; le stress oxydatif et l\'inflammation ; une moins bonne absorption de nutriments protecteurs ; et, pour le cancer du sein, une hausse des œstrogènes.\n\nLe risque diminue après l\'arrêt\nLe NCI indique surtout que l\'arrêt est associé à une baisse du risque au fil du temps — des études montrent que le risque accru de cancers de la bouche et de l\'œsophage diminue après l\'arrêt, même s\'il peut falloir des années pour se rapprocher du risque d\'une personne n\'ayant jamais bu. Une année sans alcool est une étape significative sur ce chemin.\n\nDes bénéfices qui s\'additionnent\nAtteindre un an consolide également les gains cardiovasculaires et hépatiques de l\'abstinence — baisse de la tension artérielle, réduction du risque d\'arythmie et poursuite de la guérison du foie — en parallèle de la baisse du risque de cancer.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'Sevrage des benzodiazépines : la première semaine\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), NCBI Bookshelf\n\nRemarque sur la sécurité du sevrage\nLe sevrage des benzodiazépines peut être dangereux. Les recommandations de l\'OMS indiquent clairement que l\'approche la plus sûre consiste à administrer des benzodiazépines à doses progressivement décroissantes, ce qui « aide à soulager les symptômes de sevrage et à prévenir l\'apparition de crises convulsives ». N\'arrêtez pas brutalement après un usage prolongé — établissez un plan de diminution avec un médecin.\n\nQuand le sevrage apparaît\nLe calendrier de l\'OMS dépend de la durée d\'action du médicament :\n• Courte durée d\'action (oxazépam, alprazolam, témazépam) : début 1 à 2 jours après la dernière dose, pendant 2 à 4 semaines ou davantage\n• Longue durée d\'action (diazépam, nitrazépam) : début 2 à 7 jours après la dernière dose, pendant 2 à 8 semaines ou davantage\nLa première semaine est le moment où même les benzodiazépines à longue durée d\'action ont suffisamment diminué pour que le sevrage soit pleinement installé.\n\nSymptômes précoces\n• Anxiété de rebond — souvent plus intense que l\'anxiété initialement traitée\n• Insomnie et sommeil perturbé\n• Tremblements et tension musculaire\n• Sueurs et palpitations\n• Sensibilité accrue à la lumière et au son\n\nSurveillance\nLes recommandations de l\'OMS précisent que la sévérité peut « fluctuer fortement » ; plutôt que des échelles formelles, un clinicien doit évaluer régulièrement, rassurer et expliquer les symptômes. Les benzodiazépines renforcent le GABA, principal signal calmant du cerveau ; un usage prolongé émousse ce système, si bien que l\'arrêt laisse temporairement le cerveau surexcité — source de l\'anxiété, des tremblements et du risque convulsif qui rendent une diminution progressive essentielle.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'Sevrage des benzodiazépines : deux semaines\n\nSource : Ashton, « Protracted withdrawal syndromes from benzodiazepines », Journal of Substance Abuse Treatment (1991), PubMed\n\nToujours en sevrage aigu\nAprès deux semaines, beaucoup de personnes — surtout celles qui arrêtent une benzodiazépine à longue durée d\'action — sont encore dans la phase aiguë, lorsque le déséquilibre entre les systèmes calmant (GABA) et excitateur du cerveau est le plus marqué. Anxiété, insomnie et troubles perceptifs sont fréquents.\n\nPourquoi le sevrage peut durer\nLa professeure Heather Ashton décrit comment les premiers symptômes peuvent se prolonger. Anxiété, insomnie, difficultés à penser clairement et changements sensoriels peuvent durer plusieurs mois parce que les adaptations de tolérance du cerveau mettent du temps à s\'inverser.\n\nDes changements lentement réversibles\nAshton les décrit comme des « changements fonctionnels lentement réversibles du système nerveux central ». Le message central est celui de la récupération : le système nerveux inverse progressivement les adaptations fonctionnelles créées par une exposition prolongée aux benzodiazépines.\n\nLa diminution progressive est essentielle\nLes données soutiennent fortement un sevrage lent et supervisé comme moyen le plus sûr d\'arrêter, afin de laisser le cerveau se réadapter progressivement plutôt que de subir une perte soudaine de signalisation inhibitrice.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'Benzodiazépines et récupération du sommeil à deux mois\n\nSource : Poyares et al., « Chronic benzodiazepine usage and withdrawal in insomnia patients », Journal of Psychiatric Research (2004), PubMed\n\nComment les benzodiazépines modifient le sommeil\nLes benzodiazépines sont largement prescrites contre l\'insomnie, mais elles modifient l\'architecture du sommeil. Dans cette étude polysomnographique de patients ayant pris des benzodiazépines chaque soir pendant près de sept ans en moyenne, l\'usage chronique était associé à moins de sommeil lent profond et davantage de sommeil léger de stade 2 — les utilisateurs perdent donc une partie du sommeil profond réparateur même s\'ils se sentent sédatés.\n\nLe sommeil profond revient\nRésultat encourageant : l\'étude a de nouveau mesuré le sommeil 15 jours après le sevrage et constaté une récupération du sommeil lent et de l\'activité delta par rapport aux nuits sous usage chronique, ainsi qu\'une amélioration subjective de la qualité du sommeil. Le sommeil profond, supprimé par le médicament, commençait à revenir environ deux semaines après l\'arrêt.\n\nCe que cela signifie à 60 jours\nSi le sommeil profond récupère dès les deux premières semaines, alors à deux mois le cerveau a eu largement le temps de poursuivre la reconstruction d\'un sommeil naturel et réparateur. L\'insomnie sévère de rebond du début du sevrage s\'est généralement calmée. Les auteurs indiquent honnêtement que le sevrage aggravait d\'abord le sommeil — d\'où l\'importance d\'une diminution progressive — mais qu\'à la fin du protocole la qualité du sommeil était meilleure que sous usage chronique.\n\nAutres améliorations à deux mois\nBeaucoup de symptômes physiques précoces — tension musculaire, tremblements, palpitations, sueurs — ont généralement diminué ou disparu à deux mois à mesure que le corps se régule de nouveau.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'Trois mois après les benzodiazépines : la santé physique se stabilise\n\nSource : Ashton, « Protracted withdrawal syndromes from benzodiazepines », Journal of Substance Abuse Treatment (1991), PubMed\n\nStabilisation physique\nÀ 90 jours, la phase aiguë est loin derrière vous. Chez les personnes ayant terminé une diminution encadrée, la plupart des symptômes physiques — tremblements, palpitations, maux de tête et les pires perturbations du sommeil — se sont nettement atténués, et le sommeil est généralement plus stable.\n\nPourquoi certains symptômes persistent\nAshton indique que certains symptômes peuvent durer plusieurs mois. À trois mois, une anxiété persistante, un brouillard mental et des changements sensoriels peuvent encore apparaître pendant que le cerveau poursuit sa lente réadaptation réversible.\n\nDeux raisons pour lesquelles l\'anxiété persiste\n1. Le système GABA du cerveau continue de se réadapter vers une sensibilité normale — un processus lent\n2. Toute anxiété sous-jacente ayant conduit à l\'usage de benzodiazépines est désormais ressentie sans le tampon fourni par le médicament\n\nUn bon moment pour la thérapie\nLe pire des symptômes précoces étant derrière vous, trois mois est un moment propice pour utiliser des soutiens comme une thérapie par la parole, notamment la TCC, afin de traiter l\'anxiété et construire des stratégies d\'adaptation pendant que le système nerveux continue de se stabiliser.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'Pensée et mémoire à six mois : des progrès mesurables\n\nSource : Tata et al., « Lack of cognitive recovery following withdrawal from long-term benzodiazepine use », Psychological Medicine (1994), PubMed\n\nCe qu\'a fait l\'étude\nCette étude a testé 21 patients utilisant des benzodiazépines au long cours avant le sevrage, juste après et à nouveau après six mois d\'abstinence, en les comparant à des témoins appariés. C\'est l\'un des points de données les plus francs de la littérature sur la récupération après benzodiazépines.\n\nCe qu\'elle a trouvé\nAvant l\'arrêt, les patients présentaient des difficultés d\'apprentissage verbal, de mémoire, de vitesse motrice, de coordination visuelle et de raisonnement visuel. Juste après l\'arrêt, il y avait peu de changement. À six mois, plusieurs de ces domaines s\'étaient améliorés de façon mesurable.\n\nCe que cela signifie\nÀ six mois, l\'apprentissage verbal, la mémoire, la vitesse motrice et la coordination visuelle étaient en récupération mesurable. L\'amélioration était déjà nette et pouvait encore progresser.\n\nVue d\'ensemble\nSi vous vous sentez encore embrumé à six mois, cette étude indique que cela peut arriver et que l\'abstinence continue est la voie à suivre. Des études plus longues montrent que la récupération se poursuit bien au-delà — le cerveau continue de guérir.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'Un an après les benzodiazépines : la pensée et la mémoire continuent de récupérer\n\nSource : Barker et al., « Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis », Archives of Clinical Neuropsychology (2004), PubMed\n\nLes données les plus solides disponibles\nLes chercheurs ont combiné des études qui réévaluaient des utilisateurs de benzodiazépines au long cours après au moins six mois sans médicament. Le résultat global montre une récupération claire de la pensée et de la mémoire après le sevrage.\n\nLa bonne nouvelle\nLes études combinées ont observé une amélioration réelle et mesurable dans plusieurs domaines cognitifs après l\'arrêt. Vers un an, la récupération est large et évidente par rapport à l\'usage actif.\n\nLa récupération continue\nLes études combinées montrent une récupération étendue de la pensée et de la mémoire. À un an, vous êtes bien engagé dans une tendance de récupération déjà mesurable à six mois.\n\nCe que cela signifie à un an\nAttendez-vous à une récupération importante de la pensée, de la mémoire et de la clarté mentale après un an — la plupart des personnes se sentent nettement plus vives qu\'au cours de l\'usage. Si certains domaines restent en retard, cela reste compatible avec les données et ne signifie pas que la récupération s\'est arrêtée. Elle continue, et une année d\'abstinence est une étape majeure et précieuse.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 mois après les benzodiazépines : une récupération lente mais réelle\n\nSource : Ashton, « Protracted withdrawal syndromes from benzodiazepines », Journal of Substance Abuse Treatment (1991), PubMed\n\nPourquoi la récupération prend autant de temps\nLes benzodiazépines agissent sur le GABA, principal système calmant du cerveau. Un usage prolongé modifie la force de la réponse de ce système, et ces changements peuvent mettre des mois à s\'inverser. C\'est pourquoi la récupération se mesure en mois plutôt qu\'en semaines.\n\nOù se situent 18 mois\nAshton décrit des symptômes prolongés qui peuvent prendre des mois à s\'atténuer. À 18 mois, le pire est loin derrière la plupart des personnes et l\'anxiété persistante, les changements sensoriels et le brouillard mental se sont largement apaisés.\n\nLentement réversible\nPoint essentiel : Ashton décrit les changements sous-jacents comme des « changements fonctionnels lentement réversibles du système nerveux central ». Lents, mais réversibles — la longue durée reflète la profondeur de l\'adaptation provoquée par les benzodiazépines, pas des dommages permanents chez la plupart des personnes.\n\nSignal de récupération\nAshton décrit les changements sous-jacents comme lentement réversibles. À 18 mois, le système GABA a eu beaucoup de temps pour se stabiliser et la direction dominante reste une récupération continue vers la normale.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'Deux ans après les benzodiazépines : des progrès majeurs et durables\n\nSource : Barker et al., « Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis », Archives of Clinical Neuropsychology (2004), PubMed\n\nUne étape majeure du rétablissement\nDeux ans représentent une étape importante, surtout après un sevrage prolongé. Les phases de symptômes précoces et persistants sont loin derrière et les gains de la première année ont eu une année supplémentaire pour se consolider.\n\nCe que les données soutiennent\nLes études combinées montrent une récupération dans de nombreux domaines après l\'arrêt. À deux ans, la plupart des personnes rapportent une anxiété égale ou inférieure à leur niveau d\'avant les benzodiazépines, un sommeil fiable sans médicament, des émotions plus stables et une pensée plus claire que pendant l\'usage.\n\nSignal de récupération\nLes études combinées établissent une récupération dans de nombreux domaines de la pensée et de la mémoire. À deux ans, une récupération durable est l\'attente soutenue par les données.\n\nGarder la perspective\nDeux ans donnent au sommeil, à l\'humeur, à la mémoire et à la clarté mentale une longue fenêtre de récupération. Les données montrent une amélioration importante dans ces quatre domaines, avec une guérison qui se poursuit.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'Trois ans après les benzodiazépines : guérison à long terme\n\nSource : Barker et al., « Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis », Archives of Clinical Neuropsychology (2004), PubMed\n\nLa perspective à long terme\nTrois ans se situent à l\'extrémité de la chronologie de récupération. Pour la grande majorité des personnes, même après un sevrage sévère et prolongé, les symptômes perturbateurs sont loin derrière elles et la qualité de vie est transformée par rapport à l\'usage actif.\n\nCe que la méta-analyse a trouvé\nLes études combinées d\'utilisateurs au long cours montrent une récupération dans de nombreux domaines après l\'arrêt. Au fil des années d\'abstinence, l\'histoire dominante est celle d\'une large récupération de la pensée, de la mémoire et du fonctionnement quotidien.\n\nSignal de récupération\nLa recherche à long terme montre une récupération dans de nombreux domaines cognitifs. À trois ans, les phases de sevrage précoce et prolongé sont loin derrière et ces progrès ont eu des années pour se renforcer.\n\nUn message d\'espoir\nLe rétablissement après benzodiazépines est l\'un des parcours les plus exigeants en médecine, et trois années de guérison durable constituent une réussite profonde. Les données sont claires : le cerveau récupère de façon importante, la plupart des personnes retrouvent clarté, sommeil et amplitude émotionnelle, et l\'amélioration se poursuit avec le temps.';

  @override
  String get cocaineReferenceDay1 =>
      'Sevrage de la cocaïne : les premières 24 heures\n\nSource : « Withdrawal Syndromes », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nLa cocaïne et le cerveau\nLa cocaïne bloque la recapture de la dopamine — ainsi que d\'autres monoamines — dans les circuits de récompense du cerveau, ce qui provoque son accumulation et entraîne une euphorie et une énergie intenses. Avec un usage régulier, le cerveau s\'adapte en réduisant l\'activité de ce système, si bien que sans la substance les activités ordinaires semblent ternes.\n\nLe crash\nStatPearls décrit le sevrage stimulant comme commençant par un « crash » à l\'arrêt, caractérisé par une dépression marquée, un sommeil excessif, de la faim, une baisse de moral et un ralentissement important des mouvements et de la pensée. Pendant les premières 24 heures, cela comprend généralement :\n• Fatigue extrême et besoin accru de sommeil\n• Humeur dépressive et ralentissement des mouvements et de la pensée\n• Augmentation de l\'appétit (la cocaïne le supprime)\n\nLes envies, l\'irritabilité et l\'anxiété sont également très fréquemment rapportées pendant cette période dans la littérature plus large sur les dépendances, même si StatPearls ne les détaille pas spécifiquement dans le crash.\n\nContrairement à certaines autres substances\nStatPearls indique que le sevrage stimulant est pris en charge par observation et soins de soutien ; contrairement au sevrage de l\'alcool ou des benzodiazépines, il ne provoque généralement ni crises convulsives ni délirium. Le principal danger est psychologique — une dépression et, chez les personnes ayant une consommation importante, des idées suicidaires peuvent survenir pendant le crash ; soutien et surveillance sont donc recommandés.\n\nAucun médicament approuvé\nAucun médicament n\'est actuellement approuvé pour traiter spécifiquement le sevrage de la cocaïne ; la prise en charge est de soutien, et des approches non médicamenteuses comme la gestion des contingences constituent des traitements fondés sur les données pour le trouble d\'usage sous-jacent.';

  @override
  String get cocaineReferenceDay3 =>
      'Trois jours sans cocaïne : traverser le pic de difficulté\n\nSource : « Cocaine Toxicity », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nComment la cocaïne affecte le corps\nStatPearls indique que la cocaïne bloque la recapture de la dopamine, de la noradrénaline et de la sérotonine, prolongeant la stimulation sympathique. C\'est ce qui produit à la fois son euphorie et sa dangerosité — elle peut affecter presque tous les organes.\n\nJours 2 à 4 : pic du sevrage psychologique\nAu troisième jour, le crash aigu laisse place au sevrage psychologique le plus intense :\n• Baisse de moral et humeur dépressive maximales\n• Perte de plaisir\n• Fortes envies déclenchées par des signaux\n• Anxiété et agitation\n• Sommeil perturbé — excessif chez certains, insomnie chez d\'autres\n\nLe danger cardiovasculaire recule\nStatPearls identifie la toxicité cardiovasculaire comme l\'effet le plus mortel de la cocaïne : hausse du rythme cardiaque et de la tension, augmentation des besoins du myocarde en oxygène, spasme coronaire et activation plaquettaire — entraînant un risque d\'arythmie, d\'infarctus et d\'AVC, même chez les jeunes. La demi-vie de la cocaïne elle-même est courte, environ une heure, et au troisième jour la substance a été éliminée ; StatPearls note toutefois que ses métabolites peuvent encore provoquer une constriction des vaisseaux pendant des heures après la prise et que l\'un d\'eux peut persister pendant des semaines, si bien qu\'une partie de la contrainte cardiovasculaire peut durer plus longtemps que la substance elle-même.\n\nLa suite\nLa phase aiguë est intense, mais ce sont les symptômes psychologiques — dépression, envies, perte de plaisir — qui nécessitent le plus de soutien et persistent le plus longtemps.';

  @override
  String get cocaineReferenceDay7 =>
      'Une semaine sans cocaïne : début de la récupération physique\n\nSource : « Withdrawal Syndromes », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nLa phase aiguë se termine\nStatPearls décrit le sevrage de la cocaïne comme passant du crash initial à une phase de récupération plus longue. À la fin de la première semaine, les pires symptômes diminuent généralement tandis que le système dopaminergique continue de se reconstruire.\n\nRécupération physique en cours\nQuand la stimulation sympathique de la cocaïne cesse, ses effets cardiovasculaires, sur l\'appétit, le sommeil et les voies respiratoires commencent à s\'inverser au cours des jours et semaines suivants :\n• Rythme cardiaque et tension artérielle revenant vers la normale\n• Appétit revenant progressivement (la cocaïne le supprime fortement)\n• Sommeil commençant à se stabiliser\n• Voies nasales commençant à guérir si la cocaïne était sniffée\n\nLes symptômes psychologiques continuent\nStatPearls indique que la dépression et la perte de plaisir sont caractéristiques du sevrage stimulant et durent plus longtemps que les symptômes physiques :\n• L\'humeur reste basse, mais moins sévère qu\'au pic\n• Les envies déclenchées par des signaux restent fortes\n• La concentration et la motivation sont encore altérées\n\nPhase post-aiguë\nLe sevrage évolue ensuite vers des semaines ou des mois d\'amélioration plus régulière de l\'humeur, des envies et de la clarté mentale. Connaître ce schéma aide à traverser la partie plus lente du rétablissement.';

  @override
  String get cocaineReferenceDay14 =>
      'Deux semaines sans cocaïne : retrouver la stabilité\n\nSource : « Withdrawal Syndromes », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nAprès deux semaines\nÀ deux semaines, les symptômes sévères du crash — dépression profonde, sommeil excessif, ralentissement des mouvements et de la pensée — se sont généralement atténués. Le rétablissement se concentre maintenant sur la reconstruction de la santé cérébrale et émotionnelle.\n\nHumeur et état émotionnel\nÀ deux semaines, l\'humeur peut rester inférieure à la normale pendant que le système dopaminergique récupère. Par rapport à la première semaine, la profonde perte de plaisir diminue et de vrais moments de bien-être reviennent.\n\nEnvies et déclencheurs\nLes envies déclenchées par des signaux représentent un défi important à ce stade. Le cerveau a créé de fortes associations entre l\'usage de cocaïne et certains lieux, personnes, émotions et activités. Rencontrer ces déclencheurs peut provoquer de fortes envies même lorsque l\'humeur générale s\'améliore. Éviter les environnements à haut risque et créer de nouvelles associations est important.\n\nAmélioration du sommeil\nLe sommeil est généralement plus stable et réparateur à deux semaines que pendant la phase aiguë. Cette amélioration a un effet positif important sur l\'humeur, la clarté mentale et la capacité à gérer les envies.\n\nConstruire les bases\nLes traitements fondés sur les données pour les troubles liés aux stimulants étant comportementaux — gestion des contingences, thérapie et soutien par les pairs — la marque des deux semaines est un moment important pour s\'engager dans les structures de soutien qui porteront le rétablissement à long terme.';

  @override
  String get cocaineReferenceDay60 =>
      'Deux mois sans cocaïne : l\'humeur et le système de récompense commencent à récupérer\n\nSource : « Recovering from Cocaine: Insights from Clinical and Preclinical Investigations », Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nCe que fait le cerveau\nCette revue synthétise des études humaines et animales sur ce qui arrive au cerveau après l\'arrêt de la cocaïne. L\'usage chronique modifie le système dopaminergique et réduit l\'activité du cortex frontal ; la récupération de ces systèmes sous-tend les améliorations d\'humeur et de motivation observées au début de l\'abstinence.\n\nProgrès du système de récompense\nDans les études animales, les modifications des récepteurs de la dopamine et des protéines de recyclage liées à la cocaïne évoluaient vers des niveaux plus sains avec une abstinence durable. À mesure que le système de récompense récupère, la profonde perte de plaisir diminue et les récompenses ordinaires — nourriture, liens sociaux, accomplissement — redeviennent gratifiantes.\n\nSignal de récupération\nÀ deux mois, l\'humeur s\'améliore et le sommeil est plus stable tandis que les systèmes dopaminergique et frontal continuent de se reconstruire. Les études chez les primates montrent que les modifications des récepteurs D1 et des transporteurs liées à la cocaïne reviennent vers les niveaux témoins avec une abstinence durable.';

  @override
  String get cocaineReferenceDay90 =>
      'Trois mois sans cocaïne : rebond des marqueurs dopaminergiques\n\nSource : « Recovering from Cocaine: Insights from Clinical and Preclinical Investigations », Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nPourquoi 90 jours sont une étape importante\nCette revue souligne que le point des trois mois est biologiquement significatif. Chez des primates non humains, les récepteurs dopaminergiques D1 et les transporteurs que la cocaïne avait augmentés montraient des « signes de retour aux niveaux témoins » après environ 90 jours d\'abstinence — preuve directe que le système de récompense peut se réadapter une fois la substance supprimée.\n\nL\'avant du cerveau\nLes auteurs soulignent la récupération de la partie frontale du cerveau comme l\'un des signes les plus importants d\'une abstinence prolongée. Cette région gère le contrôle des impulsions, la prise de décision et le contrôle de soi ; ces capacités se renforcent à mesure qu\'elle récupère.\n\nCe que montrent 90 jours\nÀ 90 jours, les études chez les primates ont trouvé des densités de récepteurs D1, D2 et de transporteurs de dopamine qui n\'étaient plus significativement différentes de celles des témoins sans drogue. Même après une exposition prolongée, une récupération importante du système dopaminergique est déjà visible à ce stade et se poursuit avec l\'abstinence.';

  @override
  String get cocaineReferenceDay180 =>
      'Six mois sans cocaïne : une pensée plus claire\n\nSource : « Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies », PubMed Central\n\nUne récupération visible en imagerie\nCette revue regroupe des études longitudinales d\'imagerie cérébrale qui examinent les mêmes personnes à plusieurs reprises à mesure que l\'abstinence s\'allonge. Pour la cocaïne, elle rapporte une récupération mesurable de l\'activité fonctionnelle avec une abstinence durable.\n\nDonnées d\'imagerie cérébrale\nDeux études d\'IRM fonctionnelle ont suivi des consommateurs de cocaïne au fil du temps et toutes deux ont constaté une meilleure activation du mésencéphale et du thalamus avec une abstinence plus longue. Dans l\'une d\'elles, après environ six mois, le schéma d\'activation cérébrale était comparable à celui de témoins sains non dépendants. Toutes substances confondues, la revue indique que les résultats de l\'imagerie nucléaire suggèrent une récupération dopaminergique avec l\'abstinence.\n\nCe que cela signifie à six mois\nCes gains fonctionnels correspondent aux améliorations réelles rapportées à ce stade :\n• Meilleure attention et mémoire de travail\n• Prise de décision et contrôle des impulsions plus efficaces\n• Humeur et régulation émotionnelle plus stables\n\nSignal de récupération\nVers six mois, une cohorte longitudinale d\'IRMf montrait un schéma d\'activation comparable à celui de témoins sains non dépendants, tandis que l\'activation du mésencéphale et des structures profondes s\'améliorait avec la durée de l\'abstinence. Il s\'agit d\'une récupération fonctionnelle directement visible en imagerie.';

  @override
  String get cocaineReferenceDay365 =>
      'Un an sans cocaïne : la contrainte cardiovasculaire disparaît\n\nSource : « Cocaine Toxicity », StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nPourquoi le cœur est central\nStatPearls identifie la toxicité cardiovasculaire comme l\'effet le plus mortel de la cocaïne. Chaque prise augmente le rythme cardiaque, la tension et les besoins du myocarde en oxygène tout en provoquant un spasme coronaire et en favorisant la formation de caillots — une combinaison qui entraîne infarctus, arythmie et AVC même chez les jeunes.\n\nCe qu\'une année d\'abstinence supprime\nChaque journée sans cocaïne est une journée sans ces agressions aiguës. Sur une année, les poussées répétées de tension et de rythme cardiaque ont disparu, le risque de spasme coronaire et d\'infarctus aigu provoqués par la cocaïne est éliminé, et le cœur n\'est plus poussé vers un déséquilibre entre besoins et apport en oxygène.\n\nSignal de récupération\nL\'arrêt de la cocaïne met fin aux spasmes coronaires, à la tachycardie, à l\'hypertension, à la promotion des caillots et au déséquilibre en oxygène répétés qui entraînent les lésions cardiaques aiguës. Une fibrose ou une myocardite existante reste un problème médical, mais l\'agression répétée déclenchée par la cocaïne a cessé.\n\nLe cerveau récupère aussi\nÀ un an, les systèmes de récompense et de contrôle de soi ont eu beaucoup de temps pour récupérer, favorisant un meilleur contrôle des impulsions, une humeur plus stable et une réponse plus forte aux récompenses ordinaires.';

  @override
  String get cocaineReferenceDay730 =>
      'Deux ans sans cocaïne : rétablissement durable\n\nSource : « Recovering from Cocaine: Insights from Clinical and Preclinical Investigations », Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nLa perspective à long terme\nCette revue rassemble ce que les études humaines et animales montrent sur l\'abstinence prolongée de cocaïne. Sa conclusion centrale est que la préservation et la récupération du fonctionnement du cortex frontal constituent le marqueur le plus important de l\'abstinence à long terme — les personnes abstinentes depuis plus de 10 mois montraient davantage d\'activité frontale que celles abstinentes depuis moins longtemps.\n\nCe qui continue de guérir\n• Les marqueurs dopaminergiques modifiés par la cocaïne continuent d\'évoluer vers la normale avec l\'abstinence\n• La diminution de l\'intégrité de la matière grise et blanche observée pendant l\'usage actif et au début de l\'abstinence peut s\'inverser sur une abstinence plus longue, possiblement grâce à la maturation continue de la myéline\n• Les circuits de contrôle frontal — contrôle des impulsions, jugement, régulation émotionnelle — se renforcent\n\nSignal de récupération\nLes auteurs apportent une prudence scientifique réelle : une partie des différences observées chez les abstinents de longue durée peut refléter un « effet survivant » — les personnes ayant au départ une meilleure intégrité cérébrale peuvent avoir plus de facilité à rester abstinentes — plutôt que la récupération seule. Ce qui est clair, c\'est que deux années sans cocaïne favorisent un cerveau fonctionnant bien plus près de celui d\'un non-consommateur, et une vie non seulement abstinente mais profondément reconstruite.';

  @override
  String get ghbReferenceDay1 =>
      'Sevrage du GHB : les premières heures\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\n⚠ Il s\'agit d\'une urgence médicale\nLe sevrage du GHB fait partie des plus dangereux, comparable aux sevrages sévères de l\'alcool et des benzodiazépines. Sans traitement, il peut évoluer vers un délirium dans plus de la moitié des cas, avec de dangereuses variations du rythme cardiaque et de la tension ainsi que des crises convulsives. Toute personne dépendante au GHB, au GBL ou au 1,4-butanediol doit rechercher une désintoxication hospitalière supervisée plutôt que d\'arrêter seule.\n\nPourquoi il commence si vite\nLa demi-vie du GHB n\'est que de 30 à 60 minutes, et les personnes dépendantes doivent généralement reprendre une dose toutes les 2 à 3 heures simplement pour éviter le sevrage — bien plus vite qu\'avec l\'alcool ou les benzodiazépines. Cette pharmacocinétique rapide explique pourquoi les symptômes peuvent apparaître beaucoup plus tôt qu\'avec d\'autres sevrages de sédatifs-hypnotiques.\n\nSymptômes précoces\nAnxiété, insomnie, tremblements, sueurs, accélération du rythme cardiaque et hausse de la tension.';

  @override
  String get ghbReferenceDay3 =>
      'Sevrage du GHB : les jours les plus difficiles\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nLa période la plus rude\nCette étude a constaté que plusieurs symptômes centraux — douleurs musculaires, contractions musculaires, sensation de tension et de stress, rythme cardiaque rapide et crampes abdominales — étaient à leur maximum pendant les trois premiers jours, avec une baisse de plus de 70 % de la sévérité de nombreux symptômes au quatrième jour. Cette fenêtre précoce est généralement la période de risque maximal, lorsque le sevrage non traité est le plus susceptible d\'évoluer vers un délirium, des crises convulsives ou de dangereuses variations du rythme cardiaque et de la tension.\n\nManifestations sévères\n• Agitation et anxiété sévères\n• Hallucinations auditives et visuelles, paranoïa\n• Tremblements, sueurs, cœur qui s\'emballe et hypertension\n• Risque de crises convulsives\n\nPrise en charge\nL\'étude décrit la diminution progressive de benzodiazépines et celle de GHB pharmaceutique comme deux méthodes courantes de désintoxication, avec certaines données suggérant qu\'une diminution du GHB peut mieux contrôler les symptômes que les benzodiazépines seules. Les deux approches exigent une surveillance étroite — ce sevrage n\'est pas sûr à gérer à domicile.';

  @override
  String get ghbReferenceDay7 =>
      'Une semaine sans GHB\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nLa plupart des symptômes s\'estompent\nPlusieurs symptômes centraux ont diminué de plus de 70 % en sévérité ou en fréquence pendant les quatre premiers jours. Sous diminution supervisée, la phase de réduction durait en moyenne 11 jours, suivie d\'une phase de récupération d\'environ six jours — après une semaine, beaucoup sont donc déjà bien engagés dans l\'amélioration même si le processus n\'est pas terminé.\n\nCe qui peut persister\n• Sueurs, tremblements et mains qui tremblent\n• Sommeil excessif ou, au contraire, insomnie et agitation\n• Envies\n\nL\'étude a constaté que ces symptômes particuliers changeaient relativement peu même jusqu\'à 11 jours ; leur persistance cette semaine n\'est donc pas inhabituelle. Une surveillance médicale continue reste importante jusqu\'à ce que le syndrome soit clairement résolu.';

  @override
  String get ghbReferenceDay14 =>
      'Deux semaines sans GHB\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nAprès le syndrome aigu\nÀ deux semaines, le syndrome physique aigu décrit dans cette étude — dont les phases de diminution et de récupération totalisent en moyenne environ 17 jours sous traitement supervisé — est généralement résolu ou presque. Le rythme cardiaque, la tension et la plupart des symptômes physiques devraient se stabiliser.\n\nCe qui persiste\nL\'étude signale spécifiquement que les envies et l\'insomnie sont encore présentes à la sortie chez certains patients et qu\'elles peuvent contribuer au risque de rechute. Le soutien et la structure restent importants, même si la dangereuse phase initiale est derrière vous.';

  @override
  String get ghbReferenceDay30 =>
      'Un mois sans GHB\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nOù se situe un mois\nÀ un mois, la phase aiguë et dangereuse décrite dans cette étude est loin derrière. Cette phase — concentrée pendant les premiers jours puis suivie d\'une diminution supervisée et d\'une récupération totalisant en moyenne environ deux semaines et demie — est passée. Les envies et l\'insomnie sont les principaux risques résiduels de rechute identifiés à la sortie.\n\nPourquoi le soutien aide encore\nSi des envies, une baisse de moral ou des troubles du sommeil sont encore présents à un mois, cela correspond aux facteurs de risque de rechute signalés par les auteurs — d\'où l\'importance de conserver du soutien et une structure.';

  @override
  String get ghbReferenceDay90 =>
      'Trois mois sans GHB\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nTrois mois de rétablissement\nÀ trois mois, le syndrome aigu de sevrage du GHB est résolu depuis longtemps. Les risques résiduels identifiés à la sortie sont les envies et l\'insomnie ; trois mois d\'abstinence donnent donc au sommeil, à la stabilité du système autonome et aux routines de prévention de la rechute beaucoup de temps pour se consolider.\n\nCe que les personnes rapportent souvent\n• Une humeur habituelle plus calme\n• Un sommeil plus fiable\n• Une pensée plus claire et moins d\'envies\n\nSi l\'anxiété, l\'insomnie ou la baisse de moral restent importantes à trois mois, il vaut mieux en parler à un clinicien plutôt que supposer qu\'elles disparaîtront seules.';

  @override
  String get ghbReferenceDay180 =>
      'Six mois sans GHB\n\nSource : « Characterization of the GHB Withdrawal Syndrome », PubMed Central\n\nSix mois plus tard\nÀ six mois, le syndrome aigu est résolu depuis longtemps et le rétablissement est passé entièrement de la désintoxication à la stabilité du sommeil, au contrôle des envies et à la prévention de la rechute. La dangereuse phase autonome avec risque de délirium appartient aux premiers jours et semaines, pas à ce stade.\n\nVue d\'ensemble\nTraverser le sevrage du GHB en sécurité et rester abstinent six mois est une réussite majeure compte tenu de la dangerosité de la phase initiale et du risque réel de rechute — alimenté notamment par les envies et l\'insomnie persistantes. Les routines et le soutien qui vous ont mené jusqu\'ici méritent d\'être conservés.';

  @override
  String get inhalantsReferenceDay1 =>
      'Arrêter les substances inhalées : premier jour\n\nSource : Radparvar, « The Clinical Assessment and Treatment of Inhalant Abuse », The Permanente Journal (2023), PubMed Central\n\nPourquoi le sevrage survient\nL\'usage chronique de substances inhalées provoque une neuroadaptation — le système nerveux finit par s\'attendre à la substance. Beaucoup affectent les mêmes circuits cérébraux que l\'alcool, si bien que l\'arrêt laisse temporairement le cerveau en déséquilibre. Les produits chimiques quittent rapidement le sang mais sont stockés dans les tissus adipeux, ce qui rend le calendrier du sevrage imprévisible.\n\nSymptômes précoces\nCette revue décrit un sevrage ressemblant à celui de l\'alcool ou des benzodiazépines, avec notamment :\n• Nausées, vomissements et sueurs\n• Tremblements et accélération du rythme cardiaque\n• Insomnie et troubles du sommeil\n• Anxiété et irritabilité\n\nRemarque de sécurité\nDans les cas plus sévères, la revue mentionne aussi hallucinations, délires et crises convulsives parmi les symptômes rapportés, sans établir un calendrier précis jour par jour — il faut les considérer comme des symptômes possibles, pas comme une chronologie fixe. Une supervision médicale est prudente pendant la désintoxication, surtout chez les consommateurs importants et de longue durée.';

  @override
  String get inhalantsReferenceDay7 =>
      'Une semaine sans substances inhalées\n\nSource : Radparvar, « The Clinical Assessment and Treatment of Inhalant Abuse », The Permanente Journal (2023), PubMed Central\n\nLa fenêtre aiguë\nLa littérature clinique décrit le sevrage comme ressemblant à celui de l\'alcool ou des benzodiazépines, mais généralement plus court. À la fin de la première semaine, les symptômes physiques aigus — nausées, tremblements, sueurs, insomnie — sont généralement en train de se résoudre chez la plupart des personnes.\n\nCe qui reste\n• Fatigue et brouillard mental\n• Humeur basse ou instable\n• Envies\n\nRemarque sur le début de l\'abstinence\nLe brouillard mental à ce stade ne signifie pas des dommages durables — le cerveau continue de se réadapter. La récupération spécifique de la pensée et de la mémoire au cours des semaines et mois suivants est abordée dans les étapes ultérieures.';

  @override
  String get inhalantsReferenceDay14 =>
      'Deux semaines sans substances inhalées\n\nSource : Radparvar, « The Clinical Assessment and Treatment of Inhalant Abuse », The Permanente Journal (2023), PubMed Central\n\nAprès la phase aiguë\nLes revues cliniques décrivent le sevrage comme semblable à celui de l\'alcool ou des benzodiazépines mais plus court. Après deux semaines, les nausées, tremblements, insomnie et anxiété se sont généralement calmés.\n\nLa suite du chemin\nL\'attention, la mémoire, les mouvements et la coordination récupèrent plus progressivement au cours des mois suivants. L\'abstinence continue donne à tous ces systèmes le temps de s\'améliorer. Une bonne alimentation — l\'usage de substances inhalées peut épuiser la vitamine B12 — et l\'abstinence créent les conditions de cette récupération.';

  @override
  String get inhalantsReferenceDay30 =>
      'Un mois sans substances inhalées\n\nSource : Dingwall et al., « Cognitive recovery during and after treatment for volatile solvent abuse », Drug and Alcohol Dependence (2011), PubMed\n\nOù se situe un mois\nLa période de sevrage précoce est loin derrière vous. Dans cette étude, certaines capacités d\'apprentissage s\'amélioraient en six semaines, tandis que la coordination visuelle, la mémoire, la planification et la prise de décision progressaient plus graduellement au cours des mois suivants.\n\nCe qui peut s\'améliorer\n• Attention et certaines tâches d\'apprentissage\n• Humeur et sommeil à mesure que le corps se stabilise\n• Vitesse motrice, progressivement\n\nSignal de récupération\nLa conclusion de l\'étude est claire : mémoire, planification et prise de décision s\'améliorent progressivement sur des mois ou des années d\'abstinence. La poursuite de l\'abstinence est le moteur le plus puissant de cette récupération.';

  @override
  String get inhalantsReferenceDay90 =>
      'Trois mois sans substances inhalées\n\nSource : Dingwall et al., « Cognitive recovery during and after treatment for volatile solvent abuse », Drug and Alcohol Dependence (2011), PubMed\n\nUn processus inégal et plus long\nCette étude a suivi des personnes au-delà d\'un programme de traitement de huit semaines et en a réévalué certaines environ un an plus tard. Certaines capacités d\'apprentissage se sont améliorées en six semaines, tandis que la coordination visuelle, la mémoire, la planification et la prise de décision ont continué à progresser plus longtemps.\n\nPoursuivre le cap\nL\'étude montre que les capacités plus lentes à récupérer s\'améliorent progressivement sur des mois ou des années. À trois mois, poursuivre l\'abstinence reste le levier le plus fort pour ajouter de la récupération mois après mois.';

  @override
  String get inhalantsReferenceDay365 =>
      'Un an sans substances inhalées\n\nSource : « A prospective study of neurocognitive changes 15 years after chronic inhalant abuse », PubMed\n\nUne récupération réelle et mesurable\nUne étude à long terme a constaté une récupération importante des problèmes cérébraux et cognitifs liés à un usage chronique après deux ans d\'abstinence. À un an, vous êtes déjà bien engagé sur cette trajectoire.\n\nCe que cela signifie\nLa mémoire, l\'attention et la fonction motrice continuent de s\'améliorer. L\'abstinence à long terme produit une véritable récupération cérébrale : à deux ans, la plupart des scores concernant le cerveau, la mémoire et la pensée étaient revenus à la normale chez les consommateurs chroniques qui ne présentaient pas de lésions cérébrales dues au plomb.';

  @override
  String get inhalantsReferenceDay730 =>
      'Deux ans sans substances inhalées\n\nSource : « A prospective study of neurocognitive changes 15 years after chronic inhalant abuse », PubMed\n\nLe cap des deux ans\nC\'est l\'étape clé de la recherche : les déficits reflétant des lésions cérébrales dues à l\'usage prolongé de solvants montraient une récupération importante après deux ans d\'abstinence. Les auteurs ont conclu qu\'en l\'absence de lésions liées à l\'essence au plomb, une abstinence prolongée peut permettre le retour d\'un fonctionnement cérébral normal.\n\nSignal de récupération\nLa principale exception concerne les dommages liés à l\'abus d\'essence au plomb, qui peuvent entraîner des déficits persistants. Sinon, deux ans d\'abstinence représentent la meilleure fenêtre documentée permettant au cerveau de guérir — en parallèle d\'une vie reconstruite.';

  @override
  String get ketamineReferenceDay1 =>
      'Arrêter la kétamine : premier jour\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug », PubMed Central\n\nUn sevrage surtout psychologique\nContrairement aux opioïdes ou à l\'alcool, la kétamine provoque rarement un sevrage physique sévère. L\'arrêt est généralement sûr ; les personnes luttent plus souvent contre les envies et la dépendance psychologique que contre une maladie physique.\n\nCe que vous pouvez ressentir\n• Variations d\'humeur et baisse de moral\n• Envies\n• Sueurs ou palpitations occasionnelles\n\nL\'étape essentielle\nPour toute personne présentant des symptômes vésicaux, l\'arrêt immédiat et complet est le point de départ obligatoire de la récupération — le premier jour est donc la décision la plus importante.';

  @override
  String get ketamineReferenceDay7 =>
      'Une semaine sans kétamine\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review », PubMed Central\n\nLa phase psychologique\nLe principal défi du début de l\'arrêt est psychologique : envies, humeur modifiée ou basse et brouillard mental. Le sevrage physique, lorsqu\'il existe, est généralement léger.\n\nLe brouillard mental est fréquent à ce stade — la concentration demande un effort, le temps de réaction est plus lent et la mémoire à court terme peut sembler peu fiable. Ces effets sur la pensée et la mémoire s\'améliorent avec l\'abstinence : une étude longitudinale portant sur 114 utilisateurs de kétamine a trouvé des gains importants de mémoire verbale, mémoire visuelle, vitesse de traitement, planification, concentration et prise de décision après 12 semaines sans kétamine.\n\nSymptômes vésicaux\nSi vous souffrez de cystite induite par la kétamine — urgence ou fréquence urinaires, douleur ou sang dans les urines — arrêter maintenant donne à la vessie sa meilleure chance de guérir. La douleur peut pousser à reprendre de la kétamine pour s\'automédiquer ; mieux vaut rompre ce cycle avec une prise en charge adaptée de la douleur.';

  @override
  String get ketamineReferenceDay14 =>
      'Deux semaines sans kétamine\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review », PubMed Central\n\nUne pensée plus claire\nLa substance étant entièrement éliminée, le brouillard mental et la pensée déconnectée associés à un usage régulier commencent à s\'atténuer. La mémoire et la concentration s\'améliorent et l\'humeur se stabilise.\n\nDébut de la récupération vésicale\nPour la cystite à un stade précoce, la revue souligne que le simple fait d\'arrêter la kétamine est l\'étape la plus importante pour inverser les symptômes et qu\'un arrêt plus précoce offre les meilleures chances de récupération avant que les dommages deviennent permanents. Deux semaines d\'abstinence marquent le début de ce processus.';

  @override
  String get ketamineReferenceDay30 =>
      'Un mois sans kétamine\n\nSource : « Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users », Winstock et al., BJU International (2012)\n\nRécupération de la vessie\nLe traitement le plus important de la cystite induite par la kétamine est l\'arrêt de la kétamine. Cette étude d\'utilisateurs récréatifs a constaté que 51 % des personnes présentant des symptômes urinaires signalaient une amélioration après l\'arrêt, contre moins de 4 % dont l\'état s\'aggravait. Plus l\'arrêt est précoce, meilleur est le résultat.\n\nEsprit et humeur\nLa cognition et l\'humeur continuent de s\'éclaircir à un mois. Le soutien psychologique et social améliore de façon significative les chances de rester abstinent — l\'arrêt fonctionne mieux lorsqu\'il est accompagné.';

  @override
  String get ketamineReferenceDay90 =>
      'Trois mois sans kétamine\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review », PubMed Central\n\nRécupération continue\nLa récupération de la vessie après la kétamine est souvent progressive ; la revue décrit une amélioration de la sévérité des symptômes après l\'arrêt, même si elle peut être longue et variable. Trois mois donnent aux voies urinaires un temps prolongé pour guérir dans les cas qui répondent à l\'arrêt.\n\nEsprit\nLa pensée et l\'humeur sont nettement plus claires qu\'au début de l\'abstinence, et les envies moins fréquentes. Des symptômes vésicaux persistants ou sévères doivent être évalués par un urologue.';

  @override
  String get ketamineReferenceDay180 =>
      'Six mois sans kétamine\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review », PubMed Central\n\nSix mois plus tard\nAvec une abstinence durable, les symptômes vésicaux continuent de s\'améliorer dans les cas qui répondent à l\'arrêt, et la pensée, la mémoire et l\'humeur sont stables. La compulsion à consommer s\'est considérablement affaiblie.\n\nSignal de récupération\nLa récupération de lésions vésicales déjà établies peut être incomplète, ce qui explique l\'importance d\'un arrêt précoce. Quel que soit le stade auquel vous avez arrêté, rester abstinent donne à la vessie la meilleure issue possible.';

  @override
  String get ketamineReferenceDay365 =>
      'Un an sans kétamine\n\nSource : « Ketamine-Induced Cystitis: A Comprehensive Review », PubMed Central\n\nUn an plus tard\nDouze mois d\'abstinence donnent à la vessie, lorsque les lésions ont été détectées tôt, sa meilleure chance de récupérer et laissent la pensée, la mémoire et l\'humeur stables et claires. La dépendance psychologique qui rendait l\'arrêt difficile s\'est largement estompée.\n\nVue d\'ensemble\nUne année de liberté représente un changement profond — en santé physique, en clarté et en autonomie. Conserver le soutien qui vous a permis d\'arriver jusque-là aide à le protéger.';

  @override
  String get kratomReferenceDay1 =>
      'Sevrage du kratom : le premier jour\n\nSource : Swogger et al. (2022), « Understanding Kratom Use: A Guide for Healthcare Providers », Frontiers in Pharmacology\n\nPourquoi le sevrage survient\nLes composés actifs du kratom agissent sur les mêmes récepteurs opioïdes que les opioïdes classiques. Avec un usage régulier, le corps s\'adapte ; l\'arrêt produit donc un sevrage de type opioïde. Ce guide clinique décrit la dépendance et le sevrage comme des risques reconnus d\'un usage régulier de kratom.\n\nCe que montrent les données sur le début\nLes études animales citées dans le guide montrent des signes physiques de sevrage apparaissant en environ 12 heures, avec des effets de type anxieux visibles à 24 heures ; le calendrier précis chez l\'humain est moins bien établi, mais les symptômes précoces fréquemment rapportés comprennent :\n• Agitation, anxiété et irritabilité\n• Douleurs musculaires et écoulement nasal\n• Sueurs et larmoiement\n• Envies\n\nRemarque sur la sévérité\nLe guide indique qu\'une durée d\'usage plus longue et des doses plus élevées sont liées à un sevrage plus sévère et plus prolongé. Un accompagnement médical supervisé peut être utile, surtout si le kratom était consommé à fortes doses ou avec des opioïdes.';

  @override
  String get kratomReferenceDay3 =>
      'Sevrage du kratom : les jours les plus difficiles\n\nSource : Singh et al. (2014), Drug and Alcohol Dependence — enquête auprès de 293 consommateurs réguliers de kratom en Malaisie\n\nCe que montrent les données\nPlutôt qu\'un unique « jour de pic » bien défini, cette enquête a constaté que la sévérité du sevrage dépend de la quantité et de la durée d\'usage : les personnes buvant au moins trois verres de kratom par jour avaient une probabilité nettement plus élevée de dépendance sévère et de sevrage difficile. Pour la plupart, les premiers jours après l\'arrêt sont les plus difficiles.\n\nSymptômes fréquemment rapportés\n• Douleurs musculaires et articulaires, jambes sans repos\n• Insomnie malgré l\'épuisement\n• Nausées, crampes abdominales et diarrhée\n• Anxiété, baisse de moral et irritabilité\n• Fortes envies\n\nTraverser cette période\nHydratation, repos et traitement symptomatique peuvent aider. Si le sevrage vous a semblé sévère jusqu\'ici, cela correspond davantage à un usage plus important ou plus long qu\'à quelque chose d\'anormal — et la tendance est à l\'amélioration à partir de là.';

  @override
  String get kratomReferenceDay7 =>
      'Une semaine sans kratom\n\nSource : Swogger et al. (2022), « Understanding Kratom Use: A Guide for Healthcare Providers », Frontiers in Pharmacology\n\nAprès la phase aiguë\nLes données autodéclarées chez l\'humain citées dans ce guide indiquent que les symptômes de sevrage se résolvent en environ un à trois jours pour la plupart des personnes qui arrêtent. Après une semaine, les symptômes physiques aigus — douleurs musculaires, sueurs, nausées — se sont généralement calmés chez la majorité. Ce qui peut rester est plus psychologique : fatigue, sommeil perturbé et baisse de moral pendant que les récepteurs opioïdes stimulés par le kratom se réadaptent aux signaux naturels du corps.\n\nUn risque réel\nLe guide indique aussi qu\'un petit nombre de personnes trouvent le kratom très difficile à arrêter, avec un sevrage plus sévère et plus long chez les consommateurs plus importants et de longue durée. Cette semaine est un point fréquent de rechute et la tolérance baisse rapidement — reprendre une ancienne dose, surtout si des opioïdes sont impliqués, est désormais réellement dangereux.';

  @override
  String get kratomReferenceDay14 =>
      'Deux semaines sans kratom\n\nSource : National Institute on Drug Abuse (NIDA), « Kratom »\n\nAu-delà de la fenêtre étudiée\nLes données humaines contrôlées sur la durée du sevrage du kratom couvrent surtout les premiers jours ; il n\'existe donc pas de recherche bien établie fixant une étape précise à « deux semaines ». Le schéma général est toutefois documenté : le kratom agit sur les mêmes récepteurs opioïdes que les opioïdes classiques et, lorsque l\'usage régulier cesse, ces récepteurs retrouvent progressivement leur sensibilité aux signaux naturels du corps.\n\nCe que les personnes rapportent souvent\n• L\'appétit et l\'énergie s\'améliorent souvent\n• Le sommeil tend à devenir plus fiable\n• L\'humeur est généralement plus stable, même si elle reste variable\n\nLes envies peuvent encore être déclenchées par le stress et des signaux familiers ; conserver un plan pour les gérer reste donc utile.';

  @override
  String get kratomReferenceDay30 =>
      'Un mois sans kratom\n\nSource : National Institute on Drug Abuse (NIDA), « Kratom »\n\nUn système de récompense en récupération\nLe NIDA décrit le kratom comme agissant sur les récepteurs opioïdes du cerveau, la dépendance et le sevrage étant des risques reconnus d\'un usage régulier. Aucune étude ne fixe précisément une étape de récupération à « un mois », mais le schéma général des dépendances fondées sur les récepteurs opioïdes est que la réponse du cerveau aux plaisirs ordinaires se normalise progressivement avec une abstinence durable.\n\nCe qu\'un mois peut construire\nUn mois sans kratom, c\'est un mois pendant lequel un sommeil, des repas et des routines réguliers remplacent le temps et l\'énergie consacrés à la consommation. Les envies ont tendance à survenir moins souvent et à devenir plus gérables, même si les moments de stress élevé restent les plus vulnérables.';

  @override
  String get kratomReferenceDay90 =>
      'Trois mois sans kratom\n\nSource : National Institute on Drug Abuse (NIDA), « Kratom »\n\nUn quotidien plus stable\nLe kratom agit sur les récepteurs opioïdes ; trois mois sans consommation donnent donc aux systèmes cérébraux de récompense et de stress un temps prolongé pour se stabiliser. Beaucoup rapportent une pensée plus claire et une motivation plus régulière à mesure qu\'ils s\'éloignent de l\'usage actif.\n\nPourquoi cela compte\nPlus la consommation est lointaine, plus l\'attrait quotidien du kratom tend à s\'estomper — ce qui fait de cette étape une base solide pour un rétablissement durable.';

  @override
  String get kratomReferenceDay365 =>
      'Un an sans kratom\n\nSource : National Institute on Drug Abuse (NIDA), « Kratom »\n\nBien au-delà du sevrage aigu\nLe NIDA ne publie pas de chronologie spécifique de récupération sur un an pour le kratom, mais une année d\'abstinence durable est très au-delà de la fenêtre aiguë et psychologique précoce documentée dans la recherche. Pour la plupart des personnes arrivées à ce stade, les envies sont rares et beaucoup plus faciles à gérer.\n\nVue d\'ensemble\nUne année d\'abstinence représente un changement important en matière de santé, de finances et d\'autonomie. Rester en lien avec du soutien aide à protéger ces progrès.';

  @override
  String get maoiReferenceDay3 =>
      'Arrêt des IMAO : la phase de risque maximal\n\nSource : Dilsaver (1988), recherches sur les réactions à l\'arrêt des IMAO\n\nAvertissement de sécurité essentiel\nLes IMAO présentent les risques d\'arrêt les plus graves parmi les classes d\'antidépresseurs. Un arrêt brutal — en particulier de la phénelzine et de la tranylcypromine — peut provoquer des réactions sévères comprenant :\n• Anxiété et agitation intenses\n• Parole précipitée et agitation motrice\n• Insomnie ou somnolence\n• Hallucinations\n• Délirium et psychose paranoïde\n\nSi vous présentez ces symptômes, consultez immédiatement.\n\nComment fonctionnent les IMAO\nLes IMAO se lient de façon irréversible aux enzymes monoamine oxydase (MAO-A et MAO-B) et les désactivent. Ces enzymes dégradent normalement la sérotonine, la noradrénaline, la dopamine et la tyramine dans le cerveau et l\'intestin. Comme l\'enzyme elle-même est détruite plutôt que simplement bloquée, la récupération dépend de la production de nouvelles enzymes par le corps, et non de la vitesse à laquelle le médicament quitte le sang.';

  @override
  String get maoiReferenceDay7 =>
      'Une semaine après les IMAO : synthèse des enzymes MAO en cours\n\nSource : « Monoamine Oxidase Inhibitors (MAOIs) » (StatPearls, NCBI Bookshelf)\n\nLe processus de récupération enzymatique\nContrairement aux ISRS, IRSN et ATC — qui inhibent réversiblement la recapture des neurotransmetteurs — les IMAO irréversibles comme la phénelzine et la tranylcypromine détruisent durablement les molécules d\'enzyme monoamine oxydase. La période d\'élimination clinique dépend donc du temps nécessaire au corps pour synthétiser de nouvelles enzymes — environ deux semaines — et non de la vitesse d\'élimination du médicament lui-même.\n\nCe qui se passe après une semaine\n• La synthèse des enzymes MAO-A et MAO-B est bien engagée, environ à mi-chemin de la fenêtre de resynthèse d\'environ deux semaines\n• La phase de risque aigu décrite au troisième jour est en train de passer, même si une surveillance médicale étroite reste importante\n\nPrécautions alimentaires\nLe traitement par IMAO exige une alimentation pauvre en tyramine, puisque ces enzymes dégradent normalement la tyramine et l\'empêchent de déclencher une crise hypertensive. Les recommandations sont de maintenir ces restrictions pendant toute la fenêtre de resynthèse — votre prescripteur vous indiquera quand il est sûr de les assouplir.';

  @override
  String get maoiReferenceDay14 =>
      'Deux semaines après les IMAO : activité enzymatique MAO largement rétablie\n\nSource : Fritz et al. (1983), Biological Psychiatry\n\nLe cap critique des deux semaines\nDeux semaines constituent le délai clinique standard de récupération des enzymes MAO après l\'arrêt d\'un IMAO irréversible comme la tranylcypromine ou la phénelzine. En étudiant la tranylcypromine, ces chercheurs ont constaté que l\'activité catalytique de la MAO-B plaquettaire — fortement réduite dans la journée suivant la prise — revenait à la normale en environ deux semaines, à mesure que le corps remplace les plaquettes affectées par de nouvelles portant des enzymes actives, alors même que la quantité totale de protéine MAO-B ne changeait pas.\n\nRécupération des enzymes MAO\n• L\'activité MAO-B plaquettaire a largement récupéré à ce stade\n• Les MAO-A et MAO-B du cerveau, dont le calendrier de resynthèse est globalement similaire, sont elles aussi largement restaurées\n• Le métabolisme normal de la tyramine se rétablit — les restrictions alimentaires liées aux IMAO peuvent généralement être assouplies en concertation avec votre prescripteur\n\nRetour de l\'équilibre neurochimique\nAvec la récupération de l\'activité MAO, les systèmes neurochimiques affectés par les IMAO reviennent sous régulation naturelle :\n• La sérotonine, la noradrénaline et la dopamine ne sont plus maintenues élevées par l\'inhibition des MAO\n• L\'hypersensibilité des récepteurs monoaminergiques, liée aux taux élevés prolongés sous IMAO, commence à se résoudre\n• La régulation naturelle de l\'humeur et de l\'énergie revient';

  @override
  String get maoiReferenceDay30 =>
      'Un mois après les IMAO : rééquilibrage des systèmes neurochimiques\n\nSource : « Monoamine Oxidase Inhibitors (MAOIs) » (StatPearls, NCBI Bookshelf)\n\nBilan à un mois\nUn mois après l\'arrêt se situe bien au-delà de la fenêtre d\'environ deux semaines de resynthèse des enzymes MAO décrite par cette source. À ce stade, l\'activité enzymatique a complètement récupéré et les systèmes neurochimiques fonctionnent sous une régulation entièrement naturelle.\n\nCe qui a récupéré à un mois\n• Activité MAO complète : MAO-A et MAO-B pleinement opérationnelles\n• Fin des restrictions alimentaires : alimentation normale sans restriction de tyramine\n• Dégradation naturelle de la sérotonine : cycle normal de renouvellement restauré\n• Régulation naturelle des catécholamines : dopamine et noradrénaline régulées par l\'activité MAO naturelle\n\nPrécautions concernant les interactions médicamenteuses\nLes IMAO sont associés à des interactions potentiellement très graves avec les médicaments sérotoninergiques. Ces risques d\'interaction ont pris fin à un mois. Informez néanmoins toujours votre prescripteur et votre pharmacien de tout usage antérieur d\'IMAO lorsqu\'un nouveau médicament est prescrit.';

  @override
  String get maoiReferenceDay90 =>
      'Trois mois après les IMAO : bien au-delà du sevrage\n\nSource : « Antidepressant Withdrawal Syndrome », Therapeutics Letter 112 (2018), Therapeutics Initiative, NCBI Bookshelf\n\nLe sevrage dans les différentes classes d\'antidépresseurs\nCette revue considère le sevrage des antidépresseurs comme un phénomène réel de tolérance et de dépendance — plaçant les antidépresseurs « aux côtés des opiacés et des benzodiazépines ». Les données détaillées portent surtout sur les ISRS et IRSN, mais des réactions de sevrage sont reconnues pour toutes les classes, y compris après un IMAO. Les symptômes « apparaissent généralement dans les jours suivant l\'arrêt » et « la plupart… se résolvent en deux semaines », même si certains durent davantage.\n\nOù se situent trois mois\nÀ trois mois, la phase aiguë est loin derrière la grande majorité des personnes et le corps s\'est depuis longtemps réadapté à réguler les monoamines sans inhibition des MAO.\n\nSignal de récupération et « resensibilisation des récepteurs »\nAffirmer avec certitude que les récepteurs de la sérotonine, de la noradrénaline et de la dopamine sont tous « resensibilisés à trois mois » va au-delà de ce que les données permettent d\'établir. Ce qui est fiable : le sevrage est généralement résolu à ce stade et, chez la plupart des personnes, l\'humeur, l\'énergie et l\'amplitude émotionnelle se stabilisent avec une signalisation cérébrale naturelle et autorégulée.\n\nSevrage ou rechute\nLa lettre insiste sur la distinction entre sevrage et véritable retour de l\'affection sous-jacente. Si des symptômes persistent à trois mois, faites-les réévaluer avec votre prescripteur plutôt que de supposer qu\'ils sont uniquement liés au sevrage.';

  @override
  String get maoiReferenceDay180 =>
      'Six mois après les IMAO : récupération à long terme\n\nSource : Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nBilan à six mois\nCette revue explique que les antidépresseurs agissent en partie en diminuant la sensibilité ou le nombre de récepteurs monoaminergiques au fil du temps, et que cette adaptation met des semaines à des mois à s\'inverser après l\'arrêt — un processus plus lent que la resynthèse des enzymes MAO en environ deux semaines.\n\nOù se situent six mois\nSix mois se situent largement au-delà de cette fenêtre de réadaptation des récepteurs pour la grande majorité des personnes, tandis que l\'activité enzymatique s\'est complètement normalisée dès le premier mois. Les délais précis de resensibilisation complète des récepteurs à la sérotonine, à la noradrénaline et à la dopamine ne sont pas établis jour par jour dans la littérature ; ce qui est fiable, c\'est qu\'à six mois la plupart des personnes fonctionnent avec une signalisation cérébrale naturelle et autorégulée.\n\nRemarque sur la phénéthylamine\nLes IMAO inhibent aussi la dégradation de la phénéthylamine (PEA), une amine trace liée à l\'humeur et à l\'énergie. Son métabolisme devrait se normaliser avec la récupération générale des enzymes MAO, même si — comme pour la resensibilisation des récepteurs — la recherche n\'établit pas de calendrier précis spécifique à la PEA.';

  @override
  String get maoiReferenceDay365 =>
      'Un an après les IMAO : récupération accomplie\n\nSource : « Monoamine Oxidase Inhibitors (MAOIs) » (StatPearls, NCBI Bookshelf)\n\nUn an : une réussite remarquable\nAtteindre un an après l\'arrêt d\'un IMAO est une étape réellement importante. Les IMAO comptent parmi les antidépresseurs les plus exigeants à arrêter, avec un mécanisme irréversible, un régime strict pauvre en tyramine et des précautions d\'interactions médicamenteuses uniques parmi les antidépresseurs.\n\nCe que représente cette année\n• Une année complète d\'activité naturelle et autorégulée de la monoamine oxydase, après une resynthèse enzymatique achevée durant le premier mois\n• La capacité démontrée de maintenir le bien-être sans inhibition des MAO provoquée par le médicament\n• Un recul suffisant pour être certain que les risques aigus du troisième jour sont fermement derrière vous\n\nUne remarque sur les IMAO\nLes IMAO restent particulièrement efficaces pour certaines formes de dépression résistante ou atypique. Un arrêt réussi ne diminue pas leur valeur thérapeutique — il démontre la capacité du cerveau à récupérer et celle du patient à traverser un processus médical exceptionnellement exigeant. Une précaution durable : continuez d\'informer tout nouveau prescripteur ou anesthésiste de votre ancien usage d\'IMAO, car certaines interactions méritent d\'être signalées à long terme.';

  @override
  String get marijuanaReferenceDay1 =>
      'Sevrage du cannabis : premier jour\n\nSource : « The cannabis withdrawal syndrome: current insights », Substance Abuse and Rehabilitation (2017), PubMed Central\n\nLe sevrage du cannabis est réel\nCette revue évaluée par les pairs établit que le syndrome de sevrage du cannabis est un trouble clinique bien validé, survenant chez environ 90 % des personnes diagnostiquées dépendantes au cannabis lorsqu\'elles arrêtent. Sa sévérité moyenne au pic est comparable à celle du sevrage tabagique.\n\nPourquoi le sevrage survient\nLe THC agit sur le système endocannabinoïde — les récepteurs CB1 impliqués dans l\'humeur, l\'appétit, le sommeil, la mémoire et le stress. Avec un usage chronique, le cerveau réduit l\'activité de ce système ; à l\'arrêt, il devient temporairement sous-actif. La revue indique que les récepteurs CB1 retrouvent un fonctionnement normal en environ quatre semaines d\'abstinence.\n\nDébut au premier jour\nLa revue indique que les symptômes physiques apparaissent généralement en premier — dans les 1 à 3 jours suivant la dernière consommation — tandis que les symptômes psychologiques apparaissent sur 2 à 10 jours. Les symptômes précoces comprennent :\n• Irritabilité, anxiété et agitation\n• Difficultés à dormir\n• Diminution de l\'appétit\n• Tension physique, sueurs ou frissons\n• Humeur dépressive\n\nSévérité\nLe syndrome n\'est pas médicalement dangereux et les symptômes sont généralement légers à modérés, mais ils peuvent être suffisamment pénibles pour favoriser une rechute — d\'où l\'intérêt de connaître la chronologie.';

  @override
  String get marijuanaReferenceDay3 =>
      'Chronologie du sevrage du cannabis : les premiers jours\n\nSource : « Time-course of the DSM-5 cannabis withdrawal symptoms in poly-substance abusers », BMC Psychiatry (2013), PubMed Central\n\nUne chronologie mesurée\nCette étude a suivi les symptômes DSM-5 de sevrage du cannabis chez 90 patients pendant quatre semaines, fournissant l\'une des images les plus claires de leur évolution. La sévérité globale suivait une courbe : augmentation, puis diminution au fil des semaines.\n\nCe qui culmine tôt\nPlusieurs symptômes physiques perturbateurs culminent au cours des premiers jours :\n• Insomnie — pic autour du jour 1\n• Nervosité — autour du jour 4\n• Humeur dépressive et symptômes physiques — autour du jour 5\n• Agitation — autour du jour 6\n\nCe qui culmine plus tard\nCertains symptômes apparaissent et culminent après la première semaine :\n• Rêves vifs et désagréables — autour du jour 11\n• Irritabilité et colère — autour du jour 14\n\nSommeil et cannabis\nLes rêves vifs retardés reflètent un rebond de sommeil paradoxal : le cannabis le réduit pendant l\'usage et le cerveau compense après l\'arrêt. Les auteurs estiment ce symptôme suffisamment fréquent pour faire partie des critères officiels de sevrage.\n\nCe qu\'il faut retenir au troisième jour\nVous êtes au cœur du pic physique précoce — insomnie, nervosité et agitation sont proches de leur maximum. La courbe régulière et prévisible est rassurante : ces symptômes ont une évolution connue et diminuent ensuite.';

  @override
  String get marijuanaReferenceDay7 =>
      'Une semaine sans cannabis : le pire est passé\n\nSource : « The cannabis withdrawal syndrome: current insights », Substance Abuse and Rehabilitation (2017), PubMed Central\n\nOù se situe une semaine\nCette revue indique que le syndrome de sevrage dure généralement jusqu\'à environ trois semaines, la période la plus pénible se situant entre la première et la troisième semaine. À une semaine, les symptômes physiques les plus précoces — insomnie, perte d\'appétit, agitation — ont généralement dépassé leur pic et commencent à diminuer.\n\nCe qui continue à se stabiliser\nLa revue distingue les symptômes physiques à pic précoce des symptômes psychologiques plus tardifs. À une semaine :\n• L\'inconfort physique et l\'appétit s\'améliorent largement\n• Le sommeil reste perturbé chez beaucoup de personnes, avec des rêves vifs liés au rebond de sommeil paradoxal qui culminent souvent autour de cette période\n• L\'irritabilité et l\'humeur peuvent rester élevées, car elles culminent plus tard pendant les deux premières semaines\n\nNeurobiologie de la récupération\nSous ces changements, la revue indique que les récepteurs CB1 réduits reviennent vers un fonctionnement normal en environ quatre semaines d\'abstinence. Après une semaine, cette régulation est déjà bien engagée — le système récupère même si certains symptômes persistent.\n\nÀ retenir\nAtteindre une semaine signifie que le pic physique aigu est derrière vous. Les symptômes restants du sommeil et de l\'humeur appartiennent à un syndrome dont la durée est connue et limitée, qui continue de se résoudre au cours des semaines suivantes.';

  @override
  String get marijuanaReferenceDay14 =>
      'Deux semaines sans cannabis : fin du sevrage aigu\n\nSource : Budney, AJ et al. (2003) — étude évaluée par les pairs sur la chronologie du sevrage du cannabis\n\nRésultats de la recherche\nCette étude a documenté systématiquement l\'évolution des symptômes de sevrage chez des consommateurs réguliers. Elle a montré que le syndrome aigu culmine pendant la première semaine et, pour la plupart des symptômes, se résout largement dans les deux semaines suivant l\'arrêt.\n\nCe qui se résout en deux semaines\nÀ 14 jours, les participants avaient largement vu disparaître :\n• L\'inconfort physique et les symptômes corporels\n• Les perturbations de l\'appétit\n• La majeure partie des troubles du sommeil\n• Le pic d\'irritabilité et d\'anxiété\n\nCe qui peut persister\nLa recherche a aussi identifié des symptômes persistant au-delà de deux semaines chez certains utilisateurs :\n• Humeur dépressive\n• Difficultés de concentration\n• Qualité du sommeil, bien qu\'en amélioration\n\nPourquoi le cap des deux semaines compte\nPasser deux semaines est important car le syndrome aigu est en grande partie terminé. Les difficultés restantes concernent surtout la récupération cérébrale à plus long terme et la gestion des raisons sous-jacentes de l\'usage, plutôt que la réponse physiologique aiguë à l\'arrêt.';

  @override
  String get marijuanaReferenceDay30 =>
      'Un mois sans cannabis : amélioration de la mémoire\n\nSource : Pope et al. (2001), Archives of General Psychiatry\n\nCannabis et mémoire : le problème\nCette étude a suivi de personnes ayant une consommation importante de longue durée pendant 28 jours d\'abstinence confirmée et comparé leurs résultats de pensée et de mémoire avec ceux de consommateurs légers et de non-consommateurs. Au début, puis aux jours 1 et 7, les personnes ayant une consommation importante réussissaient moins bien le rappel de listes de mots — un déficit corrélé aux métabolites urinaires du THC, reflétant l\'exposition récente plutôt que l\'usage sur toute la vie.\n\nLa bonne nouvelle : récupération au jour 28\nAu jour 28, personnes ayant une consommation importante, consommateurs légers et non-consommateurs obtenaient des résultats pratiquement identiques aux tests cognitifs et de mémoire de l\'étude. Il n\'existait plus de relation significative entre consommation cumulée de cannabis et performance.\n\nCe que cela signifie à 30 jours\n• L\'apprentissage verbal et le rappel sont revenus au niveau des témoins\n• Les déficits résiduels observés la première semaine se sont résolus\n• Le déficit antérieur était lié à l\'exposition récente, pas à des dommages permanents\n\nCe que montrent les données\nAu jour 28, les personnes ayant une consommation importante étaient pratiquement indiscernables des consommateurs légers et des non-consommateurs sur l\'ensemble des tests. Les déficits d\'apprentissage verbal et de rappel observés la première semaine avaient récupéré jusqu\'au niveau témoin.';

  @override
  String get marijuanaReferenceDay60 =>
      'Deux mois sans cannabis : la concentration s\'affine\n\nSource : Roten et al. (2015), Addictive Behaviors\n\nLa question de recherche\nCette étude sur l\'arrêt du cannabis chez les jeunes a suivi les résultats de tests de mémoire et de cognition parallèlement à des tests urinaires pendant environ deux mois, en comparant les consommateurs persistants à ceux qui venaient d\'arrêter ou restaient abstinents.\n\nRésultats clés\nUne abstinence régulière était associée à une amélioration significative de :\n• La mémoire globale\n• La mémoire verbale en particulier — le domaine le plus touché\n• Les performances de mouvement et de vitesse de réaction\n\nÀ deux mois\nAprès environ huit semaines d\'abstinence régulière, les scores de mémoire, de mouvement et de vitesse de réaction avaient progressé de façon mesurable par rapport à l\'usage actif, suivant étroitement l\'absence de consommation confirmée plutôt que le temps seul.\n\nCe que montre l\'étude\nChez des adolescents et jeunes adultes dépendants au cannabis, une abstinence régulière a produit des gains significatifs de mémoire globale, de mémoire verbale et de performances motrices et réactionnelles sur la fenêtre de traitement d\'environ deux mois.';

  @override
  String get marijuanaReferenceDay90 =>
      'Trois mois sans cannabis : retour de la stabilité de l\'humeur\n\nSource : Connor et al. (2022), Addiction — revue clinique du sevrage du cannabis\n\nLa véritable chronologie du sevrage\nCette revue décrit des symptômes commençant généralement 24 à 48 heures après l\'arrêt et culminant vers les jours 2 à 6. Colère, agressivité et humeur dépressive peuvent apparaître dès une semaine mais culminent habituellement après environ deux semaines ; les troubles du sommeil peuvent persister plus longtemps que les autres symptômes.\n\nOù se situent trois mois\nÀ trois mois, vous êtes très au-delà de la chronologie documentée : les symptômes commencent sous 24 à 48 heures, culminent vers les jours 2 à 6, et même les symptômes plus lents de l\'humeur et du sommeil culminent dans les semaines suivantes. Quatre-vingt-dix jours donnent à ces effets de sevrage plusieurs mois pour se stabiliser.\n\nRemarque sur le système endocannabinoïde\nLa recherche montre également que les récepteurs CB1 réduits retrouvent un fonctionnement proche de la normale en environ quatre semaines d\'abstinence. À 90 jours, vous êtes bien au-delà de cette fenêtre de récupération.\n\nLa suite\nLa revue aborde aussi le pronostic après désintoxication et la prévention de la rechute, soulignant que soutien et stratégies d\'adaptation restent importants bien au-delà de la période aiguë.';

  @override
  String get marijuanaReferenceDay180 =>
      'Six mois sans cannabis : récupération de la planification et de la prise de décision\n\nSource : Crean, Crane & Mason (2011), Journal of Addiction Medicine\n\nPlanification et prise de décision après le cannabis\nCette revue a étudié attention, prise de décision, contrôle de soi, mémoire de travail et fluidité verbale depuis les premières heures suivant l\'usage jusqu\'à l\'abstinence à long terme. À six mois, vous êtes très au-delà des effets à court terme et profondément engagé dans la récupération.\n\nCe que la recherche a trouvé\nPlusieurs difficultés liées à un usage important diminuent avec une abstinence durable, certaines études observant une récupération dès 28 jours. Les domaines les plus lents à récupérer après un usage important commencé tôt comprennent :\n• Prise de décision et prise de risque — domaines où des déficits peuvent persister plus longtemps chez les personnes ayant une consommation importante chroniques\n• Raisonnement abstrait et compétences verbales — particulièrement altérés chez les adultes ayant commencé avant 17 ans\n\nRécupération après un début précoce\nSix mois sont très au-delà des effets à court terme décrits dans cette revue. Planification, prise de décision et raisonnement continuent de s\'améliorer avec l\'abstinence, qui reste la voie la plus solide vers davantage de récupération.\n\nVue d\'ensemble\nPour un usage plus léger commencé à l\'âge adulte, les perspectives sont plus favorables — beaucoup rapportent à six mois une pensée plus claire, des décisions plus stables et un plus grand sentiment d\'autonomie. Les plus grands gains viennent de la poursuite de l\'abstinence, surtout après un usage important ou commencé tôt.';

  @override
  String get marijuanaReferenceDay365 =>
      'Un an sans cannabis : récupération de la structure cérébrale\n\nSource : « Hippocampal harms, protection and recovery following regular cannabis use », Translational Psychiatry (2016), PubMed Central\n\nModifications structurelles liées au cannabis\nCette étude d\'imagerie a examiné l\'hippocampe, une région centrale pour la mémoire, chez des consommateurs actuels, anciens et des non-consommateurs. Les utilisateurs actuels non exposés au CBD avaient un hippocampe environ 11 % plus petit et un marqueur de santé cellulaire environ 15 % plus faible que les témoins.\n\nRésultat clé : récupération avec l\'abstinence\nLes analyses de courbe soutenaient un modèle de « protection et récupération ». Surtout, les anciens utilisateurs — abstinents depuis environ 29 mois en moyenne — ne différaient des témoins sur aucune mesure d\'intégrité. Les auteurs concluent que les atteintes des régions de mémoire liées au THC « peuvent récupérer avec des périodes prolongées d\'abstinence ».\n\nRécupération cérébrale sur un an et au-delà\nÀ un an sans cannabis, le système de mémoire du cerveau est bien engagé dans la récupération : la taille de l\'hippocampe et les marqueurs de santé cellulaire évoluent vers la normale, soutenant la mémoire et le contrôle émotionnel.\n\nSignal de récupération\nLes anciens utilisateurs abstinents depuis environ 29 mois correspondaient aux non-consommateurs sur les mesures de santé de l\'hippocampe. À un an, le système de mémoire progresse déjà sur cette trajectoire documentée vers la normale.';

  @override
  String get mdmaReferenceDay1 =>
      'Après la MDMA : la descente\n\nSource : Meyer (2013), « 3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives », Substance Abuse and Rehabilitation\n\nPourquoi le moral baisse\nLa MDMA agit en provoquant une forte libération de sérotonine, avec un peu de dopamine. Ensuite, le cerveau présente temporairement moins de sérotonine disponible. Cette revue décrit une baisse de l\'humeur — le « blues du milieu de semaine » — mesurée chez des utilisateurs novices comme expérimentés 2 à 5 jours après la prise.\n\nCe qui aide\n• Hydratation et alimentation nutritive\n• Sommeil\n• Patience — cette baisse est liée à l\'épuisement temporaire, pas à un état permanent\n\nLa descente après une prise unique diffère du sevrage lié à une dépendance, que la même revue décrit comme comportant des envies mais pas de symptômes physiques significatifs.';

  @override
  String get mdmaReferenceDay3 =>
      'Quelques jours après la MDMA\n\nSource : Meyer (2013), « 3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives », Substance Abuse and Rehabilitation\n\nLe blues du milieu de semaine\nC\'est approximativement la période décrite par cette revue lorsqu\'elle évoque le « blues du milieu de semaine » — une baisse de l\'humeur mesurée 2 à 5 jours après la prise chez des utilisateurs novices et expérimentés, liée à un épuisement à court terme de la sérotonine plutôt qu\'à un changement durable.\n\nCe qui s\'améliore\n• L\'humeur remonte généralement à partir de son point le plus bas autour de maintenant\n• L\'énergie revient\n• Le sommeil commence à se normaliser';

  @override
  String get mdmaReferenceDay7 =>
      'Une semaine après la MDMA\n\nSource : Meyer (2013), « 3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives », Substance Abuse and Rehabilitation\n\nAprès le blues du milieu de semaine\nPour la plupart des personnes, une semaine dépasse la fenêtre de 2 à 5 jours que cette revue associe à la descente aiguë ; l\'humeur devrait donc être revenue à la normale. La revue note que chez les personnes qui consomment beaucoup ou de façon répétée, les envies peuvent persister dans le cadre d\'une dépendance, sans qu\'elle décrive de symptômes physiques importants de sevrage.\n\nQuand demander de l\'aide\nSi la baisse de moral, l\'anxiété ou les troubles du sommeil persistent après une semaine, il peut s\'agir de davantage qu\'une simple descente — il est utile d\'en parler à un professionnel.';

  @override
  String get mdmaReferenceDay14 =>
      'Deux semaines sans MDMA\n\nSource : Meyer (2013), « 3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives », Substance Abuse and Rehabilitation\n\nChronologie de récupération\nPour une descente après une prise unique, deux semaines sont bien au-delà de la baisse de 2 à 5 jours documentée par cette revue ; l\'humeur, le sommeil et la concentration devraient donc être stables. Après un usage plus important ou répété, la récupération se poursuit au-delà de la descente, et les études d\'imagerie chez des personnes abstinentes montrent que la capacité de recyclage de la sérotonine augmente avec une abstinence prolongée.\n\nCe que cela signifie pour vous\nSi votre usage était occasionnel, vous avez probablement traversé le pire. S\'il était fréquent ou important, soyez patient avec vous-même — la récupération complète de la signalisation sérotoninergique est un processus plus long que deux semaines, abordé dans les étapes suivantes.';

  @override
  String get mdmaReferenceDay30 =>
      'Un mois sans MDMA\n\nSource : « Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users », PubMed\n\nOù se situe un mois\nLa descente aiguë et le sevrage sont loin derrière vous, et l\'humeur, la pensée et la mémoire sont plus stables. Les recherches d\'imagerie montrent que la MDMA réduit la capacité du cerveau à traiter et recycler la sérotonine, et que cette capacité récupère avec une abstinence durable.\n\nSignal de récupération\nCes mêmes recherches montrent une récupération de la capacité de recyclage de la sérotonine avec l\'abstinence. L\'humeur et la fonction sérotoninergique s\'améliorent d\'abord, tandis que la mémoire suit sa propre chronologie de récupération — poursuivre l\'abstinence soutient les deux.';

  @override
  String get mdmaReferenceDay90 =>
      'Trois mois sans MDMA\n\nSource : « Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users », PubMed\n\nRécupération continue\nAvec une abstinence durable, le système sérotoninergique du cerveau continue de récupérer, notamment dans les régions cérébrales profondes. L\'humeur et le sommeil sont généralement stables à ce stade.\n\nSignal de récupération\nL\'abstinence prolongée entraîne une récupération continue des transporteurs de sérotonine dans plusieurs régions du cerveau, tandis que l\'humeur et le sommeil restent stables et que la récupération de la pensée et de la mémoire se poursuit.';

  @override
  String get mdmaReferenceDay365 =>
      'Un an sans MDMA\n\nSource : « Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users », PubMed\n\nUn an plus tard\nAprès une année d\'abstinence, le traitement de la sérotonine par le cerveau a largement récupéré et l\'humeur est stable.\n\nSignal de récupération\nUne année entière d\'abstinence offre au système sérotoninergique une longue fenêtre de récupération. Les recherches d\'imagerie montrent que la capacité de recyclage de la sérotonine augmente avec l\'abstinence, ce qui fait de la récupération importante de ce système le signal biologique le plus clair à ce stade.';

  @override
  String get methReferenceDay1 =>
      'Sevrage de la méthamphétamine : les premières 24 heures\n\nSource : McGregor et al., « The nature, time course and severity of methamphetamine withdrawal », Addiction (2005), PubMed\n\nLe crash\nLa méthamphétamine provoque une forte libération de dopamine ; à l\'arrêt, le système se retrouve temporairement épuisé. Cette étude a suivi les symptômes chaque jour pendant les trois premières semaines d\'abstinence et constaté que leur sévérité globale était maximale dans les 24 heures suivant la dernière prise — le « crash », un passage brutal d\'une stimulation extrême à un épuisement physique et psychologique.\n\nSymptômes du premier jour\nL\'étude a documenté les manifestations les plus intenses à ce moment :\n• Fatigue extrême et sommeil accru\n• Augmentation de l\'appétit, la méthamphétamine le supprimant fortement\n• Humeur dépressive et perte de plaisir\n• Fortes envies\n• Anxiété et irritabilité\n\nSécurité physique\nLe syndrome de sevrage lui-même n\'est généralement pas dangereux sur le plan vital, mais les symptômes dépressifs peuvent être sévères au début et inclure des pensées suicidaires. Une supervision médicale est fortement recommandée, surtout chez les personnes ayant une consommation importante.\n\nLa situation commence à s\'améliorer\nRésultat encourageant : la sévérité est maximale au tout début puis diminue. À partir de ce pic des 24 heures, les symptômes reculent régulièrement au cours des jours suivants — le pire point se situe au commencement.';

  @override
  String get methReferenceDay3 =>
      'Sevrage de la méthamphétamine : jour trois — toujours dans la phase aiguë\n\nSource : McGregor et al., « The nature, time course and severity of methamphetamine withdrawal », Addiction (2005), PubMed\n\nAprès le pic\nCette étude a constaté que la sévérité globale culmine dans les premières 24 heures puis diminue de façon à peu près linéaire pendant la phase aiguë, qui dure environ 7 à 10 jours. Au troisième jour, vous avez dépassé le point maximal mais restez pleinement dans la phase aiguë — les symptômes restent marqués même si la tendance est à la baisse.\n\nSymptômes du troisième jour\nLes manifestations suivies dans l\'étude encore importantes à ce stade comprennent :\n• Dépression et perte de plaisir\n• Fortes envies\n• Difficultés de concentration et de clarté mentale\n• Sommeil perturbé — alternance d\'insomnie et d\'hypersomnie\n• Fatigue persistante\n\nPourquoi cela arrive\nL\'intensité du sevrage reflète l\'ampleur de l\'épuisement dopaminergique. Les symptômes dépressifs mesurés sont les plus visibles pendant ces premiers jours — mais l\'étude a surtout constaté que la sévérité globale « diminuait jusqu\'à des niveaux proches des témoins à la fin de la première semaine d\'abstinence ».\n\nCela passera\nLa période la plus difficile correspond aux premiers jours et les données montrent ensuite une baisse régulière. Comprendre que cet état est temporaire et lié au fonctionnement du cerveau et des nerfs — pas une condition permanente — aide à le traverser.';

  @override
  String get methReferenceDay7 =>
      'Une semaine sans méthamphétamine : fin de la phase aiguë\n\nSource : McGregor et al., « The nature, time course and severity of methamphetamine withdrawal », Addiction (2005), PubMed\n\nFin de la phase aiguë\nVoici l\'un des résultats les plus encourageants de la recherche. L\'étude rapporte que la sévérité globale du sevrage — y compris les symptômes dépressifs suivis — « diminuait jusqu\'à des niveaux proches des témoins à la fin de la première semaine d\'abstinence », ce qui marque la fin de la phase aiguë. La partie la plus raide du parcours est derrière vous.\n\nDeux phases de sevrage\nLes auteurs décrivent :\n• Une phase aiguë d\'environ 7 à 10 jours, pendant laquelle la sévérité diminue régulièrement après son pic initial\n• Une phase subaiguë durant au moins deux semaines supplémentaires, avec des symptômes plus légers mais persistants\n\nCe qui reste au jour 7\nÀ l\'entrée dans la phase subaiguë, les principaux défis sont davantage psychologiques que liés au crash aigu :\n• Humeur basse, bien que nettement meilleure que les premiers jours\n• Envies, surtout face à des déclencheurs\n• Concentration et mémoire encore en récupération\n• Sommeil encore en cours de stabilisation\n\nRécupération physique en cours\nLa phase aiguë terminée, l\'appétit est revenu et l\'énergie augmente progressivement à mesure que le corps récupère des effets de la méthamphétamine sur le sommeil, l\'alimentation et le système cardiovasculaire.';

  @override
  String get methReferenceDay30 =>
      'Un mois sans méthamphétamine : l\'humeur se stabilise, les envies persistent\n\nSource : Zorick et al., « Withdrawal symptoms in abstinent methamphetamine-dependent subjects », Addiction (2010), PubMed Central\n\nSuivre les cinq premières semaines\nCette étude a suivi des participants dépendants à la méthamphétamine restés abstinents jusqu\'à cinq semaines, en les comparant à des témoins sains — donnant une image particulièrement claire de la situation à un mois.\n\nCe qui s\'est amélioré à un mois\n• Les symptômes dépressifs ont « diminué de façon importante au cours des deux premières semaines jusqu\'à des niveaux bas et stables » et, à la fin de quatre semaines, se rapprochaient des niveaux témoins\n• Les symptômes psychiatriques et de type psychotique avaient atteint un faible niveau dès la fin de la deuxième semaine\nÀ 30 jours, la forte dépression du début s\'est donc largement levée — une amélioration réelle et mesurée.\n\nCe qui persiste\nL\'étude est claire sur un symptôme qui dure plus longtemps : les envies « se poursuivaient encore à un niveau réduit pendant les cinq semaines d\'abstinence ». Elles sont plus faibles qu\'au cours de la première semaine mais n\'ont pas disparu, ce qui explique pourquoi un mois reste une période à risque et pourquoi le soutien compte.\n\nÀ retenir\nAprès un mois, les mécanismes cérébraux de l\'humeur ont suffisamment récupéré pour que le ressenti quotidien soit bien meilleur qu\'au début — tandis que des envies persistantes sont normales à ce stade et ne constituent pas un échec.';

  @override
  String get methReferenceDay90 =>
      'Trois mois sans méthamphétamine : la guérison a commencé — soyez patient\n\nSource : Volkow et al., « Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence », Journal of Neuroscience (2001)\n\nÀ propos de cette recherche\nCette étude d\'imagerie historique a suivi des utilisateurs de méthamphétamine à deux moments — vers trois mois d\'abstinence puis vers 14 mois — pour observer la récupération du système dopaminergique.\n\nOù se situent trois mois\nÀ trois mois, le sevrage précoce est terminé depuis longtemps et une récupération dopaminergique plus profonde est en cours. La même étude a ensuite constaté que les protéines qui recyclent la dopamine dans les régions de récompense et de mouvement augmentaient d\'environ 16 à 19 % après 12 à 17 mois sans méthamphétamine.\n\nCe que cela signifie\nÀ 90 jours, le sevrage aigu est loin derrière, l\'humeur et le sommeil se sont améliorés et la participation à une thérapie devient plus productive. Mais la récupération profonde de la dopamine est un projet plus long qui se poursuit pendant l\'année suivante. Si motivation et plaisir semblent encore atténués à trois mois, cela est compatible avec les données — la trajectoire de cette étude est clairement ascendante à partir de là.\n\nPourquoi l\'attente en vaut la peine\nLa même étude montre que l\'abstinence est ce qui entraîne la récupération : plus elle est longue, plus la récupération des transporteurs de dopamine est importante. Trois mois sont les fondations ; les gains continuent.';

  @override
  String get methReferenceDay180 =>
      'Six mois sans méthamphétamine : le cœur peut récupérer\n\nSource : « Stopping Drug Abuse Can Reverse Related Heart Damage », American College of Cardiology (2017), rapportant une étude de JACC: Heart Failure\n\nMéthamphétamine et cœur\nLa méthamphétamine est l\'une des drogues récréatives les plus cardiotoxiques. Elle peut provoquer une hypertension sévère, des arythmies et, avec le temps, une cardiomyopathie associée à la méthamphétamine — un affaiblissement du muscle cardiaque pouvant entraîner une insuffisance cardiaque.\n\nCe que l\'étude a trouvé\nL\'ACC a rapporté les résultats de patients atteints de cardiomyopathie liée à la méthamphétamine, tous avec une fonction de pompage du cœur nettement réduite. Résultat central et encourageant : l\'arrêt « peut inverser les dommages causés au cœur et améliorer la fonction cardiaque ». Les patients ayant arrêté avaient de bien meilleurs résultats que ceux continuant à consommer, et les auteurs ont souligné qu\'une détection précoce « pourrait prévenir une nouvelle détérioration de la cardiomyopathie ».\n\nPourquoi six mois comptent\nChaque mois d\'abstinence supprime le stress toxique continu sur le cœur et lui donne une chance de récupérer. À six mois, vous avez offert au système cardiovasculaire une pause importante et prolongée — précisément la condition dans laquelle cette étude observait une amélioration.\n\nSignal de récupération\nLe résultat soutenu par les données est fort : arrêter la méthamphétamine peut inverser des lésions cardiaques associées et améliorer la fonction du cœur. Six mois sans agressions stimulantes répétées offrent une fenêtre importante de récupération.';

  @override
  String get methReferenceDay365 =>
      'Un an sans méthamphétamine : récupération cérébrale mesurable\n\nSource : Wang et al., « Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence », American Journal of Psychiatry (2004), PubMed\n\nCe que montre l\'imagerie\nCette étude a examiné des utilisateurs tôt dans l\'abstinence puis à nouveau après 12 à 17 mois. Elle a constaté une véritable récupération cérébrale, certaines zones récupérant plus vite que d\'autres.\n\nLa bonne nouvelle : récupération profonde et cognitive\nLe thalamus, relais profond du cerveau, recommençait à utiliser l\'énergie plus normalement avec une abstinence prolongée. Cette récupération était associée à de meilleures performances motrices et de mémoire verbale : l\'amélioration visible en imagerie se traduisait donc par de vrais gains cognitifs.\n\nLes circuits de récompense récupèrent plus lentement\nÀ 12 à 17 mois, le relais cérébral profond avait fortement récupéré et ce gain suivait l\'amélioration des mouvements et de la mémoire verbale. Les systèmes de récompense et de motivation continuaient également de se renforcer, donnant à un an une image de récupération majeure de la pensée et de la mémoire.\n\nCe que cela signifie à un an\nÀ un an, attendez-vous à un cerveau qui pense et mémorise bien mieux qu\'au début du rétablissement — une guérison claire et mesurable. Si la motivation ou la capacité à ressentir du plaisir restent parfois en retard, cela correspond aux données et n\'est pas un échec personnel : ces circuits peuvent récupérer plus lentement et certains déficits persister plus d\'un an.';

  @override
  String get methReferenceDay420 =>
      '14 mois sans méthamphétamine : rebond du marqueur dopaminergique\n\nSource : Volkow et al., « Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence », Journal of Neuroscience (2001)\n\nLe résultat principal\nCette étude d\'imagerie a examiné des utilisateurs tôt dans l\'abstinence puis après environ 12 à 17 mois. Les protéines qui recyclent la dopamine ont augmenté d\'environ 16 à 19 % dans les régions de récompense et de mouvement et ont atteint des niveaux qui ne différaient plus significativement de ceux des témoins sains. Une abstinence plus longue correspondait à une meilleure récupération.\n\nPourquoi les transporteurs comptent\nCes protéines recyclent la dopamine après sa libération. La méthamphétamine les réduit, ce qui dérègle le système dopaminergique. Leur rebond vers 14 mois est un signe réel et mesurable de guérison.\n\nSignal de récupération\nAprès 12 à 17 mois, les protéines de recyclage de la dopamine dans les régions de récompense et de mouvement avaient augmenté de 16 à 19 % et atteint les niveaux des témoins. Le système dopaminergique a mesurablement rebondi vers la normale, tandis que pensée, mémoire et mouvement continuent de s\'améliorer.\n\nCe que cela signifie à 14 mois\nLe « matériel » du système dopaminergique récupère de façon mesurable — une vraie raison d\'être optimiste. La récupération fonctionnelle complète, notamment mémoire, motivation et motricité fine, peut toutefois être plus lente et continue avec l\'abstinence.';

  @override
  String get methReferenceDay730 =>
      'Deux ans sans méthamphétamine : pensée et humeur continuent de s\'améliorer\n\nSource : Iudicello et al., « Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence », Journal of Clinical and Experimental Neuropsychology (2010), PubMed Central\n\nUne récupération qui se poursuit au-delà d\'un an\nCette étude a suivi des utilisateurs pendant environ 13 mois et comparé des abstinents stables, des consommateurs persistants et des témoins sains. L\'abstinence stable améliorait la cognition globale et réduisait la détresse émotionnelle, avec des progrès qui se poursuivaient au-delà d\'un an.\n\nCe qui s\'améliore\n• Les performances cognitives globales des abstinents ont rejoint celles des témoins sains, tandis que les consommateurs persistants restaient significativement altérés\n• Les plus grands gains concernaient la vitesse de traitement et les capacités motrices, surtout chez les personnes les plus touchées au départ\n• L\'humeur s\'améliorait nettement : seuls les abstinents montraient une amélioration significative de la dépression et de l\'humeur globale\n\nSignal de récupération\nLes abstinents stables ont rejoint les témoins sains sur la cognition globale et rapportaient moins de détresse émotionnelle. L\'apprentissage verbal, la mémoire de travail, la planification et la concentration peuvent continuer de progresser au-delà de la première année, si bien que la tendance se poursuit pendant la deuxième année.\n\nAprès deux ans\nLe message soutenu par les données est que l\'abstinence durable continue de porter ses fruits bien après la première année — pensée plus vive, meilleure humeur et fonctionnement en amélioration régulière — même si quelques domaines demandent plus de temps.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'Premier jour : le gaz est éliminé, mais surveillez la vitamine B12\n\nSource : Knuf & Maani, « Nitrous Oxide », StatPearls (NCBI Bookshelf)\n\nÀ quelle vitesse le protoxyde d\'azote est-il éliminé ?\nLe protoxyde d\'azote agit rapidement — en deux à cinq minutes — et disparaît tout aussi vite de l\'organisme lorsque l\'inhalation cesse. À ce stade, le gaz lui-même n\'est plus présent dans votre organisme.\n\nLe vrai risque n\'est pas le gaz\nAprès l\'arrêt, l\'important est ce que des expositions répétées ont peut-être déjà provoqué. Le protoxyde d\'azote inactive la méthionine synthase, une enzyme dépendante de la vitamine B12. StatPearls indique que des expositions répétées — professionnelles ou récréatives — peuvent entraîner une anémie mégaloblastique ainsi que des troubles du cerveau et des nerfs et, dans de rares cas, une dégénérescence de la moelle épinière.\n\nSi votre usage était important ou fréquent\nLe protoxyde d\'azote n\'est pas décrit comme provoquant un syndrome de sevrage physique comparable à celui des opioïdes ou de l\'alcool. Le premier jour n\'est donc pas une période où le corps exige le produit : il s\'agit plutôt de commencer à surveiller d\'éventuels symptômes liés à la vitamine B12 — abordés dans les prochains jalons — et de consulter s\'ils apparaissent.';

  @override
  String get nitrousOxideReferenceDay3 =>
      'Après 72 heures : pas de sevrage physique, mais surveillez les symptômes neurologiques\n\nSource : Knuf & Maani, StatPearls ; Tikaria et al. (2026), Cureus\n\nContrairement aux opioïdes ou à l\'alcool, le protoxyde d\'azote n\'est pas décrit comme provoquant un syndrome de sevrage physique. À ce stade, les envies relèvent de l\'habitude et du désir de consommer, et non d\'un besoin du corps pour fonctionner.\n\nÀ surveiller\nUne revue systématique de 1 809 cas d\'usage récréatif de protoxyde d\'azote (Tikaria et al., 2026) a constaté que les symptômes touchant le cerveau et les nerfs — en particulier les picotements ou l\'engourdissement, appelés paresthésies — constituaient le signe le plus fréquent de dommages liés à la vitamine B12, parfois même lorsque les analyses sanguines standards semblaient normales. Des troubles de la marche et une faiblesse ont également été rapportés.\n\nSi vous remarquez l\'un de ces symptômes\nDemandez un avis médical. La même revue a constaté que les analyses courantes — hémoglobine et vitamine B12 sérique — ne détectaient pas une part importante des personnes atteintes. Les dosages de l\'acide méthylmalonique (MMA) et de l\'homocystéine sont plus sensibles et peuvent être demandés spécifiquement si vous signalez un usage de protoxyde d\'azote.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'Une semaine : faites-vous tester si votre usage était important\n\nSource : Tikaria et al. (2026), « The Toxic Legacy of Recreational Nitrous Oxide Use », Cureus\n\nCe que montrent les données\nCette revue systématique a constaté que la carence en vitamine B12 liée au protoxyde d\'azote est souvent « fonctionnelle » : le taux sanguin de B12 paraissait normal chez environ la moitié des patients atteints, même lorsque de véritables lésions du cerveau et des nerfs étaient présentes. L\'homocystéine et l\'acide méthylmalonique (MMA) étaient anormaux beaucoup plus souvent — respectivement chez 84 % et 73 % des patients testés — et constituent des marqueurs plus fiables.\n\nQue faire ?\nSi votre usage était important ou fréquent, une semaine après l\'arrêt est un moment raisonnable pour consulter un médecin et demander spécifiquement un dosage de l\'homocystéine et du MMA, et pas seulement un taux standard de vitamine B12. C\'est particulièrement important en cas de picotements, d\'engourdissement, de troubles de l\'équilibre ou de faiblesse inexpliquée.\n\nLa récupération neurologique est fréquente après l\'arrêt du protoxyde d\'azote et le traitement par vitamine B12 : de grandes séries cliniques rapportent une amélioration partielle ou complète chez la plupart des patients suivis, avec une récupération qui se poursuit pendant les premiers mois après le traitement.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'Deux semaines : les symptômes touchant le cerveau et les nerfs méritent un suivi\n\nSource : Tikaria et al. (2026), Cureus ; Knuf & Maani, StatPearls\n\nCe qui a été rapporté\nLes rapports et séries de cas analysés par Tikaria et al. décrivent des atteintes nerveuses liées au protoxyde d\'azote se manifestant par une perte de sensibilité, une ataxie à la marche et parfois une faiblesse gênant la marche. Ces signes peuvent ressembler à d\'autres maladies neurologiques et être manqués lorsque l\'usage de protoxyde d\'azote n\'est pas signalé au clinicien.\n\nCe que l\'on sait du calendrier de récupération\nAucune des deux sources n\'indique combien de temps la récupération prend habituellement après l\'arrêt et le traitement d\'une éventuelle carence. Les rapports de cas décrivent des résultats très variés — d\'une récupération complète à des séquelles persistantes — qui dépendent largement de l\'importance des dommages avant le diagnostic. Un point reste constant dans la littérature : un traitement plus précoce est associé à de meilleurs résultats.\n\nSi vous n\'avez pas encore été contrôlé\nDeux semaines après l\'arrêt restent un bon moment pour effectuer des analyses, même sans symptômes — en particulier l\'homocystéine et le MMA plutôt que la seule vitamine B12 sérique.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'Un mois : habitude et envie, pas dépendance physique\n\nSource : Knuf & Maani, « Nitrous Oxide », StatPearls (NCBI Bookshelf)\n\nOù vous en êtes\nStatPearls ne décrit pas le protoxyde d\'azote comme provoquant un syndrome de dépendance physique. Après un mois sans usage, les envies qui persistent relèvent donc de l\'habitude, du contexte social ou de l\'ennui plutôt que d\'un corps encore en train de s\'adapter à l\'absence du produit.\n\nLa question de la vitamine B12\nSi une carence en vitamine B12 a été recherchée puis traitée, un mois est un moment raisonnable pour que votre médecin vérifie si vos taux — et vos éventuels symptômes — ont répondu au traitement. Si vous n\'avez pas été testé et que votre usage était important, cela vaut toujours la peine d\'en parler.\n\nCe que vous protégez\nChaque mois sans usage est un mois pendant lequel vous n\'ajoutez pas de nouvelle inactivation de la méthionine synthase ni de risque supplémentaire pour le cerveau et les nerfs.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'Trois mois : le moment de refaire le point si ce n\'est pas déjà fait\n\nSource : Tikaria et al. (2026), « The Toxic Legacy of Recreational Nitrous Oxide Use », Cureus\n\nCe que l\'on sait — et ce que l\'on ne sait pas\nLes données disponibles reposent surtout sur des rapports et séries de cas, et non sur des études contrôlées de récupération. Il n\'existe donc pas de calendrier publié fiable décrivant précisément la résolution des symptômes à trois mois. Les données montrent en revanche que les résultats varient fortement : certaines personnes présentant une carence légère détectée tôt récupèrent complètement, tandis qu\'un diagnostic tardif ou une atteinte nerveuse plus sévère peut laisser des déficits persistants.\n\nCe qui est utile en pratique\nSi vous avez présenté des symptômes neurologiques et n\'avez pas eu d\'analyses de suivi ni d\'avis spécialisé, trois mois sans usage constituent un moment raisonnable pour le faire. Si vous avez été traité et que votre état s\'améliore, c\'est également un bon moment pour confirmer avec votre médecin que cette évolution se poursuit.\n\nLe plus important reste de ne pas reprendre\nLa revue est cohérente sur un point : chaque nouvelle exposition continue d\'inactiver la vitamine B12 et d\'ajouter du risque. Ne pas utiliser de protoxyde d\'azote est le facteur le plus important en votre faveur.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'Un an : la meilleure protection reste l\'abstinence continue\n\nSource : Knuf & Maani, StatPearls ; Tikaria et al. (2026), Cureus\n\nCe que les données permettent réellement de conclure\nAucune des deux sources ne promet un calendrier précis de récupération, et il est important de le dire clairement : la littérature sur le protoxyde d\'azote et la carence en vitamine B12 repose presque entièrement sur des rapports de cas individuels plutôt que sur des études de suivi à long terme. Le mécanisme, lui, est bien établi : le protoxyde d\'azote inactive la vitamine B12 à chaque utilisation, et l\'arrêt supprime entièrement cette atteinte continue.\n\nSi vous avez eu des symptômes liés à une carence\nLes rapports de cas décrivent des résultats très variables, allant d\'une récupération complète à des symptômes nerveux persistants, en grande partie selon l\'importance des dommages et la précocité du traitement. Si des symptômes sont encore présents après un an, c\'est une raison de poursuivre le suivi avec un neurologue, pas la preuve qu\'aucune amélioration n\'est possible : la récupération nerveuse peut se poursuivre sur une longue période.\n\nCe qui est certain\nUn an sans protoxyde d\'azote correspond à un an sans nouvelle inactivation de la méthionine synthase. C\'est le point certain que soutiennent les deux sources.';

  @override
  String get opioidReferenceDay1 =>
      'Sevrage des opioïdes : premier jour\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), sur NCBI Bookshelf\n\n⚠ Note de sécurité\nLe sevrage des opioïdes est rarement mortel chez les personnes par ailleurs en bonne santé, mais il provoque une détresse physique importante et s\'accompagne d\'un risque élevé de reprise. Reprendre après une période d\'abstinence est particulièrement dangereux, car la tolérance diminue rapidement : utiliser la même dose qu\'avant l\'abstinence peut provoquer une surdose mortelle. Une supervision médicale et un traitement par agoniste opioïde sont fortement recommandés.\n\nQuand le sevrage commence\nLe calendrier de l\'OMS varie selon le type d\'opioïde :\n• opioïdes à courte durée d\'action — héroïne, oxycodone : début 8 à 24 heures après la dernière prise, durée 4 à 10 jours\n• opioïdes à longue durée d\'action — méthadone : début 12 à 48 heures après la dernière prise, durée 10 à 20 jours\n\nSymptômes du premier jour\nLes recommandations de l\'OMS citent parmi les premiers signes du sevrage :\n• anxiété et agitation\n• crampes et douleurs musculaires\n• larmoiement et écoulement nasal\n• bâillements et transpiration\n• insomnie, avec bouffées de chaleur et frissons\n• premières nausées\n\nPourquoi c\'est si difficile\nLe système opioïde participe à la régulation de la douleur, du stress, du bien-être émotionnel et du confort de base. L\'usage prolongé d\'opioïdes réduit la production naturelle d\'endorphines par l\'organisme. Lorsque les opioïdes sont retirés, le corps se retrouve temporairement sans son système habituel de confort, avec douleur, anxiété et détresse à un niveau qui reflète l\'ampleur de cette adaptation. Les recommandations de l\'OMS conseillent des soins de soutien, notamment de boire deux à trois litres d\'eau par jour et d\'effectuer une surveillance trois à quatre fois par jour.';

  @override
  String get opioidReferenceDay7 =>
      'Une semaine sans opioïdes : le pic des symptômes diminue\n\nSource : « Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings », Organisation mondiale de la Santé (2009), sur NCBI Bookshelf\n\nLe pic puis le recul\nSelon le calendrier de l\'OMS, le sevrage des opioïdes à courte durée d\'action dure environ quatre à dix jours ; les symptômes augmentent au début puis diminuent au cours de cette période. À la fin de la première semaine :\n• les vomissements et la diarrhée sont en grande partie résolus\n• les crampes musculaires sont moins fortes\n• la détresse physique a nettement diminué\n\nCe qui peut persister au septième jour\nMême si les symptômes physiques aigus s\'améliorent, des difficultés importantes peuvent continuer :\n• insomnie — les troubles du sommeil comptent parmi les symptômes de sevrage des opioïdes les plus persistants\n• baisse de moral et émoussement émotionnel\n• fatigue et faiblesse\n• envies\n• anxiété\n\nSevrage post-aigu\nAprès la première période de sevrage, les troubles du sommeil, les variations d\'humeur et les vagues d\'envie peuvent persister pendant des semaines ou des mois. Le soutien continu est particulièrement important pendant cette phase plus longue du rétablissement.\n\nTraitement par agoniste opioïde\nLes recommandations de l\'OMS décrivent la méthadone et la buprénorphine comme des traitements efficaces qui réduisent la gravité du sevrage et soutiennent le rétablissement. Ces médicaments réduisent aussi la mortalité liée au trouble de l\'usage d\'opioïdes, et de nombreuses personnes en rétablissement durable les utilisent tout au long de la phase initiale.';

  @override
  String get opioidReferenceDay14 =>
      'Deux semaines sans opioïdes : le sommeil commence à s\'améliorer\n\nSource : recherches pharmacologiques évaluées par les pairs sur les opioïdes et le sommeil\n\nLe lien entre opioïdes et sommeil\nCet article examine la relation bidirectionnelle entre l\'usage d\'opioïdes et les troubles du sommeil. Les résultats montrent que les opioïdes perturbent fortement l\'architecture normale du sommeil par plusieurs mécanismes :\n• diminution du sommeil lent profond\n• perturbation du sommeil paradoxal\n• troubles respiratoires du sommeil, notamment l\'apnée centrale\n• dérèglement du rythme circadien\n\nUn cercle vicieux\nLa recherche souligne le caractère bidirectionnel du problème : les opioïdes perturbent le sommeil et, en retour, un mauvais sommeil augmente la sensibilité à la douleur et l\'intensité des envies, ce qui peut favoriser la poursuite de l\'usage. Sortir de la dépendance aux opioïdes, c\'est aussi rompre ce cercle de perturbation du sommeil.\n\nLe sommeil après deux semaines\nAprès quatorze jours sans opioïdes, le sommeil commence à se normaliser :\n• l\'apnée centrale du sommeil, lorsqu\'elle était présente, se résout en quelques jours\n• le sommeil lent profond commence à récupérer\n• le sommeil paradoxal revient vers une proportion normale\n• l\'endormissement devient plus régulier\n\nLe sommeil reste une difficulté importante pour beaucoup de personnes après deux semaines, mais la tendance est clairement à l\'amélioration. Un meilleur sommeil améliore directement l\'humeur, réduit les envies et soutient la clarté mentale nécessaire au rétablissement.';

  @override
  String get opioidReferenceDay30 =>
      'Un mois sans opioïdes : la pensée et la mémoire commencent à récupérer\n\nSource : Mayo Clinic\n\nComprendre le trouble lié à l\'usage d\'opioïdes\nLa Mayo Clinic explique que les opioïdes se fixent à des récepteurs dans le cerveau et dans tout l\'organisme, produisant un soulagement de la douleur, de l\'euphorie et de la somnolence. Avec des prises répétées, le cerveau répond moins fortement et produit moins de ses propres substances de type opioïde. Cela crée une dépendance physique.\n\nPensée et mémoire après un mois\nAprès 30 jours, une récupération significative de la pensée et de la mémoire a déjà eu lieu. Le plus fort du brouillard mental s\'est dissipé et les régions frontales du cerveau — qui participent à la planification et à la maîtrise de soi — récupèrent :\n• la prise de décision s\'améliore\n• la mémoire de travail récupère\n• la vitesse de traitement augmente\n• la concentration devient plus fiable\n\nLe système des endorphines\nAprès un mois, le système naturel des endorphines du cerveau récupère activement : il produit davantage de ses propres substances de type opioïde et y répond de nouveau plus normalement. L\'émoussement émotionnel et la diminution de la tolérance à la douleur continuent de s\'améliorer à mesure que cette récupération progresse.\n\nPrévenir la reprise\nLa Mayo Clinic souligne qu\'un mois d\'abstinence ne signifie pas que le risque de reprise est passé : il reste élevé. La tolérance a nettement diminué, ce qui rend particulièrement dangereuse une reprise aux doses utilisées auparavant en raison du risque de surdose.';

  @override
  String get opioidReferenceDay60 =>
      'Deux mois sans opioïdes : les circuits cérébraux du stress commencent à s\'apaiser\n\nSource : « Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence », Frontiers in Pharmacology (2023)\n\nD\'où viennent les émotions négatives\nCette revue décrit comment l\'usage prolongé d\'opioïdes modifie les circuits cérébraux du stress et de la peur. Pendant le sevrage, ces circuits deviennent hyperactifs tandis que la signalisation dopaminergique diminue dans les circuits de récompense. Cette combinaison aide à expliquer l\'anxiété, la baisse de moral et les envies au début du rétablissement.\n\nPourquoi deux mois peuvent apporter un soulagement\nPoint essentiel, la revue indique que certaines de ces modifications sont réversibles. Dans des modèles animaux, la diminution de la densité des épines dendritiques dans la coque du noyau accumbens est décrite comme une « diminution durable mais réversible », revenant vers les valeurs d\'avant exposition en quelques semaines. À mesure que les circuits du stress et de la récompense se régulent de nouveau, les mécanismes à l\'origine des bouleversements émotionnels du début du rétablissement s\'atténuent, ce qui concorde avec la réactivité plus faible et l\'humeur plus stable que de nombreuses personnes rapportent vers deux mois.\n\nUn signe de récupération\nLes changements réversibles de densité des épines et des circuits du stress documentés dans cette littérature montrent un véritable processus biologique de récupération : pendant l\'abstinence, les circuits qui alimentent l\'état émotionnel négatif de la dépendance se rapprochent progressivement de leur état antérieur à l\'usage.';

  @override
  String get opioidReferenceDay90 =>
      'Trois mois sans opioïdes : le système de récompense commence à récupérer\n\nSource : « Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies », Drug and Alcohol Dependence (2022), sur PubMed Central\n\nDopamine et opioïdes\nLes opioïdes stimulent la libération de dopamine dans le système de récompense du cerveau. Une consommation prolongée laisse ce système appauvri : dans une étude d\'imagerie cérébrale, les protéines qui recyclent la dopamine étaient environ 30 % en dessous des niveaux observés chez des personnes en bonne santé au début du suivi. Cela aide à expliquer la perte de plaisir observée dans le trouble lié à l\'usage d\'opioïdes et au début du rétablissement.\n\nLa récupération est progressive\nCette revue a rassemblé les études longitudinales ayant réexaminé les mêmes personnes pendant leur abstinence. Le déficit des transporteurs de la dopamine s\'est amélioré d\'environ 20 % sur six à douze mois d\'abstinence, et certaines anomalies de la matière grise et de la substance blanche frontales observées au début du sevrage n\'étaient plus détectables après environ un mois. À trois mois, vous êtes encore au début de cette courbe de récupération : les systèmes de récompense et frontaux se réparent de façon mesurable, mais le processus n\'est pas terminé.\n\nCe que les personnes ressentent\nÀ mesure que ces circuits récupèrent, de nombreuses personnes remarquent vers 90 jours :\n• davantage de plaisir authentique dans les activités, la nourriture et les relations\n• moins d\'envies qu\'au début du rétablissement\n• une pensée plus claire et de meilleures décisions\n\nUn signe de récupération\nL\'imagerie humaine longitudinale montre que la disponibilité des transporteurs de la dopamine augmente au fil de six à douze mois d\'abstinence, tandis que les anomalies de matière grise et de substance blanche frontales commencent à se normaliser bien plus tôt. À 90 jours, une récupération cérébrale mesurable est déjà établie.';

  @override
  String get opioidReferenceDay180 =>
      'Six mois sans opioïdes : le système immunitaire commence à récupérer\n\nSource : « Effects of opioid tolerance and withdrawal on the immune system », Journal of Neuroimmune Pharmacology (2006), sur PubMed\n\nOpioïdes et système immunitaire\nCette revue montre que l\'usage prolongé d\'opioïdes affaiblit le système immunitaire de plusieurs manières :\n• action directe des opioïdes sur des cellules immunitaires — lymphocytes T, cellules NK et macrophages\n• perturbation des molécules de signalisation immunitaire\n• dérèglement de l\'axe hypothalamo-hypophyso-surrénalien (HPA)\n• susceptibilité accrue aux infections\n\nUn signe de récupération\nL\'usage prolongé d\'opioïdes supprime plusieurs composantes du système immunitaire. Après six mois sans opioïdes, cette suppression constante est absente depuis un semestre et la fonction immunitaire se reconstruit activement vers la normale.\n\nCe que signifient six mois\nSix mois sans opioïdes donnent aux cellules immunitaires, aux signaux immunitaires et au système de réponse au stress de l\'organisme un temps prolongé pour revenir vers un fonctionnement normal.\n\nPourquoi cela reste important\nC\'est particulièrement pertinent pour les personnes qui injectaient des opioïdes, qui étaient aussi exposées à des risques infectieux supplémentaires comme le VIH et l\'hépatite C. L\'arrêt des opioïdes, une meilleure nutrition et le maintien de l\'abstinence offrent au système immunitaire les conditions nécessaires pour poursuivre sa récupération.';

  @override
  String get opioidReferenceDay365 =>
      'Un an sans opioïdes : la structure et la chimie du cerveau récupèrent\n\nSource : « Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies », Drug and Alcohol Dependence (2022), sur PubMed Central\n\nCe que montre l\'imagerie humaine\nCette revue a rassemblé les études ayant scanné à plusieurs reprises les mêmes personnes présentant un trouble lié à l\'usage d\'opioïdes pendant leur abstinence. Les résultats convergent vers une récupération :\n• les protéines qui recyclent la dopamine dans les régions liées à la récompense et au mouvement, environ 30 % sous la normale au départ, ont augmenté d\'environ 20 % après six à douze mois sans opioïdes\n• les anomalies de matière grise frontale présentes au début du sevrage n\'étaient plus détectables après environ un mois d\'abstinence\n• la substance blanche frontale et cingulaire ainsi que l\'activité frontale au repos commençaient aussi à se normaliser dès le premier mois\n\nOù en est-on à un an\nÀ douze mois, vous avez atteint ou dépassé la plus longue période mesurée par ces études. Le système dopaminergique a eu le plus de temps pour récupérer et les circuits frontaux qui soutiennent la maîtrise de soi et le jugement se réparent depuis des mois : c\'est le pendant biologique de la pensée plus claire, des envies plus faibles et de l\'humeur plus stable que les personnes décrivent après un an.\n\nUn signe de récupération\nÀ un an, le signal de l\'imagerie humaine est nettement orienté vers la récupération : la disponibilité des transporteurs de la dopamine a augmenté sur la période de six à douze mois, tandis que les anomalies structurelles et fonctionnelles frontales ont eu plusieurs mois pour se normaliser.';

  @override
  String get opioidReferenceDay730 =>
      'Deux ans sans opioïdes : une base stable\n\nSource : « Treatment of Opioid Use Disorder », Centers for Disease Control and Prevention (CDC)\n\nUne maladie chronique, bien prise en charge\nLe CDC décrit le trouble lié à l\'usage d\'opioïdes comme « une maladie chronique qui peut toucher n\'importe qui » : « un problème médical, pas un défaut moral ». Atteindre deux années de rétablissement durable signifie que vous avez réussi à prendre en charge cette maladie pendant l\'une de ses périodes les plus vulnérables.\n\nCe qui fonctionne selon le CDC\nLes recommandations du CDC mettent l\'accent sur des traitements qui aident à stabiliser le rétablissement à long terme :\n• les médicaments du trouble lié à l\'usage d\'opioïdes — buprénorphine, méthadone et naltrexone — que le CDC qualifie de particulièrement efficaces\n• l\'association des médicaments à une thérapie comportementale et à un accompagnement\n• un traitement d\'une durée variable, adapté à chaque personne\nLe CDC indique que ces médicaments aident à « normaliser la chimie du cerveau » et à soulager les envies : la chimie cérébrale qui semblait détournée pendant la dépendance active travaille de nouveau avec vous.\n\nRester en sécurité\nLe CDC encourage les personnes en rétablissement à parler avec leur médecin du risque de reprise et de surdose, et à garder de la naloxone à portée de main. La tolérance diminue pendant l\'abstinence ; reprendre des opioïdes après une période aussi longue est donc particulièrement dangereux. Le savoir fait partie de la protection de ce que vous avez construit.\n\nAprès deux ans\nLe CDC souligne que le rétablissement est souvent un processus de long terme plutôt qu\'une ligne d\'arrivée. Deux ans ne marquent pas la fin du parcours : ils constituent une base stable et saine, ainsi qu\'une preuve solide que l\'approche que vous suivez fonctionne.';

  @override
  String get pornographyReferenceDay1 =>
      'Premier jour : reprendre le contrôle\n\nSource : Kraus et al., Compulsive sexual behaviour disorder in the ICD-11, World Psychiatry (2018).\n\nLe problème cliniquement important n\'est pas l\'usage de pornographie en lui-même. Le trouble du comportement sexuel compulsif est défini par une difficulté persistante à contrôler des comportements sexuels répétitifs lorsque ce schéma provoque une détresse importante ou une altération du fonctionnement. L\'usage problématique de pornographie peut constituer l\'une des manifestations de ce problème plus large.\n\nCela rend le premier jour concret plutôt que mystérieux : vous avez interrompu un comportement que vous aviez jugé hors de contrôle. Une journée terminée ne prouve pas une « réinitialisation » du cerveau ou du système nerveux, mais elle vous donne une première observation réelle des moments où les envies apparaissent, des situations qui les déclenchent et de ce que vous pouvez faire à la place.\n\nSi votre usage ne provoquait ni détresse ni altération du fonctionnement et n\'était pas difficile à contrôler, le cadre clinique du trouble du comportement sexuel compulsif ne s\'applique peut-être pas à vous. Ces jalons s\'adressent aux personnes qui cherchent volontairement à modifier un usage problématique ou compulsif.';

  @override
  String get pornographyReferenceDay3 =>
      'Troisième jour : reconnaître à quoi peut ressembler une envie\n\nSource : Lewczuk et al., Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use, Journal of Behavioral Addictions (2022).\n\nDans un échantillon polonais national représentatif et préenregistré de 1 541 adultes, des expériences de type sevrage plus fortes, déclarées par les participants, étaient associées à une plus grande sévérité du trouble du comportement sexuel compulsif et de l\'usage problématique de pornographie. Parmi les participants présentant un usage problématique, les expériences fréquemment rapportées comprenaient des pensées sexuelles difficiles à interrompre, un désir difficile à contrôler, une excitation accrue, de l\'irritabilité, des changements d\'humeur et des troubles du sommeil.\n\nL\'agitation, les pensées sexuelles intrusives, les envies fortes et l\'irritabilité sont documentées chez les personnes présentant un usage problématique plus sévère. Si elles apparaissent vers le troisième jour, considérez-les comme un schéma réel de type sevrage et travaillez sur les déclencheurs.\n\nNotez quelles envies surviennent réellement, ce qui les a précédées et quelle réponse vous a aidé. Le rétablissement devient plus facile à orienter lorsque le déclencheur est identifié au lieu d\'être traité comme un phénomène cérébral mystérieux.';

  @override
  String get pornographyReferenceDay7 =>
      'Une semaine : ce qu\'a constaté une étude randomisée d\'abstinence\n\nSource : Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nLes chercheurs ont réparti au hasard 176 utilisateurs réguliers de pornographie entre un groupe tentant sept jours d\'abstinence et un groupe poursuivant son usage habituel. Dans l\'ensemble de l\'échantillon, l\'abstinence n\'a pas provoqué d\'augmentation globale significative des envies, de l\'humeur négative ou des symptômes de sevrage.\n\nUne analyse exploratoire a toutefois trouvé une augmentation des envies chez les personnes qui combinaient des scores élevés d\'usage problématique et un usage quotidien avant l\'étude. Ce résultat doit être reproduit, mais il est utile : une première semaine difficile peut être réelle chez les personnes ayant un usage problématique plus intense, tandis que cet essai ne soutient pas l\'idée d\'un syndrome de sevrage universel lié à la pornographie.\n\nSi vous avez passé le cap d\'une semaine, vous disposez maintenant de meilleures informations sur votre propre schéma d\'usage que n\'importe quelle chronologie générique trouvée sur Internet.';

  @override
  String get pornographyReferenceDay14 =>
      'Deux semaines : repérez les déclencheurs qui comptent réellement\n\nSource : Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review (2023).\n\nCette revue a synthétisé 66 études et constaté que l\'usage problématique de pornographie est associé à un ensemble de facteurs plutôt qu\'à un simple mécanisme lié à la dopamine. Parmi les facteurs psychologiques et sociaux régulièrement identifiés figurent les envies, le stress, l\'évitement, la solitude, l\'estime de soi, les croyances négatives et les stratégies d\'adaptation.\n\nDeux semaines vous ont exposé à plusieurs reprises aux jours de semaine, aux week-ends, à l\'ennui, au stress, à l\'intimité, aux appareils et à d\'autres contextes qui pouvaient déclencher l\'ancien comportement. Servez-vous de ces données. Si le stress est le déclencheur, préparez une réponse au stress. Si c\'est la solitude, ajoutez du contact humain. Si c\'est la facilité d\'accès, modifiez l\'environnement.\n\nLes données soutiennent le fait de travailler sur les facteurs qui entretiennent l\'usage problématique ; elles n\'exigent pas de prétendre que chaque personne suit le même compte à rebours biologique.';

  @override
  String get pornographyReferenceDay30 =>
      'Un mois : le contrôle compte davantage qu\'un simple nombre de consultations\n\nSource : Bőthe et al., Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?, Addictive Behaviors (2021).\n\nDans un échantillon communautaire de 14 581 adultes, l\'usage problématique de pornographie présentait une association positive modérée avec des difficultés de fonctionnement sexuel, chez les hommes comme chez les femmes. La fréquence d\'usage de pornographie prise isolément présentait, elle, une faible association négative avec ces difficultés.\n\nCette distinction est importante. Les données ne justifient pas de dire à chaque personne utilisant de la pornographie que la seule fréquence de visionnage altère le fonctionnement sexuel. La cible cliniquement la plus pertinente est la perte de contrôle et les problèmes qui entourent ce schéma.\n\nAprès un mois, comparez votre vie actuelle à celle du début : préoccupation, temps perdu, capacité à vous arrêter, fonctionnement sexuel, conflits relationnels et détresse. Ces changements comptent davantage que d\'attendre une hypothétique « réinitialisation du cerveau » au trentième jour.';

  @override
  String get pornographyReferenceDay90 =>
      'Trois mois : un changement durable est possible\n\nSource : Crosby & Twohig, Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial, Behavior Therapy (2016).\n\nCe petit essai randomisé a comparé un programme de thérapie d\'acceptation et d\'engagement (ACT) en douze séances à une liste d\'attente chez 28 hommes adultes. Le visionnage de pornographie a beaucoup plus diminué dans le groupe ACT à la fin du traitement, et des réductions importantes étaient toujours présentes lors du suivi à trois mois.\n\nL\'étude ne démontre pas que 90 jours d\'abstinence seuls produisent le même résultat, et son échantillon était petit et peu diversifié. Elle montre néanmoins quelque chose d\'important : l\'usage problématique de pornographie peut être modifié et des compétences structurées peuvent produire des changements qui persistent au-delà de la période immédiate de traitement.\n\nSi vos progrès reposent encore surtout sur le fait de résister par la seule volonté, trois mois constituent un bon moment pour renforcer le système autour de vous : plans pour les déclencheurs, acceptation des envies sans agir dessus, obstacles pratiques dans l\'environnement, responsabilisation et thérapie si nécessaire.';

  @override
  String get pornographyReferenceDay180 =>
      'Six mois : le contrôle des symptômes peut se maintenir à long terme\n\nSource : Hallberg et al., A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men, Journal of Sexual Medicine (2019).\n\nChez 137 hommes présentant un comportement sexuel hors de contrôle, sept semaines de thérapie cognitivo-comportementale en groupe ont produit une réduction plus importante des symptômes d\'hypersexualité et de la compulsivité sexuelle qu\'une liste d\'attente, ainsi qu\'une amélioration du bien-être psychiatrique. Les bénéfices du traitement sont restés stables lors des suivis à trois et à six mois.\n\nCette étude portait plus largement sur le trouble hypersexuel et non sur la seule abstinence de pornographie. Elle ne doit donc pas être transformée en affirmation selon laquelle chaque personne serait biologiquement « rétablie » à six mois. Elle soutient toutefois une conclusion plus solide et plus utile : une amélioration durable du comportement sexuel compulsif peut rester stable sur une période de cette durée.\n\nSix mois constituent donc un jalon de maintien. Conservez les habitudes qui ont facilité le contrôle au lieu de considérer cette date comme une autorisation de les abandonner.';

  @override
  String get pornographyReferenceDay365 =>
      'Un an : des données en faveur d\'un changement comportemental durable\n\nSource : One-year follow-up effects of an acceptance-based treatment for hypersexuality (2026).\n\nLors du suivi à un an, les participants à cette étude d\'un traitement fondé sur l\'acceptation n\'étaient pas revenus à leurs niveaux d\'hypersexualité d\'avant le traitement. Les auteurs ont décrit ces résultats comme des données préliminaires en faveur de bénéfices durables et cliniquement significatifs, le contrôle perçu des envies faisant partie des processus suivis au fil du temps.\n\nIl s\'agit de données de suivi après traitement, et non de la preuve d\'une « réinitialisation du cerveau » au bout d\'un an. La conclusion utile est meilleure : un contrôle cliniquement pertinent peut persister pendant un an au lieu de disparaître dès la fin de l\'intervention initiale.\n\nUne année de changement maintenu vous donne également beaucoup d\'informations sur votre propre évolution. Comparez votre contrôle actuel, votre détresse, votre fonctionnement, vos relations et votre emploi du temps à votre situation de départ : ce sont ces résultats qui comptent cliniquement.';

  @override
  String get pornographyReferenceDay1825 =>
      'Cinq ans : le contrôle à long terme est le véritable résultat\n\nSource : Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\nLes revues modernes considèrent le trouble du comportement sexuel compulsif et l\'usage problématique de pornographie comme des problèmes complexes impliquant le contrôle, la détresse, le fonctionnement, le contexte et les différences individuelles. Il n\'existe pas de seuil validé de « réinitialisation » du cerveau et du système nerveux à cinq ans.\n\nCinq ans ne constituent pourtant pas un jalon vide. Ce sont 1 825 jours pendant lesquels vous avez maintenu l\'orientation comportementale que vous aviez choisie. Puisque le problème clinique est une perte de contrôle persistante accompagnée de détresse ou d\'une altération du fonctionnement, un contrôle durable et un fonctionnement restauré pendant plusieurs années sont des résultats significatifs à part entière.\n\nÀ ce stade, la question utile n\'est plus de savoir si votre cerveau a atteint un pourcentage fictif de « recâblage ». Il s\'agit de savoir si l\'ancien schéma contrôle encore vos choix ou perturbe la vie que vous souhaitez. Si ce n\'est plus le cas, c\'est une réussite substantielle à long terme.';

  @override
  String get smokingReferenceDay1 =>
      'Premier jour : les bénéfices commencent maintenant\n\nSource : NHS Better Health\n\nLes bénéfices commencent en quelques minutes, pas en plusieurs jours. Dès que la fumée cesse, l\'organisme commence à revenir vers la normale.\n\nCe qui se passe aujourd\'hui\n• après 20 minutes : le pouls commence à revenir vers la normale\n• après 8 heures : le monoxyde de carbone dans le sang a diminué de moitié et le taux d\'oxygène se rétablit\n• après 48 heures : le monoxyde de carbone est revenu au niveau d\'une personne non-fumeuse\n\nLe monoxyde de carbone se fixe aux globules rouges plus fortement que l\'oxygène et prend sa place dans le sang. Chaque organe recevait donc moins d\'oxygène qu\'il n\'aurait dû. Cet effet s\'inverse en deux jours.\n\nLe sevrage commence dès le premier jour\n• envies de fumer, durant généralement trois à cinq minutes chacune\n• irritabilité et difficultés de concentration\n• augmentation de l\'appétit\n\nCes symptômes sont temporaires et peuvent être pris en charge. Le programme NHS Better Health propose un soutien gratuit, notamment des applications et des conseils de pharmaciens.';

  @override
  String get smokingReferenceDay3 =>
      'Troisième jour : le pic du sevrage\n\nSource : McLaughlin, Dani & De Biasi\n\nAprès 72 heures, la nicotine a quitté votre organisme. Pendant les années de tabagisme, le cerveau a développé davantage de récepteurs nicotiniques ; désormais insuffisamment stimulés, ils participent au syndrome de sevrage.\n\nSymptômes au pic\n• envies de fumer — elles sont généralement les plus intenses à ce stade\n• irritabilité, frustration et agitation\n• difficultés de concentration\n• anxiété\n• maux de tête\n• augmentation de l\'appétit\n• toux — les voies respiratoires se dégagent, ce qui est un signe de récupération\n\nC\'est généralement l\'une des journées les plus difficiles. À partir de là, les symptômes tendent à diminuer progressivement à mesure que le cerveau se réadapte.\n\nLes substituts nicotiniques, la varénicline et le bupropion réduisent significativement la gravité du sevrage à ce stade.';

  @override
  String get smokingReferenceDay7 =>
      'Une semaine : le goût et l\'odorat reviennent\n\nSource : NHS Better Health\n\nAtteindre une semaine sans fumer est un indicateur important de réussite à long terme : les personnes qui passent la première semaine ont beaucoup plus de chances d\'arrêter durablement.\n\nCe qui a récupéré\n• les aliments ont davantage de goût\n• les odeurs sont plus nettes\n• la respiration est plus facile à mesure que les voies respiratoires se dégagent\n• la circulation s\'améliore\n• la peau est mieux hydratée\n\nLe tabagisme endommage directement les récepteurs du goût et de l\'odorat ; quelques jours après l\'arrêt, ils commencent à récupérer.\n\nLe sevrage aigu de la nicotine s\'atténue. Les envies physiques sont plus courtes et moins fréquentes. Les envies déclenchées par certaines situations peuvent encore être présentes, mais le plus fort de l\'urgence physique est derrière vous.';

  @override
  String get smokingReferenceDay14 =>
      'Deux semaines : la circulation s\'améliore\n\nSource : NHS Better Health\n\nEntre deux et douze semaines après l\'arrêt, la circulation sanguine s\'améliore. La nicotine resserre les vaisseaux sanguins à chaque cigarette ; sans elle, les vaisseaux se détendent et le sang circule plus librement.\n\nCe que cela signifie\n• le débit sanguin vers les mains, les pieds et les tissus périphériques s\'améliore\n• de nombreuses personnes remarquent que leurs mains et leurs pieds sont plus chauds\n• marcher et monter les escaliers commence à sembler plus facile\n\nLe monoxyde de carbone ayant déjà été éliminé du sang dès les premiers jours et la circulation s\'améliorant maintenant, l\'oxygène atteint plus efficacement les muscles.\n\nLes cils qui tapissent les voies respiratoires récupèrent et évacuent le mucus accumulé. Si vous toussez davantage que d\'habitude, cela peut être un signe de récupération plutôt qu\'un recul.';

  @override
  String get smokingReferenceDay30 =>
      'Un mois : la fonction pulmonaire progresse\n\nSource : NHS Better Health\n\nLa respiration devient plus facile et la fonction pulmonaire s\'améliore — jusqu\'à environ 10 % sur une période de trois à neuf mois. Après un mois, vous êtes déjà bien engagé sur cette courbe de récupération.\n\nCe qui se passe dans les poumons\n• les cils ont repoussé et évacuent le mucus plus efficacement\n• l\'inflammation des voies respiratoires s\'atténue\n• la toux persistante du fumeur diminue\n• la tolérance à l\'effort s\'améliore\n\nLa toux, les sifflements respiratoires et les difficultés à respirer s\'améliorent à mesure que la fonction pulmonaire progresse. Un mois représente un point significatif de cette récupération.';

  @override
  String get smokingReferenceDay90 =>
      'Trois mois : le risque d\'infarctus diminue\n\nSource : PMC — Cardiovascular Effects of Smoking and Cessation (2024)\n\nLe tabagisme endommage le cœur et les artères de plusieurs façons : il accélère l\'accumulation de plaques dans les artères, favorise la coagulation, augmente la pression artérielle et abîme la paroi artérielle. Les effets procoagulants qui favorisent les caillots s\'inversent dans les jours suivant l\'arrêt, et cette revue rapporte une diminution notable des infarctus et des AVC au cours de la première année sans tabac.\n\nCe qui s\'est déjà amélioré\n• les facteurs de coagulation se normalisent\n• la pression artérielle et le rythme cardiaque se stabilisent\n• la baisse initiale la plus rapide du risque d\'événement cardiovasculaire aigu est déjà bien engagée\n\nLes bénéfices plus lents — notamment l\'inversion de plusieurs années d\'accumulation de plaques artérielles — prennent davantage de temps et sont abordés dans les jalons suivants. Chaque mois sans fumée ajoute à la récupération.';

  @override
  String get smokingReferenceDay180 =>
      'Six mois : les défenses immunitaires récupèrent\n\nSource : Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\nLe tabagisme affaiblit les cellules immunitaires situées au plus profond des poumons et réduit leur capacité à engloutir et à détruire les bactéries. La récupération est progressive : les personnes abstinentes depuis seulement deux mois présentent les altérations les plus marquées, tandis que la fonction s\'améliore régulièrement avec la durée de l\'abstinence. Après six mois, les défenses immunitaires pulmonaires ont récupéré de manière importante.\n\nCe que cela signifie\nLes poumons peuvent éliminer plus efficacement les bactéries et les particules inhalées, ce qui réduit la vulnérabilité aux rhumes, à la grippe et à la pneumonie.\n\nLes défenses immunitaires continuent de s\'améliorer au-delà de six mois, mais à ce stade la protection de l\'organisme est déjà nettement plus forte qu\'au cours des premières semaines.';

  @override
  String get smokingReferenceDay365 =>
      'Un an : le risque d\'infarctus diminue fortement\n\nSource : PMC — Smoking Cessation and Stroke Outcome ; CDC, Benefits of Quitting Smoking\n\nLe tabagisme double approximativement le risque d\'AVC en favorisant l\'accumulation de plaques dans les artères, en augmentant la coagulation et la pression artérielle, et en endommageant les vaisseaux sanguins du cerveau. La chronologie des bénéfices de l\'arrêt publiée par le CDC situe la forte baisse du risque d\'infarctus entre un et deux ans : vous entrez donc dans cette période.\n\nChronologie de la récupération\nLa normalisation complète du risque d\'AVC prend plus de temps. L\'étude citée sur les AVC a suivi les personnes ayant arrêté pendant une durée médiane de près de cinq ans pour mettre en évidence un taux d\'AVC sensiblement inférieur à celui des personnes continuant à fumer. Les données du CDC situent une division par deux du risque de maladie coronarienne entre trois et six ans, et une diminution du risque d\'AVC sur une période de cinq à dix ans.\n\nUn an reste un véritable jalon médical : la partie la plus forte de la baisse du risque aigu est derrière vous, même si les bénéfices cardiovasculaires et anticancéreux à long terme continuent de s\'accumuler pendant des années.';

  @override
  String get smokingReferenceDay1825 =>
      'Cinq ans : le risque de cancer diminue\n\nSource : CDC, Benefits of Quitting Smoking\n\nÀ cinq ans, certains des bénéfices les plus importants concernant le cancer apparaissent.\n\nJalons entre cinq et dix ans\n• le sur-risque de cancers de la bouche, de la gorge et du larynx est divisé par deux\n• le risque d\'AVC diminue\n\nCe qui vient encore\n• dix ans : le risque de mourir d\'un cancer du poumon est environ divisé par deux après dix à quinze ans ; les risques de cancers de la vessie, de l\'œsophage et du rein diminuent\n• quinze ans : le risque de maladie coronarienne se rapproche de celui d\'une personne non-fumeuse\n• vingt ans : le risque de cancers de la bouche, de la gorge et du larynx se rapproche de celui d\'une personne non-fumeuse ; le sur-risque de cancer du col de l\'utérus est environ divisé par deux\n\nCinq années sans fumer constituent un véritable accomplissement : vous êtes désormais dans la période où certaines des réductions les plus importantes du risque de cancer se manifestent, même si plusieurs bénéfices — comme la normalisation complète du risque de maladie coronarienne — demandent encore des années.';

  @override
  String get snriReferenceDay3 =>
      'Arrêt des IRSN : les premiers jours\n\nSource : Harvard Health Publishing\n\nNote de sécurité importante\nLes IRSN ne doivent être arrêtés que sous supervision médicale, selon une diminution progressive. La venlafaxine (Effexor), en particulier, a une demi-vie extrêmement courte d\'environ cinq heures : le médicament est donc éliminé très rapidement et les symptômes de sevrage peuvent être sévères et apparaître brutalement.\n\nPourquoi les IRSN peuvent être plus difficiles à arrêter que les ISRS\nLes IRSN agissent sur deux substances cérébrales qui régulent l\'humeur — la sérotonine et la noradrénaline — et les deux systèmes doivent donc se réadapter à l\'arrêt. Les symptômes de sevrage sont souvent plus intenses qu\'avec les ISRS :\n• symptômes pseudo-grippaux — fatigue, transpiration, douleurs musculaires\n• insomnie et sommeil perturbé\n• nausées, souvent plus marquées qu\'avec les ISRS\n• troubles de l\'équilibre et vertiges\n• troubles sensoriels — les « décharges cérébrales » peuvent être particulièrement intenses avec la venlafaxine\n• hyperactivation, irritabilité et anxiété\n\nComparer les IRSN\nLa venlafaxine présente le profil de sevrage le plus difficile en raison de sa courte demi-vie. La duloxétine (Cymbalta) tend à être un peu plus facile à arrêter grâce à sa demi-vie plus longue, d\'environ douze heures. La desvenlafaxine se situe entre les deux.';

  @override
  String get snriReferenceDay7 =>
      'Une semaine après l\'arrêt des IRSN : deux systèmes neurochimiques se réadaptent\n\nSource : NHS — Stopping or coming off antidepressants (recommandations générales sur les antidépresseurs ; les mécanismes spécifiques à la noradrénaline décrits ci-dessous relèvent de la pharmacologie générale des IRSN plutôt que de détails propres aux IRSN sur la page du NHS)\n\nLe défi de deux systèmes\nContrairement à de nombreux antidépresseurs qui agissent principalement sur un seul système, les IRSN influencent à la fois la sérotonine et la noradrénaline. Au bout d\'une semaine, les deux systèmes sont en cours de réadaptation.\n\nEffets liés au système noradrénergique\nLe système de la noradrénaline participe à la réaction de lutte ou de fuite, à la régulation de la pression artérielle et au niveau d\'énergie. Pendant sa réadaptation :\n• des variations de la pression artérielle peuvent survenir\n• l\'anxiété peut être ressentie de façon plus physique — cœur qui s\'emballe, transpiration\n• le niveau d\'énergie peut être irrégulier\n\nEffets liés au système sérotoninergique\nEn parallèle, le système de la sérotonine se réadapte et peut produire les symptômes de sevrage typiques de l\'arrêt d\'un antidépresseur. La réadaptation simultanée des deux systèmes peut rendre la première semaine particulièrement difficile.\n\nSur le plan physique, cela se traduit souvent par une pression artérielle qui devient plus stable et moins d\'épisodes de vertige au passage en position debout. Sur le plan émotionnel, l\'humeur reste plus variable qu\'elle ne le sera après 30 jours, mais elle n\'est plus dans la phase de chute la plus brutale.';

  @override
  String get snriReferenceDay14 =>
      'Deux semaines après l\'arrêt des IRSN : les symptômes physiques s\'estompent\n\nSource : Davies & Read (2019), Addictive Behaviors\n\nÉtat après deux semaines\nPour la plupart des personnes ayant suivi une diminution progressive adaptée, la phase physique aiguë est largement résolue au bout de deux semaines :\n• les décharges cérébrales ont nettement diminué ou ont disparu\n• les nausées et les symptômes pseudo-grippaux sont résolus\n• les vertiges et les troubles de l\'équilibre s\'améliorent\n• la pression artérielle et le rythme cardiaque se stabilisent à mesure que la noradrénaline se rééquilibre\n\nCe qui peut persister\n• une sensibilité émotionnelle et une humeur variable\n• de l\'anxiété, fortement influencée par le système noradrénergique\n• de la fatigue, puisque ce système participe à la vigilance et à l\'énergie\n\nContexte de la recherche\nLa revue systématique publiée dans Addictive Behaviors par Davies & Read en 2019 a confirmé que les effets de sevrage des IRSN comptent parmi les plus sévères de toutes les classes d\'antidépresseurs, la venlafaxine étant associée à des taux particulièrement élevés de symptômes de sevrage importants.';

  @override
  String get snriReferenceDay30 =>
      'Un mois après l\'arrêt des IRSN : les deux systèmes se stabilisent\n\nSource : Davies & Read (2019), Addictive Behaviors — revue systématique de la fréquence, de la gravité et de la durée du sevrage des antidépresseurs\n\nLa phase de stabilisation\nUn mois représente un cap important dans le rétablissement des systèmes de la sérotonine et de la noradrénaline. Cette revue a constaté que, même si une minorité importante de personnes présente des effets de sevrage pendant plus de quelques semaines, la plupart ont dépassé à ce stade la phase aiguë et la plus sévère des symptômes physiques de sevrage.\n\nCe qui s\'améliore généralement au bout d\'un mois\n• les symptômes physiques de sevrage — décharges cérébrales, nausées, vertiges — ont disparu chez la plupart des personnes\n• la pression artérielle revient vers son niveau naturel\n• la qualité du sommeil s\'améliore et les cycles de sommeil paradoxal se rétablissent naturellement\n• l\'énergie commence à se stabiliser à mesure que la régulation de la noradrénaline se normalise\n\nDisparition de l\'émoussement émotionnel\nL\'une des expériences les plus souvent rapportées à ce stade est la disparition de l\'émoussement émotionnel : de nombreuses personnes sous IRSN remarquent une palette émotionnelle « aplatie ». À mesure que le médicament est éliminé et que le cerveau se réadapte, l\'étendue et la sensibilité émotionnelles reviennent généralement.';

  @override
  String get snriReferenceDay90 =>
      'Trois mois après l\'arrêt des IRSN : le sevrage est largement derrière vous\n\nSource : « Antidepressant Withdrawal Syndrome », Therapeutics Letter 112 (2018), Therapeutics Initiative, sur NCBI Bookshelf\n\nPourquoi les IRSN demandent une attention particulière\nCette revue des données souligne que les antidépresseurs à demi-vie courte — notamment la venlafaxine et la duloxétine, qui sont toutes deux des IRSN — présentent un risque plus élevé de symptômes de sevrage. Une étude financée par un fabricant a constaté que 51 % des personnes arrêtant la duloxétine avaient présenté un ou plusieurs symptômes. Le sevrage des IRSN peut donc être marqué, ce qui explique précisément l\'importance d\'une diminution progressive et supervisée.\n\nOù en est-on à trois mois\nLa Letter indique que les symptômes de sevrage « apparaissent généralement dans les quelques jours suivant l\'arrêt » et que « la plupart des symptômes de sevrage des antidépresseurs disparaissent en deux semaines », parfois plus tard. Au bout de trois mois, la phase aiguë est largement terminée pour la grande majorité des personnes.\n\nCe que l\'on peut réellement dire de la « récupération des récepteurs »\nDes chronologies populaires affirment que les systèmes de la sérotonine et de la noradrénaline seraient « complètement rééquilibrés » en trois mois. Les données solides portent sur le syndrome de sevrage et sa durée, pas sur une horloge précise de récupération des récepteurs. Ce qui est fiable, c\'est qu\'à trois mois le sevrage est généralement résolu et que de nombreuses personnes constatent que l\'émoussement émotionnel parfois ressenti sous IRSN diminue après l\'arrêt.\n\nSevrage ou rechute\nLa Letter recommande de distinguer le sevrage d\'un véritable retour du trouble sous-jacent. Si l\'anxiété ou une baisse de moral persiste à trois mois, faites-en le point avec votre prescripteur au lieu de supposer qu\'il s\'agit uniquement du sevrage.';

  @override
  String get snriReferenceDay180 =>
      'Six mois après l\'arrêt des IRSN : récupération du cerveau et du système nerveux\n\nCe que montrent les données à six mois\nSix mois après la fin d\'une diminution progressive supervisée médicalement, la période difficile du début du sevrage des IRSN est largement derrière vous. L\'humeur, le sommeil, la fonction sexuelle et la clarté de pensée ont eu plusieurs mois pour récupérer :\n• voies sérotoninergiques : largement rétablies\n• voies noradrénergiques : normalisées, avec un système de réponse au stress qui s\'est lui aussi stabilisé\n• architecture du sommeil : devrait être entièrement rétablie\n• fonction sexuelle : largement rétablie chez la plupart des personnes ; les troubles sexuels sont un effet indésirable fréquent des IRSN, mais peuvent persister chez certaines personnes et méritent alors d\'être discutés avec le prescripteur\n\nRésilience face au stress\nÀ six mois, de nombreuses personnes rapportent une meilleure résistance aux facteurs de stress quotidiens, à mesure que le rôle du système noradrénergique dans l\'activation et la réponse au stress — fortement modulé par les IRSN — revient vers son niveau naturel.';

  @override
  String get snriReferenceDay365 =>
      'Un an après l\'arrêt des IRSN : le rétablissement est accompli\n\nUn an : récupération complète des deux systèmes\nUn an après la fin d\'une diminution progressive d\'un IRSN, les systèmes de la sérotonine et de la noradrénaline ont eu un cycle complet pour s\'adapter et se stabiliser.\n\nCe que les données permettent réellement d\'affirmer à un an\nCette revue de Therapeutics Letter indique que les symptômes de sevrage documentés « apparaissent généralement dans les quelques jours suivant l\'arrêt » et que la plupart disparaissent en environ deux semaines. Il n\'existe pas d\'étude contrôlée suivant spécifiquement les personnes un an après l\'arrêt d\'un IRSN. À cette distance, le tableau clinique général permet toutefois d\'appuyer solidement les points suivants :\n• la majorité des personnes ayant suivi une diminution progressive appropriée et reçu un soutien psychologique vont bien\n• l\'émoussement émotionnel et les troubles sexuels associés à l\'utilisation d\'un IRSN ont entièrement disparu chez la plupart des personnes\n• une pensée claire, y compris la capacité de concentration que les IRSN peuvent favoriser pendant le traitement, est maintenue par le fonctionnement naturel du cerveau\n\nL\'importance de ce cap\nRéussir à arrêter un IRSN — en particulier la venlafaxine — représente un accomplissement important. L\'intensité possible du processus de sevrage et l\'engagement nécessaire pour le gérer sous supervision médicale témoignent d\'une grande résilience.';

  @override
  String get socialMediaReferenceDay1 =>
      'Prendre du recul par rapport aux réseaux sociaux : premier jour\n\nSource : Lambert et al., « Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial », Cyberpsychology, Behavior, and Social Networking (2022), sur PubMed\n\nCe que montrent les données\nDans cette étude contrôlée solide, les participants ont été répartis au hasard entre une pause d\'une semaine de Facebook, Instagram, Twitter et TikTok, ou la poursuite de leur usage habituel. Le groupe ayant fait une pause a montré une amélioration significative du bien-être ainsi qu\'une diminution de la dépression et de l\'anxiété. Il s\'agit donc de données contrôlées réelles montrant qu\'un recul peut aider.\n\nCe que montre l\'ensemble des données\nL\'usage compulsif des réseaux sociaux est fortement associé à une humeur plus basse et à davantage d\'anxiété, et des essais randomisés montrent qu\'une réduction volontaire peut améliorer le bien-être tout en diminuant la dépression et l\'anxiété en une semaine.\n\nPremier jour : à quoi s\'attendre\n• agitation et envie de vérifier\n• notifications « fantômes », avec l\'impression d\'avoir senti une vibration qui n\'a pas eu lieu\n• ennui pendant l\'adaptation à une stimulation moins constante\nCes sensations liées à l\'habitude sont normales et temporaires. Reconnaître ce schéma constitue la première étape pour le changer.';

  @override
  String get socialMediaReferenceDay3 =>
      'Trois jours sans réseaux sociaux : anxiété et humeur\n\nSource : Lambert et al., « Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial », Cyberpsychology, Behavior, and Social Networking (2022), sur PubMed\n\nPourquoi une pause aide l\'humeur\nDans cet essai contrôlé, les personnes assignées au hasard à une pause d\'une semaine des réseaux sociaux terminaient la semaine avec moins d\'anxiété et de symptômes dépressifs, et davantage de bien-être, que celles qui continuaient à faire défiler leur fil. Une grande partie de la détresse quotidienne liée à un usage intense vient de la comparaison sociale — confronter sa vie réelle aux meilleurs moments soigneusement sélectionnés par les autres — et de la pression diffuse liée à la peur de manquer quelque chose.\n\nCe qui se passe vers 72 heures\nAu début d\'une pause, l\'habitude se fait encore fortement sentir :\n• envie marquée de vérifier, souvent déclenchée par des moments routiniers comme le réveil ou l\'attente dans une file\n• une certaine irritabilité et de l\'agitation\n• chez certaines personnes, un premier recul de l\'anxiété alimentée par la comparaison\n• l\'habitude de faire défiler avant de dormir commence à perdre de sa force\n\nLe piège de la comparaison se desserre\nSans flux constant des meilleurs moments des autres, la comparaison qui nourrit une grande partie de l\'anxiété liée aux réseaux sociaux dispose de moins de carburant. Les résultats de l\'essai suggèrent qu\'à la fin de la première semaine, ces premiers changements s\'additionnent pour produire une amélioration mesurable de l\'humeur : l\'inconfort du troisième jour est donc la partie difficile d\'un changement qui finit par porter ses fruits.';

  @override
  String get socialMediaReferenceDay7 =>
      'Une semaine sans réseaux sociaux : un bénéfice mesuré\n\nSource : Lambert et al., « Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial », Cyberpsychology, Behavior, and Social Networking (2022), sur PubMed\n\nExactement une semaine — et cela a fonctionné\nC\'est le cap auquel la recherche répond le plus directement : l\'intervention de l\'essai était une pause d\'une semaine. Par rapport aux personnes qui continuaient à utiliser les réseaux sociaux, le groupe ayant fait une pause présentait, après seulement sept jours, un bien-être significativement plus élevé ainsi que des niveaux de dépression et d\'anxiété significativement plus faibles. Atteindre une semaine, c\'est donc atteindre le point où une étude contrôlée a constaté un bénéfice réel.\n\nCe que les personnes remarquent souvent\nEn plus des améliorations de l\'humeur mesurées, les personnes rapportent fréquemment :\n• du temps récupéré — beaucoup sont surprises de découvrir combien elles en consacraient auparavant\n• une concentration plus facile à mesure que l\'habitude de changer constamment d\'attention perd de sa force\n• des soirées plus calmes et un endormissement plus simple sans le défilement avant le coucher\nCes gains concordent avec l\'amélioration générale du bien-être mesurée dans l\'essai.\n\nContinuez\nUne semaine est un véritable cap étayé par des données. Les bénéfices sur l\'humeur, le temps disponible et l\'attention ont tendance à s\'approfondir à mesure que ce rythme plus sain se maintient.';

  @override
  String get socialMediaReferenceDay14 =>
      'Deux semaines sans réseaux sociaux : des progrès mesurés\n\nSource : Coyne & Woodruff, « Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults », Behavioral Sciences (2023), sur PubMed Central\n\nÀ propos de cette étude\nDe jeunes adultes ont limité les réseaux sociaux à environ 30 minutes par jour pendant deux semaines, avec un suivi objectif de l\'utilisation sur leur téléphone ; leur usage a diminué d\'environ 78 %. Cette réduction d\'environ 78 % offre à ce cap une vérification directe, en conditions réelles, de ce qui se passe lorsque l\'utilisation est fortement diminuée pendant deux semaines.\n\nCe qui s\'est amélioré\nAu cours de ces deux semaines, les participants ont montré des améliorations concernant :\n• le sommeil, tant sa durée que sa qualité\n• la satisfaction dans la vie\n• le stress\n• le bien-être perçu\n• les scores d\'addiction au smartphone et aux réseaux sociaux\nLes progrès mesurés étaient concrets : sommeil plus long et de meilleure qualité, stress plus faible, satisfaction dans la vie et bien-être perçu plus élevés, et scores d\'addiction au smartphone et aux réseaux sociaux plus faibles.\n\nAttention au retour des anciennes habitudes\nLes chercheurs ont également observé que l\'utilisation tendait ensuite à remonter vers les niveaux précédents. Deux semaines constituent un vrai progrès, mais soulignent pourquoi un plan intentionnel — et pas seulement une pause temporaire — est nécessaire pour conserver les bénéfices.';

  @override
  String get socialMediaReferenceDay30 =>
      'Un mois sans réseaux sociaux : les liens réels s\'approfondissent\n\nSource : Coyne & Woodruff, « Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults », Behavioral Sciences (2023), sur PubMed Central\n\nPrendre du recul peut améliorer les liens\nCela peut sembler paradoxal, mais dans cette étude, réduire fortement les réseaux sociaux était associé à une amélioration des relations de soutien, ainsi qu\'à une meilleure satisfaction dans la vie et à moins de stress. Le temps et l\'attention autrefois absorbés par le fil d\'actualité redeviennent disponibles pour les personnes réellement présentes dans votre vie.\n\nCe qu\'apporte souvent un mois\nAprès 30 jours, lorsque l\'impulsion automatique de vérifier son téléphone s\'est nettement affaiblie, beaucoup de personnes constatent :\n• des conversations plus présentes et moins interrompues\n• davantage d\'intérêt pour les activités et loisirs dans le monde réel\n• une image de soi moins dépendante des mentions « J\'aime », des commentaires et du nombre d\'abonnés\n\nUn signe de progression\nAu bout d\'un mois, vous avez maintenu ce rythme plus sain pendant deux fois la durée de l\'intervention étudiée. Les améliorations du sommeil, du stress, de la satisfaction dans la vie, du bien-être et des relations mesurées à deux semaines ont eu deux semaines supplémentaires pour devenir une routine.\n\nDonnez de la valeur au temps libéré\nEssayez d\'occuper ce temps avec des activités qui créent de véritables liens et un sentiment d\'accomplissement, plutôt que de simplement remplacer un écran par un autre.';

  @override
  String get socialMediaReferenceDay60 =>
      'Deux mois sans réseaux sociaux : ce que les données permettent d\'affirmer\n\nSource : Ramadhan et al., « Impacts of digital social media detox for mental health: A systematic review and meta-analysis », Narra J (2024), sur PubMed Central\n\nLe tableau le plus fiable\nLes chercheurs ont regroupé les résultats de dix études, dont sept essais contrôlés. Le résultat le plus net était une réduction significative des symptômes dépressifs lorsque les participants prenaient du recul par rapport aux réseaux sociaux.\n\nLe résultat le plus solide\nL\'ensemble des recherches a mis en évidence une diminution claire des symptômes dépressifs. Après deux mois, vous maintenez le même type d\'exposition numérique réduite que celle qui a produit ce bénéfice pour la santé mentale.\n\nÀ quoi peuvent ressembler deux mois\nAvec moins de comparaison quotidienne et moins de renforcement piloté par le fil d\'actualité, l\'image de soi a beaucoup moins de raisons de dépendre des mentions « J\'aime », des commentaires ou du nombre d\'abonnés, tandis que les données regroupées les plus solides indiquent une diminution des symptômes dépressifs.\n\nEn pratique\nLes données favorisent un changement volontaire et durable. Profitez du cap des deux mois pour maintenir des limites choisies au lieu de revenir progressivement aux anciennes habitudes, et pour investir dans des sources de sens et de lien hors ligne.';

  @override
  String get socialMediaReferenceDay90 =>
      'Trois mois sans réseaux sociaux : une nouvelle normalité\n\nSource : Coyne & Woodruff, « Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults », Behavioral Sciences (2023), sur PubMed Central\n\nLe sommeil se distingue particulièrement\nParmi les résultats les plus nets de cette étude figurait une amélioration du sommeil, tant de sa durée que de sa qualité, lorsque les participants réduisaient fortement les réseaux sociaux. Après trois mois d\'un rythme durablement plus sain, le défilement tard le soir qui empiétait autrefois sur le sommeil ne rivalise plus depuis longtemps avec le repos, et un meilleur sommeil tend aussi à améliorer l\'humeur, la concentration et l\'énergie.\n\nLes autres améliorations observées\nLa même étude a constaté des progrès concernant le stress, la satisfaction dans la vie, le bien-être perçu et les relations de soutien. À trois mois, ces changements ne sont plus des nouveautés : ils ont eu le temps de s\'installer dans une nouvelle normalité.\n\nCe que l\'on peut dire du mécanisme\nDans l\'étude d\'intervention, une forte réduction des réseaux sociaux a amélioré à la fois la durée et la qualité du sommeil. Maintenir ce rythme pendant trois mois transforme la réduction du défilement nocturne en une habitude de sommeil durable.\n\nPrésence et relations\nLorsque le réflexe de remplir chaque moment calme avec le téléphone s\'affaiblit nettement, il devient plus naturel d\'être présent — dans les conversations, pendant les repas et dans les moments de repos — et les relations auxquelles vous avez consacré du temps pendant ces trois mois ont tendance à s\'en trouver renforcées.';

  @override
  String get socialMediaReferenceDay180 =>
      'Six mois sans réseaux sociaux : un effet mesuré\n\nSource : Ramadhan et al., « Impacts of digital social media detox for mental health: A systematic review and meta-analysis », Narra J (2024), sur PubMed Central\n\nCe qu\'apporte la méta-analyse\nEn regroupant dix études, dont sept essais contrôlés, les chercheurs ont constaté une diminution nette des symptômes dépressifs lorsque les participants réduisaient ou interrompaient leur utilisation des réseaux sociaux.\n\nCe qu\'elle a réellement constaté\n• dépression : réduction statistiquement significative, qui constitue le bénéfice le plus clair et le plus constant\n• satisfaction dans la vie : pas d\'effet significatif\n• stress : pas d\'effet significatif\n• bien-être mental global : pas d\'effet significatif\nLe résultat groupé le plus solide est donc clair : la détox numérique réduit significativement les symptômes dépressifs.\n\nPourquoi des bénéfices plus larges peuvent malgré tout être ressentis\nSix mois avec moins d\'exposition au fil d\'actualité amplifient les gains pratiques observés dans les interventions plus courtes : davantage de temps disponible, moins de vérifications compulsives et une réduction durable de l\'exposition numérique associée aux symptômes dépressifs.\n\nGardez le contrôle du fil\nLes bénéfices les plus importants viennent de la rupture avec un usage intense, passif et compulsif. Au bout de six mois, l\'usage intentionnel des réseaux sociaux devient la nouvelle norme, au lieu de laisser le fil contrôler votre attention.';

  @override
  String get socialMediaReferenceDay365 =>
      'Un an sans réseaux sociaux : une relation redéfinie\n\nSource : Ramadhan et al., « Impacts of digital social media detox for mental health: A systematic review and meta-analysis », Narra J (2024), sur PubMed Central\n\nUne année de changement durable\nLes recherches regroupées les plus solides montrent que prendre du recul par rapport aux réseaux sociaux réduit les symptômes dépressifs. Une année entière signifie que ce rythme de moindre exposition est devenu votre normalité plutôt qu\'une simple pause temporaire.\n\nCe qu\'une année permet de construire\nUne année entière vous rend des centaines d\'heures pour les relations réelles, les loisirs, l\'apprentissage, la réflexion et la créativité. Le réflexe de vérification automatique a eu un an pour s\'affaiblir, tandis que ces habitudes hors ligne ont eu un an pour se renforcer.\n\nDes bénéfices durables\nLe bénéfice de santé mentale le plus clairement mesuré est une diminution des symptômes dépressifs. Les bénéfices pratiques — davantage de temps, moins d\'interruptions et moins de vérifications compulsives — s\'accumulent chaque jour où vous gardez le contrôle du fil.\n\nEt ensuite ?\nUne année de changement volontaire a redéfini votre relation aux réseaux sociaux. Que vous reveniez à un usage limité et intentionnel ou que vous choisissiez de rester complètement à l\'écart, la boucle compulsive a été rompue : c\'est le bénéfice durable.';

  @override
  String get ssriReferenceDay3 =>
      'Arrêt des ISRS : les premiers jours\n\nSource : Harvard Health Publishing\n\nNote de sécurité importante\nLes ISRS ne doivent être arrêtés que sous supervision médicale, selon une diminution progressive de la dose. Un arrêt brutal — en particulier après une utilisation prolongée — augmente nettement la gravité des symptômes de sevrage.\n\nQu\'est-ce que le syndrome de sevrage des ISRS ?\nLe syndrome de sevrage des ISRS est un phénomène médical bien documenté qui survient lorsqu\'un ISRS est arrêté ou fortement réduit. Les cliniciens utilisent l\'acronyme FINISH pour décrire les symptômes fréquents :\n• symptômes pseudo-grippaux — fatigue, transpiration, douleurs musculaires\n• insomnie et sommeil perturbé\n• nausées\n• troubles de l\'équilibre et vertiges\n• troubles sensoriels, notamment les « décharges cérébrales »\n• hyperactivation, irritabilité et anxiété\n\nLa demi-vie compte\nLa fluoxétine (Prozac) a une très longue demi-vie de quatre à six jours ; son taux diminue donc naturellement plus lentement et elle provoque généralement des effets de sevrage plus légers. La paroxétine (Paxil) a la demi-vie la plus courte parmi les ISRS courants et provoque les symptômes de sevrage les plus marqués. La sertraline, le citalopram et l\'escitalopram se situent entre les deux.';

  @override
  String get ssriReferenceDay7 =>
      'Une semaine après l\'arrêt des ISRS : la phase aiguë\n\nSource : NHS — Stopping or coming off antidepressants\n\nLa phase aiguë du sevrage\nLe NHS indique que la plupart des symptômes de sevrage des antidépresseurs commencent dans les cinq jours suivant l\'arrêt et durent jusqu\'à six semaines dans la majorité des cas. Au bout d\'une semaine, les symptômes physiques aigus sont généralement parmi les plus marqués et commencent à diminuer chez les personnes ayant réduit progressivement leur dose.\n\nÀ quoi s\'attendre après une semaine\n• les symptômes physiques — nausées, vertiges, sensations pseudo-grippales — sont souvent les plus intenses, mais devraient commencer à s\'atténuer\n• les troubles du sommeil, notamment les rêves très vifs ou l\'insomnie, sont fréquents\n• la labilité émotionnelle, avec des changements rapides d\'humeur, est fréquente à ce stade\n• les « décharges cérébrales » peuvent encore être présentes, mais commencent généralement à devenir moins fréquentes\n\nLe rôle de la diminution progressive\nLe NHS recommande vivement une diminution lente — parfois étalée sur plusieurs mois chez les personnes traitées longtemps — afin de réduire les effets du sevrage. Le Royal College of Psychiatrists a élaboré des recommandations proposant des réductions de dose très progressives, parfois à l\'aide de formulations liquides, pour les personnes ayant pris des ISRS pendant une période prolongée.';

  @override
  String get ssriReferenceDay14 =>
      'Deux semaines après l\'arrêt des ISRS : les symptômes physiques diminuent\n\nSource : Davies & Read (2019), Addictive Behaviors — « A systematic review into the incidence, severity and duration of antidepressant withdrawal effects »\n\nCe que la recherche a constaté\nCette revue systématique de référence a constaté qu\'environ 56 % des personnes arrêtant un antidépresseur présentent des effets de sevrage et que 46 % d\'entre elles les décrivent comme sévères. Pour la plupart des personnes suivant une diminution progressive adaptée, la phase aiguë est largement résolue au bout de deux semaines :\n• les décharges cérébrales ont nettement diminué ou ont disparu\n• les nausées et les symptômes pseudo-grippaux sont résolus\n• les vertiges et les troubles de l\'équilibre s\'améliorent\n• le sommeil commence à se normaliser\n\nDistinguer le sevrage d\'une rechute\nLes symptômes qui apparaissent dans les jours suivant l\'arrêt et correspondent au profil FINISH sont très probablement liés au sevrage. Ceux qui apparaissent après deux à quatre semaines et ressemblent au trouble initialement traité sont davantage susceptibles de signaler une rechute. Il est important de surveiller cette distinction avec votre prescripteur.';

  @override
  String get ssriReferenceDay30 =>
      'Un mois après l\'arrêt des ISRS : stabilisation\n\nSource : Haddad PM (2001), Drug Safety — « Antidepressant Discontinuation Syndromes »\n\nLa phase de stabilisation\nCette revue décrit un début rapide du syndrome de sevrage, généralement dans les jours suivant l\'arrêt ou la réduction d\'un antidépresseur, et précise que la plupart des réactions sont légères et de courte durée, puis disparaissent sans traitement spécifique. Un mois marque le passage de cette fenêtre aiguë à une phase de stabilisation ; pour la plupart des personnes ayant terminé une diminution progressive, les symptômes aigus de sevrage sont désormais largement résolus.\n\nLe paysage émotionnel à un mois\nLes changements émotionnels observés après un mois varient d\'une personne à l\'autre et méritent d\'être surveillés :\n• certaines personnes se sentent d\'abord émotionnellement plus « à plat » pendant que le cerveau s\'adapte ; cela s\'améliore généralement\n• d\'autres retrouvent une intensité émotionnelle qu\'elles n\'avaient pas ressentie depuis des années\n• le niveau d\'anxiété varie fortement selon la personne et le trouble sous-jacent\n\nL\'intérêt d\'un soutien non médicamenteux\nLes recherches montrent de façon constante que les psychothérapies, notamment les thérapies cognitivo-comportementales (TCC) et d\'autres approches psychologiques fondées sur les preuves, sont très efficaces pour les troubles traités par les ISRS. Le cap d\'un mois est un excellent moment pour vérifier que ces soutiens sont bien en place.';

  @override
  String get ssriReferenceDay90 =>
      'Trois mois après l\'arrêt des ISRS : le sevrage est largement derrière vous\n\nSource : « Antidepressant Withdrawal Syndrome », Therapeutics Letter 112 (2018), Therapeutics Initiative, sur NCBI Bookshelf\n\nOù en est-on à trois mois\nCette revue des données indique que les symptômes de sevrage des antidépresseurs « apparaissent généralement dans les quelques jours suivant l\'arrêt ou la réduction de la dose » et que « la plupart des symptômes de sevrage des antidépresseurs disparaissent en deux semaines », même si les cas sévères peuvent durer plusieurs semaines ou plusieurs mois. Au bout de trois mois, la phase aiguë du sevrage est largement terminée pour la grande majorité des personnes.\n\nPourquoi les ISRS diffèrent\nLe sevrage est plus probable avec les ISRS à demi-vie courte, comme la paroxétine, qu\'avec ceux à demi-vie longue, comme la fluoxétine. La Letter indique clairement que les réactions de sevrage peuvent être importantes : deux revues systématiques les ont jugées « très similaires » à celles des benzodiazépines, et elles surviennent chez au moins un tiers des personnes qui arrêtent.\n\nCe que l\'on peut réellement dire de la « récupération des récepteurs »\nOn rencontre parfois l\'affirmation selon laquelle les récepteurs de la sérotonine seraient « complètement resensibilisés en deux à trois mois ». Les données solides portent sur le syndrome de sevrage et sa durée, pas sur une horloge précise de récupération des récepteurs. Ce qui est fiable, c\'est qu\'à trois mois le sevrage est généralement résolu et que de nombreuses personnes constatent, après l\'arrêt, une diminution de l\'émoussement émotionnel et des effets indésirables sexuels qu\'elles pouvaient ressentir sous ISRS.\n\nSi des symptômes persistent\nLa Letter recommande de distinguer le sevrage d\'un véritable retour du trouble sous-jacent. Si une baisse de moral ou de l\'anxiété persiste à trois mois, il vaut mieux en faire le point avec votre prescripteur que supposer qu\'il s\'agit « seulement du sevrage ».';

  @override
  String get ssriReferenceDay180 =>
      'Six mois après l\'arrêt des ISRS : une vision réaliste\n\nSource : « Antidepressant Withdrawal Syndrome », Therapeutics Letter 112 (2018), Therapeutics Initiative, sur NCBI Bookshelf\n\nCe qui est bien établi à six mois\nCette revue indique que même les symptômes de sevrage sévères et prolongés durent généralement des semaines à des mois plutôt qu\'indéfiniment. Au bout de six mois, le syndrome de sevrage aigu est donc clairement résolu pour la grande majorité des personnes.\n\nCe qu\'il faut dire avec prudence\nÀ six mois, la période habituelle de sevrage est largement derrière vous et le système sérotoninergique a eu plusieurs mois pour se stabiliser. Les effets indésirables sexuels s\'améliorent généralement après l\'arrêt ; s\'ils persistent, parlez-en à votre prescripteur.\n\nCe que les personnes rapportent souvent\n• une palette émotionnelle plus large que pendant le traitement\n• un sommeil et une énergie améliorés pour la plupart\n• une amélioration graduelle qui se poursuit, même si son rythme varie fortement d\'une personne à l\'autre';

  @override
  String get ssriReferenceDay365 =>
      'Un an après l\'arrêt des ISRS : une récupération mesurée\n\nSource : Duffy et al. (2021), Health Technology Assessment — essai ANTLER\n\nCe que cet essai a réellement constaté\nANTLER a suivi, en soins primaires au Royaume-Uni, des personnes utilisant des antidépresseurs à long terme qui soit poursuivaient leur traitement, soit l\'arrêtaient. Au cours de l\'année suivante, 56 % des personnes ayant arrêté ont rechuté, contre 39 % de celles ayant poursuivi le traitement — soit un risque approximativement deux fois plus élevé — et le groupe ayant arrêté a rapporté en moyenne une qualité de vie légèrement plus faible.\n\nLe tableau complet\nMalgré ce taux de rechute plus élevé, une part importante des personnes ayant arrêté n\'a pas rechuté et est restée en bonne santé sans médicament. Environ un tiers des personnes ayant arrêté ont finalement repris leur antidépresseur : il s\'agit d\'un choix clinique raisonnable, et non d\'un échec.\n\nUn mot sur la suite\nLa dépression et l\'anxiété sont des troubles chroniques chez certaines personnes. Reprendre un médicament si le trouble sous-jacent réapparaît n\'est pas un échec. L\'objectif est le bien-être, et une année d\'arrêt réussi reste un véritable accomplissement, quelle que soit la suite.';

  @override
  String get steroidsReferenceDay1 =>
      'Arrêt des stéroïdes anabolisants : les premiers jours\n\nSource : « Common symptoms associated with usage and cessation of anabolic androgenic steroids in men », Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nLa phase aiguë\nCette revue décrit le sevrage des stéroïdes anabolisants androgènes en deux phases. La première, liée à l\'activation du système nerveux sympathique plutôt qu\'aux taux hormonaux, apparaît dans les un à deux jours suivant l\'arrêt et peut comprendre :\n• maux de tête\n• tremblements\n• palpitations\n• nausées\n\nPourquoi ces symptômes apparaissent\nLes stéroïdes anabolisants freinent aussi la production naturelle de testostérone : le cerveau détecte les stéroïdes et réduit les signaux hormonaux qui stimulent normalement cette production. Cette suppression persiste après l\'arrêt et prépare la seconde phase, plus longue, décrite dans les jalons suivants.\n\nNote de sécurité\nUne dépression peut apparaître pendant le sevrage des stéroïdes et devenir sévère. Demandez un avis médical et une aide urgente en cas de pensées de vous faire du mal. Les cliniciens accompagnent souvent la récupération et certains utilisent des médicaments pour la soutenir.';

  @override
  String get steroidsReferenceDay14 =>
      'Deux semaines sans stéroïdes anabolisants\n\nSource : « Common symptoms associated with usage and cessation of anabolic androgenic steroids in men », Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nLa phase chronique s\'installe\nAu bout de deux semaines, les brefs symptômes sympathiques des premiers jours ont généralement disparu et la deuxième phase décrite par la revue — liée au déficit persistant en testostérone — devient plus visible :\n• fatigue et baisse de moral\n• douleurs musculaires\n• baisse de la libido\n• insomnie et envies de reprendre\n\nToujours dans une phase basse\nLa production naturelle de testostérone met bien plus de deux semaines à se rétablir. Cette phase est donc attendue et ne signifie pas nécessairement qu\'un problème nouveau est apparu.\n\nUn piège connu\nCertains hommes recommencent à utiliser des stéroïdes précisément pour échapper à cette période, ce qui remet le compteur de récupération à zéro au lieu de la terminer. Le soutien d\'un médecin ou d\'un conseiller aide à traverser cette phase plutôt que de tenter de la soulager avec davantage de stéroïdes.';

  @override
  String get steroidsReferenceDay30 =>
      'Un mois : surveiller l’humeur et la récupération hormonale\n\nSource : littérature clinique sur le sevrage des stéroïdes anabolisants\n\nAprès un mois, l’axe hormonal peut encore être supprimé. Un bilan médical permet de suivre la testostérone, les autres hormones, la tension et les lipides. Le repos, l’alimentation et le soutien psychologique sont utiles, mais ne remplacent pas une évaluation clinique.';

  @override
  String get steroidsReferenceDay90 =>
      'Trois mois sans stéroïdes anabolisants\n\nSource : « Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review », sur PubMed\n\nUn bon moment pour une prise de sang\nAu bout de trois mois, le système hormonal a eu le temps de montrer une récupération significative. C\'est un moment utile pour demander à votre médecin de contrôler la testostérone ainsi que les hormones qui en régulent la production.\n\nÀ quoi s\'attendre\nChez beaucoup d\'hommes après trois mois, les taux augmentent mais ne sont pas encore complètement revenus à la normale. L\'humeur et la libido s\'améliorent souvent avant que la testostérone ne se normalise entièrement. Le volume testiculaire et la production de spermatozoïdes récupèrent plus lentement et peuvent continuer à s\'améliorer pendant l\'année suivante. Lorsqu\'une croissance du tissu mammaire — gynécomastie — s\'est produite, elle a peu de chances de régresser sans traitement spécifique.';

  @override
  String get steroidsReferenceDay180 =>
      'Six mois sans stéroïdes anabolisants\n\nSource : « Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review », sur PubMed\n\nCe qu\'indiquent les données\nLa revue rapporte que la LH et la FSH — les hormones qui indiquent aux testicules de produire de la testostérone — récupèrent généralement en trois à six mois environ. Au bout de six mois, la récupération de la testostérone elle-même est également bien avancée.\n\nSi la récupération n\'est pas encore complète\nSi des symptômes de faible testostérone sont encore présents après six mois, un endocrinologue peut rechercher ce qui se passe et discuter des possibilités de traitement au lieu de vous laisser simplement attendre.';

  @override
  String get steroidsReferenceDay365 =>
      'Un an : bilan de santé après les stéroïdes\n\nSource : littérature clinique sur le sevrage des stéroïdes anabolisants\n\nUn an d’abstinence permet souvent de mieux mesurer la récupération hormonale, mais certains effets peuvent durer. Faites contrôler la tension, les lipides, le foie, le cœur et les hormones. L’urgence demeure la sécurité psychique : demandez immédiatement de l’aide en cas d’idées suicidaires.';

  @override
  String get steroidsReferenceDay730 =>
      'Deux ans sans stéroïdes anabolisants\n\nSource : « Anabolic androgenic steroid-induced hypogonadism, a reversible condition in male individuals? A systematic review », sur PubMed\n\nUne nouvelle normalité\nAprès deux ans, vos taux hormonaux reflètent la production naturelle de votre organisme. Chez la plupart des hommes qui récupèrent, l\'humeur, la libido, la force et la motivation sont stables sans stéroïdes.\n\nRécupération hormonale à long terme\nLes recherches montrent que la testostérone récupère sur plusieurs mois, tandis que les hormones qui stimulent les testicules reviennent généralement en trois à six mois. Le volume testiculaire, la production de spermatozoïdes et la libido peuvent continuer à s\'améliorer pendant des mois, voire des années. Après deux ans, des symptômes persistants de faible testostérone doivent être évalués par un spécialiste, et non traités par un nouveau cycle de stéroïdes.';

  @override
  String get tcaReferenceDay3 =>
      'Arrêt des tricycliques : les premiers jours — rebond de l\'acétylcholine\n\nSource : Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — « Antidepressant withdrawal symptoms treated with anticholinergic agents » (rapport de cas, 3 patients)\n\nCe qui distingue l\'arrêt des tricycliques\nLes antidépresseurs tricycliques diffèrent fondamentalement des ISRS et des IRSN par leur mécanisme. En plus de bloquer la recapture de la sérotonine et de la noradrénaline, ils bloquent fortement le système cholinergique de l\'organisme. Lorsque vous les arrêtez, ce système rebondit.\n\nSymptômes du rebond cholinergique\nContrairement au sevrage des ISRS, celui des tricycliques peut provoquer un rebond de l\'acétylcholine :\n• nausées, vomissements et diarrhée\n• salivation excessive et transpiration\n• maux de tête et douleurs musculaires\n• insomnie avec rêves très vifs ou perturbants\n• anxiété et agitation\n\nTricycliques courants et profils\nL\'amitriptyline et l\'imipramine ont les effets anticholinergiques les plus marqués et provoquent généralement le rebond le plus net. La nortriptyline a des effets un peu plus modérés. La clomipramine possède aussi des effets sérotoninergiques importants en plus de son profil anticholinergique.';

  @override
  String get tcaReferenceDay7 =>
      'Une semaine après l\'arrêt des tricycliques : les symptômes cholinergiques s\'atténuent\n\nRécupération du système cholinergique\nLe rebond de l\'acétylcholine atteint généralement son maximum dans les premiers jours puis commence à diminuer nettement au bout d\'une semaine. À mesure que le système cholinergique revient vers son niveau naturel :\n\nCe qui s\'améliore\n• les symptômes digestifs — nausées, crampes, diarrhée — diminuent\n• la transpiration et les symptômes pseudo-grippaux s\'atténuent\n• le sommeil, encore perturbé, commence à se stabiliser\n• la salivation excessive disparaît\n\nSystème nerveux autonome\nLes tricycliques affectent plusieurs fonctions automatiques de l\'organisme — rythme cardiaque, pression artérielle, digestion — par différents mécanismes. Au bout d\'une semaine, les symptômes autonomes les plus intenses, notamment les vertiges au passage en position debout et les variations rapides du rythme cardiaque, commencent à disparaître à mesure que le système nerveux se réadapte.';

  @override
  String get tcaReferenceDay14 =>
      'Deux semaines après l\'arrêt des tricycliques : les effets anticholinergiques s\'inversent\n\nLa charge anticholinergique diminue\nLes tricycliques exercent sur l\'organisme des effets anticholinergiques importants qui touchent plusieurs systèmes. À mesure que cette charge disparaît au cours des deux premières semaines :\n\nBénéfices physiques\n• la sécheresse buccale se résout, avec un retour du fonctionnement normal des glandes salivaires\n• la constipation disparaît à mesure que la motricité intestinale se rétablit naturellement\n• la fonction urinaire se normalise et la rétention que les tricycliques peuvent provoquer se résout\n• la vision floue s\'améliore et les yeux retrouvent une adaptation normale à la lumière\n\nBénéfices pour la pensée et la mémoire\nL\'acétylcholine est essentielle à la mémoire, à l\'attention et à l\'apprentissage. Les voies cholinergiques freinées par les tricycliques récupèrent :\n• la mémoire de travail s\'améliore\n• la vitesse de traitement augmente\n• la clarté mentale revient\n\nBeaucoup de personnes sont surprises de constater à quel point elles s\'étaient habituées au brouillard mental et aux difficultés de mémoire pendant le traitement par tricycliques.';

  @override
  String get tcaReferenceDay30 =>
      'Un mois après l\'arrêt des tricycliques : stabilisation du système nerveux autonome\n\nRécupération cardiaque\nLes tricycliques influencent le rythme cardiaque pendant le traitement par leur action à la fois sur l\'acétylcholine et sur les systèmes nerveux liés à l\'adrénaline. La littérature clinique sur leur arrêt confirme que les symptômes aigus de sevrage — notamment les effets autonomes provoqués par cette « suractivation cholinergique et adrénergique » — sont généralement légers et disparaissent dans la première ou la deuxième semaine après l\'arrêt. Au bout d\'un mois, la plupart des personnes ont largement dépassé cette fenêtre aiguë et peuvent s\'attendre à :\n• un rythme cardiaque qui revient vers son niveau d\'avant le traitement\n• une variabilité de la fréquence cardiaque qui tend vers ses niveaux naturels\n• une régulation de la pression artérielle, auparavant influencée par l\'action du médicament sur les voies adrénergiques, qui continue de se stabiliser\n\nRestauration de l\'architecture du sommeil\nLes tricycliques réduisent fortement le sommeil paradoxal. À mesure que l\'effet anticholinergique disparaît — l\'acétylcholine étant nécessaire au sommeil paradoxal :\n• le sommeil paradoxal revient, parfois avec une période de rêves particulièrement vifs\n• le sommeil lent profond s\'améliore\n• la qualité globale du sommeil et son caractère réparateur sont nettement meilleurs que pendant le traitement par tricycliques';

  @override
  String get tcaReferenceDay90 =>
      'Trois mois après l\'arrêt des tricycliques : les principaux risques sont derrière vous\n\nCe que montrent les données\nUne méta-analyse de 2024 portant sur 103 essais randomisés et 10 590 participants a conclu que, par rapport à un placebo, les tricycliques réduisent bien les symptômes dépressifs, mais qu\'ils s\'accompagnent aussi d\'un risque presque trois fois plus élevé d\'événement indésirable grave (rapport de cotes de 2,78). Les essais eux-mêmes ne suivaient les participants que pendant douze semaines au maximum sous traitement. Il n\'existe donc pas de données contrôlées à long terme sur ce qui se passe après l\'arrêt. Tout ce qui suit repose sur la compréhension clinique générale de la pharmacologie des tricycliques, et non sur un résultat spécifique de ces essais.\n\nLa récupération de plusieurs systèmes\nLes tricycliques agissent sur un éventail plus large de systèmes neurochimiques que les ISRS ou les IRSN :\n• système sérotoninergique : en cours de réadaptation\n• système noradrénergique : en cours de réadaptation\n• système cholinergique : retour progressif à la normale\n• système histaminergique : la sédation de type antihistaminique a disparu\n\nAu bout de trois mois, tous ces systèmes ont eu beaucoup de temps pour récupérer et, tout aussi important, le risque accru d\'événement indésirable grave associé au traitement actif par tricycliques est désormais derrière vous. De nombreuses personnes constatent :\n• une pensée plus claire, en particulier pour la mémoire et l\'attention\n• une humeur plus stable\n• davantage d\'énergie et de motivation\n• moins de sédation et une meilleure vigilance';

  @override
  String get tcaReferenceDay180 =>
      'Six mois après l\'arrêt des tricycliques : récupération du cœur et des fonctions cognitives\n\nCe que montrent les données à long terme\nLa période de sevrage précoce après l\'arrêt des tricycliques est généralement légère et disparaît en une à deux semaines. Six mois après une diminution progressive supervisée, les effets des tricycliques sur le rythme cardiaque, la mémoire et la pensée ont eu plusieurs mois pour récupérer.\n\nRécupération cardiovasculaire\nAu bout de six mois, les effets directs des tricycliques sur le rythme cardiaque devraient être résolus depuis longtemps :\n• maintien d\'un rythme cardiaque normal sans influence pharmacologique\n• variabilité de la fréquence cardiaque — une mesure de la capacité d\'adaptation du cœur — qui devrait s\'être nettement améliorée\n• disparition complète des vertiges au passage en position debout\n\nRécupération de la pensée et de la mémoire\nLes tricycliques peuvent provoquer un brouillard mental et des troubles de mémoire en bloquant l\'acétylcholine, en particulier chez les personnes âgées. Ces effets s\'améliorent après l\'arrêt du médicament. À six mois :\n• la consolidation de la mémoire s\'est nettement améliorée\n• la vitesse de traitement s\'est normalisée\n• la planification, la mémoire de travail et la capacité à passer d\'une tâche ou d\'une idée à une autre ont récupéré de manière significative';

  @override
  String get tcaReferenceDay365 =>
      'Un an après les tricycliques : le rétablissement est accompli\n\nUn an : récupération complète de plusieurs systèmes\nCette revue des syndromes de sevrage des antidépresseurs — couvrant les tricycliques, les IMAO, les ISRS et d\'autres classes — a constaté que les symptômes commencent généralement dans les jours suivant l\'arrêt et que, sans traitement, ils disparaissent spontanément en quelques jours à environ deux semaines. Aucune étude n\'a spécifiquement réévalué, un an plus tard, les systèmes affectés par les tricycliques. Cependant, un an après la fin d\'une diminution progressive représente de nombreux mois au-delà même des symptômes de sevrage les plus longs rapportés : tous les systèmes neurochimiques concernés — sérotonine, noradrénaline, acétylcholine et histamine — ont donc eu largement le temps de suivre un cycle complet de normalisation.\n\nL\'importance du rétablissement après les tricycliques\nLes tricycliques imposent une charge pharmacologique plus large que les antidépresseurs récents, car ils agissent simultanément sur davantage de systèmes de récepteurs. Un arrêt réussi correspond au rétablissement de plusieurs systèmes :\n• inversion complète des troubles de la mémoire et de la pensée provoqués par le blocage de l\'acétylcholine par les tricycliques\n• récupération complète du cœur\n• retour d\'une régulation neurochimique naturelle dans l\'ensemble des voies concernées\n\nUne année entière d\'autorégulation réussie après l\'arrêt d\'un tricyclique représente un véritable accomplissement, tant pour la gestion du processus de sevrage que pour le maintien du bien-être sans soutien pharmacologique continu.';
}
